/**
 * Review reproducer F1: a context that module code installed and then switched away from inside a
 * command must not stay reusable for the rest of the transaction.
 *
 * esig.sign installs the co-signer's context (iam.set_internal_actor) for the co-signature's own
 * audit entries and then restores the performer's context (kernel.set_actor_context). If the
 * co-signer's marker survives until commit, the application role can bring that context back with
 * set_config('ebmr.ctx', ...) and attribute further writes to the co-signer: a person paired with
 * the performer's session (which begin_command refuses, EBMR-IAM-111) and an authentication event
 * already consumed by the signature (INV-40).
 *
 * Safe behaviour asserted here: after the co-signature, the reinstalled co-signer context is not the
 * validated actor (kernel.current_actor() is NULL, iam.assert_validated_actor() refuses with
 * EBMR-IAM-002) and an audited write under it is refused (EBMR-AUDIT-009), so nothing is committed
 * in the co-signer's name.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type pg from 'pg';
import { toDbContext } from '../../src/db/command.ts';
import { sign } from '../../src/esig/signing.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { challengeFor, cmd, createStub, ensureSealKey, signatureAuth, signStub, testActor, testSealKey } from '../esig/helpers.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
});

afterAll(async () => {
  await db.drop();
});

const codeOf = (e: unknown): string => {
  const m = e instanceof Error ? e.message : String(e);
  return m.match(/EBMR-[A-Z]+-\d+/)?.[0] ?? `UNEXPECTED: ${m}`;
};

async function attempt<T>(c: pg.PoolClient, name: string, work: () => Promise<T>): Promise<{ ok: true; value: T } | { ok: false; code: string }> {
  await c.query(`savepoint ${name}`);
  try {
    const value = await work();
    await c.query(`release savepoint ${name}`);
    return { ok: true, value };
  } catch (e) {
    await c.query(`rollback to savepoint ${name}`);
    return { ok: false, code: codeOf(e) };
  }
}

describe('F1: a co-signer\'s context cannot be reinstalled after the co-signature', () => {
  it('[INV-40][INV-07][DI-22][DI-14][DI-13] bypass: after a co-signature, set_config back to the co-signer\'s context is refused and attributes nothing to the co-signer', async () => {
    const performer = await testActor(db, { deviceClass: 'SHARED', withPin: true, legalName: 'Kiosk Performer F1' });
    const verifier = await testActor(db, { roleCode: 'VERIFIER', deviceClass: 'SHARED', withPin: true, legalName: 'Kiosk Verifier F1' });
    const stubId = await createStub(db, performer);
    await signStub(db, performer, stubId, { meaning: 'PERFORMED', method: 'BADGE_PIN' });

    // Sanity: the kernel never validates the verifier's person with the performer's session.
    {
      const c0 = await db.app.connect();
      try {
        await c0.query('begin');
        const mixed = toDbContext({ ...performer, personId: verifier.personId, accountId: verifier.accountId, roleCode: 'VERIFIER', legalName: 'Kiosk Verifier F1' });
        const r = await attempt(c0, 'mixed', () => c0.query('select kernel.begin_command($1::jsonb)', [JSON.stringify(mixed)]));
        expect(r).toEqual({ ok: false, code: 'EBMR-IAM-111' });
      } finally {
        await c0.query('rollback');
        c0.release();
      }
    }

    // The verifier co-signs at the performer's kiosk with their own badge and PIN.
    const ch = await challengeFor(db, performer, stubId, { meaning: 'VERIFIED', signer: verifier });
    expect(ch.cosignature).toBe(true);
    const verifierEvent = await signatureAuth(db, verifier, performer, ch.challengeId, 'BADGE_PIN');
    const performerCtx = await cmd(db, performer); // the performer's own fresh badge tap (INV-40)

    const observed: Record<string, unknown> = {};
    let forgedStubId: string | null = null;
    const c = await db.app.connect();
    try {
      await c.query('begin');
      await c.query('select kernel.begin_command($1::jsonb)', [JSON.stringify(toDbContext(performerCtx))]);
      const sig = await sign(c, { challengeId: ch.challengeId, authEventId: verifierEvent, expectedState: 'OPEN' }, testSealKey);
      expect(sig.cosignature).toBe(true);
      // esig.sign restored the performer's context.
      const back = await c.query<{ p: string }>("select iam.assert_validated_actor() ->> 'person_id' as p");
      expect(back.rows[0]?.p).toBe(performer.personId);

      // Everything the application needs to rebuild the co-signer's context: its own context plus
      // the actor recorded on the signature's audit entry (readable by ebmr_app).
      const { rows: evRows } = await c.query<{ actor: Record<string, string> }>(
        "select payload -> 'actor' as actor from kernel.audit_event where table_name = 'esig.signature' and record_id = $1", [sig.signatureId]);
      const a = evRows[0]?.actor ?? {};
      expect(a['person_id']).toBe(verifier.personId);
      const overlay = { person_id: a['person_id'], account_id: a['account_id'], role_code: a['role_code'], auth_event_id: a['auth_event_id'], legal_name: a['legal_name'] };
      await c.query("select set_config('ebmr.ctx', (current_setting('ebmr.ctx')::jsonb || $1::jsonb)::text, true)", [JSON.stringify(overlay)]);

      // 1. The reinstalled context must not be read as the actor.
      const cur = await c.query<{ a: Record<string, string> | null }>('select kernel.current_actor() as a');
      observed['currentActorPerson'] = cur.rows[0]?.a?.['person_id'] ?? null;

      // 2. The identity module must refuse it.
      const asserted = await attempt(c, 'assert_actor', () => c.query<{ p: string }>("select iam.assert_validated_actor() ->> 'person_id' as p"));
      observed['assertValidatedActor'] = asserted.ok ? `ACCEPTED as ${asserted.value.rows[0]?.p}` : asserted.code;

      // 3. An audited GMP write under it must be refused.
      const ins = await attempt(c, 'forged_write', () =>
        c.query<{ id: string }>("insert into esig.stub_signable (kind, title, value, unit) values ('STEP', 'forged entry', '99', 'kg') returning id"));
      if (ins.ok) {
        forgedStubId = ins.value.rows[0]?.id ?? null;
        observed['forgedInsert'] = 'ACCEPTED';
      } else {
        observed['forgedInsert'] = ins.code;
      }
      await c.query('commit');
    } catch (e) {
      await c.query('rollback');
      throw e;
    } finally {
      c.release();
    }

    // What was committed in the verifier's name (nothing, if the guarantee holds).
    let committedForgery: unknown = null;
    if (forgedStubId) {
      const { rows } = await db.admin.query<{ person: string; role: string; session: string; ev: string }>(
        `select e.payload -> 'actor' ->> 'person_id' as person, e.payload -> 'actor' ->> 'role_code' as role,
                e.payload -> 'actor' ->> 'session_id' as session, e.payload -> 'actor' ->> 'auth_event_id' as ev
           from kernel.audit_event e where e.table_name = 'esig.stub_signable' and e.record_id = $1`, [forgedStubId]);
      const r = rows[0];
      committedForgery = r
        ? {
            attributedToVerifier: r.person === verifier.personId,
            role: r.role,
            inPerformersSession: r.session === performer.sessionId,
            reusedConsumedSignatureEvent: r.ev === verifierEvent,
          }
        : 'row committed without audit event';
    }
    observed['committedForgery'] = committedForgery;

    expect(observed).toEqual({
      currentActorPerson: null,
      assertValidatedActor: 'EBMR-IAM-002',
      forgedInsert: 'EBMR-AUDIT-009',
      committedForgery: null,
    });
  });
});

/**
 * Review reproducer F2: kernel.verify_chain must bind the stored audit_event.table_name and
 * record_id columns to the hashed payload ('table' and 'record_id').
 *
 * The payload hash covers 'table' and 'record_id', and consumers (record-level audit-trail lookups
 * through the audit_event_record index, iam.record_entry_persons, esig integrity, DI extracts, time
 * anomaly windows) read the unhashed columns. If verify_chain only compares seq, chain_key, action,
 * correlation_id and recorded_at, a direct UPDATE of table_name / record_id (no trigger stops it)
 * moves an entry out of a record's audit trail without any verifier noticing.
 *
 * Safe behaviour asserted here (DI-23 catalog test: change an audit row directly in the DB, the
 * verification job alarms and names the entry): after the columns of seq 2 are rewritten, either to
 * other values or to NULL, verify_chain reports a problem at seq 2.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { verifyAnchor, verifyChain } from '../../src/audit/verify.ts';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';

let db: TestDatabase;
let base: ActorContext;

beforeAll(async () => {
  db = await createTestDatabase();
  base = await seededTestActor(db, { legalName: 'F2 Operator' });
});

afterAll(async () => {
  await db.drop();
});

const actor = (): ActorContext => ({ ...base, correlationId: randomUUID() });

async function insertSample(batchId: string, value: string): Promise<string> {
  return withCommand(db.app, actor(), async (c) => {
    const { rows } = await c.query<{ id: string }>('insert into testgmp.sample (batch_id, value) values ($1, $2) returning id', [batchId, value]);
    return rows[0]?.id ?? '';
  });
}

/** The record's audit trail as consumers read it: by the indexed (table_name, record_id) columns. */
async function recordTrail(table: string, recordId: string): Promise<number[]> {
  const { rows } = await db.app.query<{ seq: string }>(
    'select seq from kernel.audit_event where table_name = $1 and record_id = $2 order by seq',
    [table, recordId],
  );
  return rows.map((r) => Number(r.seq));
}

describe('F2: audit_event.table_name and record_id are bound to the hashed payload', () => {
  it('[INV-08][DI-23][INV-07] rewriting table_name/record_id of an audit row directly in the database is detected by verify_chain and the entry is named', async () => {
    // Case A: the columns are rewritten to other values.
    const batch = randomUUID();
    const key = `batch:${batch}`;
    await insertSample(batch, '1');
    const victim = await insertSample(batch, '2');
    await insertSample(batch, '3');
    expect(await verifyChain(db.app, key)).toEqual([]);
    expect(await recordTrail('testgmp.sample', victim)).toEqual([2]);

    const { rows: anchorRows } = await db.app.query<{ id: string }>('select kernel.create_anchor() as id');
    const anchorId = Number(anchorRows[0]?.id);

    const { rows: before } = await db.admin.query<{ table_name: string; record_id: string; p_table: string; p_record: string }>(
      "select table_name, record_id, payload->>'table' as p_table, payload->>'record_id' as p_record from kernel.audit_event where chain_key = $1 and seq = 2",
      [key],
    );
    expect(before[0]).toEqual({ table_name: 'testgmp.sample', record_id: victim, p_table: 'testgmp.sample', p_record: victim });

    // Superuser (DBA / break-glass) rewrites the unhashed columns; no trigger refuses the UPDATE.
    const upd = await db.admin.query(
      "update kernel.audit_event set table_name = 'testgmp.reading', record_id = 'other' where chain_key = $1 and seq = 2",
      [key],
    );
    expect(upd.rowCount).toBe(1);
    // The entry has dropped out of the record's audit trail.
    expect(await recordTrail('testgmp.sample', victim)).toEqual([]);

    const anchorProblems = (await verifyAnchor(db.app, anchorId)).filter((p) => p.includes(key));
    const problemsA = await verifyChain(db.app, key);
    console.log('F2 case A verify_chain:', JSON.stringify(problemsA), 'verify_anchor (this chain):', JSON.stringify(anchorProblems));

    // Case B: the columns are set to NULL (a NULL must not hide a mismatch).
    const batchB = randomUUID();
    const keyB = `batch:${batchB}`;
    await insertSample(batchB, '1');
    const victimB = await insertSample(batchB, '2');
    expect(await verifyChain(db.app, keyB)).toEqual([]);
    await db.admin.query('update kernel.audit_event set table_name = null, record_id = null where chain_key = $1 and seq = 2', [keyB]);
    expect(await recordTrail('testgmp.sample', victimB)).toEqual([]);
    const problemsB = await verifyChain(db.app, keyB);
    console.log('F2 case B verify_chain:', JSON.stringify(problemsB));

    // Safe behaviour: the verifier alarms and names the altered entry in both cases.
    expect(problemsA.map((p) => p.seq), 'rewritten table_name/record_id not reported by verify_chain').toContain(2);
    expect(problemsB.map((p) => p.seq), 'NULLed table_name/record_id not reported by verify_chain').toContain(2);
  });
});

/**
 * Review reproducer F3: whole-database audit verification must not lose a chain because its head
 * row is missing.
 *
 * verifyAllChains (src/audit/verify.ts) takes its list of chains from kernel.audit_chain_head, and
 * kernel.verify_chain compares the head only "if found". A person with database rights who alters
 * an audit event and then deletes that chain's head row therefore removes the chain from the
 * whole-database verification, although its events are still in kernel.audit_event.
 *
 * Safe behaviour asserted here (INV-08, DI-23): after an event of a chain is altered and the chain's
 * head row is deleted, verifyAllChains still reports a problem for that chain, because the events
 * are still there and do not verify (and the head is gone).
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { verifyAllChains, verifyChain } from '../../src/audit/verify.ts';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';

let db: TestDatabase;
let base: ActorContext;

beforeAll(async () => {
  db = await createTestDatabase();
  base = await seededTestActor(db, { legalName: 'F3 Operator' });
});

afterAll(async () => {
  await db.drop();
});

async function insertSample(batchId: string, value: string): Promise<void> {
  await withCommand(db.app, { ...base, correlationId: randomUUID() }, (c) =>
    c.query('insert into testgmp.sample (batch_id, value) values ($1, $2)', [batchId, value]),
  );
}

describe('F3: whole-database verification covers every chain that has events', () => {
  it('[INV-08][DI-23] tamper: an altered chain whose head row was deleted is still reported by verifyAllChains', async () => {
    const batch = randomUUID();
    const key = `batch:${batch}`;
    for (const v of ['1', '2', '3']) await insertSample(batch, v);

    const mine = async () => (await verifyAllChains(db.app)).filter((p) => p.chainKey === key);

    // Intact chain: nothing reported.
    expect(await mine()).toEqual([]);

    // Superuser alters event 2 without recomputing any hash.
    await db.admin.query("update kernel.audit_event set payload = jsonb_set(payload, '{body,new,value}', '42') where chain_key = $1 and seq = 2", [key]);

    // Sanity: with the head row present, the whole-database job does see the alteration.
    expect((await mine()).map((p) => `${p.seq}: ${p.problem}`)).toContain('2: hash does not match the payload (event altered)');

    // Superuser now deletes the chain's head row.
    const del = await db.admin.query('delete from kernel.audit_chain_head where chain_key = $1', [key]);
    expect(del.rowCount).toBe(1);

    // Precondition: the events are still there and a direct check of this chain still finds the alteration.
    const { rows } = await db.admin.query<{ n: string }>('select count(*)::text as n from kernel.audit_event where chain_key = $1', [key]);
    expect(rows[0]?.n).toBe('3');
    expect((await verifyChain(db.app, key)).map((p) => `${p.seq}: ${p.problem}`)).toContain('2: hash does not match the payload (event altered)');

    // Safe behaviour: the whole-database verification still reports this chain.
    const reported = await mine();
    expect(reported.length, `verifyAllChains reported nothing for ${key} after its head row was deleted`).toBeGreaterThan(0);
    expect(reported.map((p) => `${p.seq}: ${p.problem}`)).toContain('2: hash does not match the payload (event altered)');
  });
});

/**
 * Review reproducer F4: dropping an insert-only guard trigger must not go unseen.
 *
 * kernel.register_audited_table gives every insert-only table two guards besides the audit trigger:
 * aa_insert_only_* (BEFORE UPDATE OR DELETE -> kernel.reject_mutation, EBMR-AUDIT-004) and
 * aa_no_truncate_*. ADR-0007 and 0010_audit_trail.sql say an event trigger records DDL so that a
 * disabled trigger or altered table is visible afterwards (kernel.ddl_log), and DI-23 says GMP writes
 * are refused while the trail's protection is missing (kernel.audit_triggers_ok, EBMR-AUDIT-005).
 *
 * kernel.log_ddl only reads pg_event_trigger_ddl_commands() on ddl_command_end; PostgreSQL reports
 * no commands there for DROP statements, and nothing listens on sql_drop. audit_triggers_ok only
 * looks at zz_audit_*. So a DROP TRIGGER of the insert-only guard leaves no DDL log row, begin_command
 * still accepts GMP writes, and a registered insert-only row can be updated (INV-06).
 *
 * Safe behaviour asserted here, after a superuser drops aa_insert_only_testgmp_reading:
 *   - kernel.ddl_log has a new row for the DROP TRIGGER;
 *   - kernel.audit_triggers_ok() (or begin_command) reports the missing guard;
 *   - a GMP command that updates an insert-only row is refused and the row is unchanged.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';

let db: TestDatabase;
let base: ActorContext;

beforeAll(async () => {
  db = await createTestDatabase();
  base = await seededTestActor(db, { legalName: 'Test Operator F4' });
});

afterAll(async () => {
  await db.drop();
});

const actor = (overrides: Partial<ActorContext> = {}): ActorContext => ({ ...base, correlationId: randomUUID(), ...overrides });

const codeOf = (e: unknown): string => {
  const m = e instanceof Error ? e.message : String(e);
  return m.match(/EBMR-[A-Z]+-\d+/)?.[0] ?? `UNEXPECTED: ${m}`;
};

describe('F4: dropping an insert-only guard trigger is recorded and stops GMP writes', () => {
  it('[DI-23][INV-06] after DROP TRIGGER aa_insert_only_*, kernel.ddl_log records it, audit_triggers_ok is false and an update of an insert-only row is refused', async () => {
    const batch = randomUUID();
    await withCommand(db.app, actor(), (c) => c.query('insert into testgmp.reading (batch_id, value) values ($1, 7)', [batch]));

    // Sanity: with the guard in place, the insert-only row cannot be changed even with a reason (EBMR-AUDIT-004).
    await expect(withCommand(db.app, actor({ reasonCode: 'CORRECTION' }), (c) => c.query('update testgmp.reading set value = 8 where batch_id = $1', [batch]))).rejects.toThrow(
      'EBMR-AUDIT-004',
    );
    // Sanity: the trail reports healthy before the drop.
    const { rows: okBefore } = await db.app.query<{ ok: boolean }>('select kernel.audit_triggers_ok() as ok');
    expect(okBefore[0]?.ok).toBe(true);

    const { rows: before } = await db.admin.query<{ max: string }>('select coalesce(max(id), 0)::text as max from kernel.ddl_log');
    const beforeId = before[0]?.max ?? '0';

    // A superuser (or the owner) removes the insert-only guard.
    await db.admin.query('drop trigger aa_insert_only_testgmp_reading on testgmp.reading');
    try {
      const observed: Record<string, unknown> = {};

      // 1. The DROP must leave a row in kernel.ddl_log.
      const { rows: logged } = await db.app.query<{ command_tag: string; object_identity: string | null }>(
        `select command_tag, object_identity from kernel.ddl_log
          where id > $1::bigint
            and (command_tag = 'DROP TRIGGER' or object_identity like '%aa_insert_only_testgmp_reading%')`,
        [beforeId],
      );
      observed['ddlLogRecordsDropTrigger'] = logged.length > 0;

      // 2. The start-of-command check must see that the guard is gone.
      const { rows: okAfter } = await db.app.query<{ ok: boolean }>('select kernel.audit_triggers_ok() as ok');
      observed['auditTriggersOkAfterDrop'] = okAfter[0]?.ok;

      // 3. A GMP command (with a reason, so EBMR-AUDIT-002 does not mask the result) must not be
      //    able to change the insert-only row.
      let updateOutcome: string;
      try {
        await withCommand(db.app, actor({ reasonCode: 'CORRECTION' }), (c) => c.query('update testgmp.reading set value = 8 where batch_id = $1', [batch]));
        updateOutcome = 'COMMITTED';
      } catch (e) {
        updateOutcome = `REFUSED ${codeOf(e)}`;
      }
      observed['updateOfInsertOnlyRowRefused'] = updateOutcome.startsWith('REFUSED EBMR-');
      const { rows: value } = await db.admin.query<{ value: string }>('select value::text as value from testgmp.reading where batch_id = $1', [batch]);
      observed['insertOnlyValueAfterAttempt'] = value[0]?.value;

      expect(observed, `update outcome: ${updateOutcome}`).toEqual({
        ddlLogRecordsDropTrigger: true,
        auditTriggersOkAfterDrop: false,
        updateOfInsertOnlyRowRefused: true,
        insertOnlyValueAfterAttempt: '7',
      });
    } finally {
      await db.admin.query(
        'create trigger aa_insert_only_testgmp_reading before update or delete on testgmp.reading for each row execute function kernel.reject_mutation()',
      );
    }
  });
});

/**
 * Review reproducer F5: the site zone and the printed name in an audit entry must be the server's,
 * not whatever the client put in the actor context.
 *
 * kernel.append_audit_event (0010) copies 'site_zone' and actor 'legal_name' straight from the
 * validated context. kernel.begin_command only requires site_zone to be non-empty, and the live
 * kernel.validate_actor_context (0190) never compares it with iam.policy_text('site.zone'); it checks
 * legal_name only when the context carries one. DI-22 / INV-07 require every entry to hold the
 * server time with the site zone (UTC plus site offset) and the printed full name at the time.
 *
 * Safe behaviour asserted here, for a real seeded operator on a PERSONAL device:
 *   - baseline: a correct context is accepted and its entry carries the policy zone and the name;
 *   - (A) a context declaring a zone other than the site policy zone is either refused, or the entry
 *     it writes still carries the site policy zone;
 *   - (B) a context that omits legal_name is either refused, or the entry it writes still carries the
 *     person's legal name (filled by the server).
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
});

afterAll(async () => {
  await db.drop();
});

const FOREIGN_ZONE = 'Pacific/Kiritimati';

const codeOf = (e: unknown): string => {
  const m = e instanceof Error ? e.message : String(e);
  return m.match(/EBMR-[A-Z]+-\d+/)?.[0] ?? `UNEXPECTED: ${m}`;
};

interface Entry {
  site_zone: string | null;
  legal_name: string | null;
  person_id: string | null;
  local_in_entry_zone: string;
  local_in_site_zone: string;
}

type Outcome = { refused: string } | { entry: Entry };

async function insertUnder(ctx: ActorContext): Promise<Outcome> {
  const batch = randomUUID();
  try {
    await withCommand(db.app, ctx, (c) => c.query('insert into testgmp.sample (batch_id, value) values ($1, 7.25)', [batch]));
  } catch (e) {
    return { refused: codeOf(e) };
  }
  const { rows } = await db.admin.query<Entry>(
    `select e.payload ->> 'site_zone' as site_zone,
            e.payload -> 'actor' ->> 'legal_name' as legal_name,
            e.payload -> 'actor' ->> 'person_id' as person_id,
            to_char(e.recorded_at at time zone (e.payload ->> 'site_zone'), 'YYYY-MM-DD HH24:MI') as local_in_entry_zone,
            to_char(e.recorded_at at time zone iam.policy_text('site.zone'), 'YYYY-MM-DD HH24:MI') as local_in_site_zone
       from kernel.audit_event e
      where e.chain_key = $1 and e.action = 'INSERT'`,
    [`batch:${batch}`],
  );
  expect(rows).toHaveLength(1);
  return { entry: rows[0] as Entry };
}

describe('F5: audit entries carry the server site zone and the printed name, not client-supplied values', () => {
  it('[DI-22][INV-07] an audit entry never carries a site zone other than the site policy zone, nor a missing printed name', async () => {
    const operator = await seededTestActor(db, { legalName: 'Review Operator F5' });
    const { rows: pol } = await db.admin.query<{ zone: string }>("select iam.policy_text('site.zone') as zone");
    const siteZone = pol[0]?.zone ?? '';
    const { rows: per } = await db.admin.query<{ legal_name: string }>('select legal_name from iam.person where id = $1', [operator.personId]);
    const personName = per[0]?.legal_name ?? '';

    // Preconditions: the seeded operator declares the site's own zone and name; the foreign zone differs.
    expect(siteZone).toBe('Asia/Kolkata');
    expect(operator.siteZone).toBe(siteZone);
    expect(personName).toBe('Review Operator F5');
    expect(operator.legalName).toBe(personName);
    expect(FOREIGN_ZONE).not.toBe(siteZone);

    // Baseline: the correct context is accepted and its entry is right (proves the harness works, so a
    // refusal below is caused by the altered field, not by the setup).
    const baseline = await insertUnder({ ...operator, correlationId: randomUUID() });
    expect(baseline).toMatchObject({ entry: { site_zone: siteZone, legal_name: personName, person_id: operator.personId } });

    // (A) The client declares a foreign zone (legal name still correct).
    const a = await insertUnder({ ...operator, siteZone: FOREIGN_ZONE, correlationId: randomUUID() });

    // (B) The client omits the printed name (zone correct).
    const { legalName: _omit, ...noName } = operator;
    void _omit;
    const b = await insertUnder({ ...noName, correlationId: randomUUID() });

    const zoneSafe = 'refused' in a ? /^EBMR-/.test(a.refused) : a.entry.site_zone === siteZone;
    const nameSafe = 'refused' in b ? /^EBMR-/.test(b.refused) : b.entry.legal_name === personName;

    expect(
      { zoneSafe, nameSafe },
      'an audited GMP write under a client-chosen zone or without a printed name must be refused or corrected by the server; ' +
        `site policy zone ${siteZone}, person name ${personName}; observed (A) foreign zone: ${JSON.stringify(a)}; (B) no name: ${JSON.stringify(b)}`,
    ).toEqual({ zoneSafe: true, nameSafe: true });
  });
});

/**
 * Review reproducer F6: the reason-for-change gate of kernel.audit_row_change (0010_audit_trail.sql)
 * must refuse a blank reason, not only a missing one.
 *
 * DI-22 (catalog_test): saving a modification without a reason is blocked. DI-24: a correction records
 * a mandatory reason. Outline 5.4: the "why" of an audit entry is the reason code and text, mandatory for
 * every change or void after first entry. INV-07: every GMP update writes an audit event carrying the
 * reason for the change.
 *
 * The trigger only checks coalesce(reason_code, '') = '', so a reason code of ' ' (whitespace) passes and
 * reason_text is never required. The application role, with a real seeded operator inside a validated
 * kernel.begin_command context, can therefore change or delete a GMP value after first entry and the
 * audit event records no meaningful reason.
 *
 * Safe behaviour asserted here (all through ebmr_app, on the audited fixture table testgmp.sample, which
 * uses the same generic trigger as every non-insert-only GMP table):
 *  - an UPDATE whose reason code is whitespace is refused with EBMR-AUDIT-002;
 *  - an UPDATE with a reason code but no reason text is refused with EBMR-AUDIT-002;
 *  - a DELETE whose reason code is whitespace is refused with EBMR-AUDIT-002;
 *  - the refused attempts leave the rows unchanged and write no UPDATE/DELETE audit event;
 *  - positive control: a reason code with reason text is accepted and audited.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';

let db: TestDatabase;
let base: ActorContext;

beforeAll(async () => {
  db = await createTestDatabase();
  base = await seededTestActor(db, { legalName: 'Test Operator F6' });
});

afterAll(async () => {
  await db.drop();
});

/** The seeded operator in a new command (fresh correlation id), with reason overrides. */
function actor(overrides: Partial<ActorContext> = {}): ActorContext {
  return { ...base, correlationId: randomUUID(), ...overrides };
}

const codeOf = (e: unknown): string => {
  const m = e instanceof Error ? e.message : String(e);
  return m.match(/EBMR-[A-Z]+-\d+/)?.[0] ?? `UNEXPECTED: ${m}`;
};

type Outcome = { ok: true } | { ok: false; code: string };

async function attempt(work: () => Promise<unknown>): Promise<Outcome> {
  try {
    await work();
    return { ok: true };
  } catch (e) {
    return { ok: false, code: codeOf(e) };
  }
}

async function insertSample(batchId: string, value: string): Promise<string> {
  return withCommand(db.app, actor(), async (c) => {
    const { rows } = await c.query<{ id: string }>('insert into testgmp.sample (batch_id, value) values ($1, $2) returning id', [batchId, value]);
    return rows[0]?.id ?? '';
  });
}

async function valueOf(id: string): Promise<string | null> {
  const { rows } = await db.app.query<{ value: string }>('select value::text as value from testgmp.sample where id = $1', [id]);
  return rows[0]?.value ?? null;
}

async function changeEvents(batchId: string) {
  const { rows } = await db.app.query<{ action: string; reason_code: string | null; reason_text: string | null }>(
    `select action, payload ->> 'reason_code' as reason_code, payload ->> 'reason_text' as reason_text
       from kernel.audit_event where chain_key = $1 and action in ('UPDATE', 'DELETE') order by seq`,
    [`batch:${batchId}`],
  );
  return rows;
}

describe('F6: the reason-for-change gate refuses a blank reason', () => {
  it('[DI-22][DI-24][INV-07] a change or delete after first entry with a whitespace reason code or no reason text is refused (EBMR-AUDIT-002)', async () => {
    // Positive control: a reason code with reason text is accepted and recorded.
    const okBatch = randomUUID();
    const okId = await insertSample(okBatch, '10.0');
    await withCommand(db.app, actor({ reasonCode: 'TRANSCRIPTION_ERROR', reasonText: 'wrong digit' }), (c) =>
      c.query('update testgmp.sample set value = 10.5 where id = $1', [okId]),
    );
    expect(await valueOf(okId)).toBe('10.5');
    expect(await changeEvents(okBatch)).toEqual([{ action: 'UPDATE', reason_code: 'TRANSCRIPTION_ERROR', reason_text: 'wrong digit' }]);

    // Sanity: the existing gate refuses a completely missing reason.
    const noneBatch = randomUUID();
    const noneId = await insertSample(noneBatch, '20.0');
    expect(await attempt(() => withCommand(db.app, actor(), (c) => c.query('update testgmp.sample set value = 20.5 where id = $1', [noneId])))).toEqual({
      ok: false,
      code: 'EBMR-AUDIT-002',
    });

    // A: UPDATE with a whitespace-only reason code (reason text present).
    const aBatch = randomUUID();
    const aId = await insertSample(aBatch, '30.0');
    const updateBlankCode = await attempt(() =>
      withCommand(db.app, actor({ reasonCode: ' ', reasonText: 'wrong digit' }), (c) =>
        c.query('update testgmp.sample set value = 30.5 where id = $1', [aId]),
      ),
    );

    // B: UPDATE with a reason code but no reason text.
    const bBatch = randomUUID();
    const bId = await insertSample(bBatch, '40.0');
    const updateNoText = await attempt(() =>
      withCommand(db.app, actor({ reasonCode: 'TRANSCRIPTION_ERROR' }), (c) => c.query('update testgmp.sample set value = 40.5 where id = $1', [bId])),
    );

    // C: DELETE with a whitespace-only reason code and no reason text.
    const cBatch = randomUUID();
    const cId = await insertSample(cBatch, '50.0');
    const deleteBlankCode = await attempt(() =>
      withCommand(db.app, actor({ reasonCode: ' ' }), (c) => c.query('delete from testgmp.sample where id = $1', [cId])),
    );

    const observed = {
      updateBlankCode,
      updateNoText,
      deleteBlankCode,
      valuesAfter: { a: await valueOf(aId), b: await valueOf(bId), c: await valueOf(cId) },
      changeEventsWritten: {
        a: await changeEvents(aBatch),
        b: await changeEvents(bBatch),
        c: await changeEvents(cBatch),
      },
    };

    expect(observed).toEqual({
      updateBlankCode: { ok: false, code: 'EBMR-AUDIT-002' },
      updateNoText: { ok: false, code: 'EBMR-AUDIT-002' },
      deleteBlankCode: { ok: false, code: 'EBMR-AUDIT-002' },
      valuesAfter: { a: '30.0', b: '40.0', c: '50.0' },
      changeEventsWritten: { a: [], b: [], c: [] },
    });
  });
});

/**
 * Review reproducer F11: a routine single-factor badge tap must not reset the failed-attempt
 * counter that drives DI-19 lockout.
 *
 * iam.consecutive_failures (0160) counts FAILURE rows after the most recent SUCCESS of any method
 * or purpose. A BADGE_TAP for COMMAND needs no secret, but it still records a SUCCESS row, so every
 * tap the victim makes while working on a shared terminal sets the count back to zero. An attacker
 * guessing the victim's password then never reaches authn.lockout_threshold.
 *
 * Safe behaviour asserted here: an attacker makes (threshold - 1) wrong password guesses, the victim
 * taps their badge once to attribute an entry, and this repeats for three rounds. The account must
 * lock no later than the threshold-th failed guess, because the taps proved no secret. With the
 * defect the account is still unlocked after three rounds (12 failed guesses at the default
 * threshold of 5), with consecutive_failures back at 0 and no LOCKED event.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { authenticate } from '../../src/identity/authentication.ts';
import { AuthenticationFailedError } from '../../src/identity/errors.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seedActor, seedAdministration, seedAuthn, type SeededActor } from '../identity/seed.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
  await seedAdministration(db);
});

afterAll(async () => {
  await db.drop();
});

const wrongPasswordLogin = (a: SeededActor) =>
  authenticate(seedAuthn(db), {
    method: 'PASSWORD', identifier: a.seed.loginName, secret: 'attacker-guess-not-the-password',
    deviceFingerprint: a.seed.deviceFingerprint, purpose: 'LOGIN',
  });

const badgeTap = (a: SeededActor) =>
  authenticate(seedAuthn(db), { method: 'BADGE_TAP', identifier: a.seed.badgeUid ?? '', deviceFingerprint: a.seed.deviceFingerprint, purpose: 'COMMAND' });

async function lockState(accountId: string): Promise<{ locked: boolean; consecutive: number; failures: number; lockEvents: number }> {
  const { rows } = await db.admin.query<{ locked: boolean; consecutive: number; failures: number; lock_events: number }>(
    `select iam.account_locked($1) as locked,
            iam.consecutive_failures($1)::int as consecutive,
            (select count(*)::int from iam.authn_attempt where account_id = $1 and outcome = 'FAILURE') as failures,
            (select count(*)::int from iam.account_lock_event where account_id = $1 and event = 'LOCKED') as lock_events`,
    [accountId],
  );
  const r = rows[0];
  return { locked: r?.locked ?? false, consecutive: r?.consecutive ?? -1, failures: r?.failures ?? -1, lockEvents: r?.lock_events ?? -1 };
}

describe('F11: a single-factor badge tap does not reset the lockout counter', () => {
  it('[DI-19] failed password guesses interleaved with the victim\'s badge taps still lock the account at the threshold', async () => {
    const threshold = Number(
      (await db.admin.query<{ n: number }>("select iam.policy_int('authn.lockout_threshold')::int as n")).rows[0]?.n,
    );
    expect(threshold).toBeGreaterThanOrEqual(3);
    expect(threshold).toBeLessThanOrEqual(5);

    // An operator on a SHARED terminal: each entry is attributed with a badge tap (INV-40).
    const victim = await seedActor(db, { deviceClass: 'SHARED', legalName: 'Shared Terminal Operator F11' });
    expect(victim.seed.badgeUid).toBeDefined();
    expect(await lockState(victim.accountId)).toMatchObject({ locked: false, failures: 0 });

    // Sanity: a badge tap is a single-factor event that proves no secret.
    const probe = await badgeTap(victim);
    expect(probe).toMatchObject({ purpose: 'COMMAND', components: ['BADGE'], restricted: false });

    let failedGuesses = 0;
    let lockedAtGuess: number | null = null;
    let tapsBetweenGuesses = 0;
    const rounds = 3;
    outer: for (let round = 1; round <= rounds; round++) {
      for (let i = 1; i < threshold; i++) {
        failedGuesses++;
        const err = await wrongPasswordLogin(victim).then(
          () => null,
          (e: unknown) => e,
        );
        expect(err, `guess ${failedGuesses} must fail`).toBeInstanceOf(AuthenticationFailedError);
        const failure = err as AuthenticationFailedError;
        expect(failure.reason).toBe('WRONG_SECRET');
        if (failure.locked) {
          lockedAtGuess = failedGuesses;
          break outer;
        }
      }
      // The victim keeps working: one legitimate badge tap to attribute an entry.
      await badgeTap(victim);
      tapsBetweenGuesses++;
    }

    const state = await lockState(victim.accountId);
    const evidence = `threshold=${threshold} failedGuesses=${failedGuesses} tapsBetweenGuesses=${tapsBetweenGuesses} ` +
      `lockedAtGuess=${String(lockedAtGuess)} state=${JSON.stringify(state)}`;

    // Safe behaviour: the badge taps proved no secret, so the account locks by the threshold-th guess.
    expect(state.locked, `account must be locked after ${failedGuesses} failed password guesses (${evidence})`).toBe(true);
    expect(state.lockEvents, evidence).toBe(1);
    expect(lockedAtGuess, evidence).not.toBeNull();
    expect(lockedAtGuess ?? Infinity, evidence).toBeLessThanOrEqual(threshold);

    // Once locked, the victim's own badge tap is refused too (so the guesses stop being masked).
    await expect(badgeTap(victim)).rejects.toMatchObject({ reason: 'ACCOUNT_LOCKED' });
  });
});

/**
 * Review reproducer F13: independence (DI-35), INV-03 and INV-04 must hold whatever ORDER the
 * signatures are applied in.
 *
 * esig.check_independence (0230) evaluates each rule only for the meaning being signed, against the
 * signatures that already exist. Nothing is checked when the "other side" of a rule is signed later:
 *   - PERFORMED has no exclusions, so a person who already VERIFIED a step can sign PERFORMED on it;
 *   - CHECKED is not independent of APPROVED, so a person who already APPROVED a master document can
 *     CHECK it afterwards (the catalogue says APPROVED is independent of CHECKED; INV-04).
 * esig.stub_complete does not enforce signing order, and esig.invariant_violations() looks only
 * backwards in time for INV-03 and has no independence rule at all.
 *
 * Safe behaviour asserted here, for each scenario: the conflicting pair of signatures by ONE person is
 * either refused at signing, or keeps the entry from being completed, or is reported by
 * esig.invariant_violations(). With the defect all three fail: the entry is COMPLETED with the same
 * person as performer and verifier (resp. checker and approver) and nothing is reported.
 *
 * Positive controls (same people, same roles, forward order) show the rules are enforced one way,
 * so the test setup (roles, grants, signing flow) is correct.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand } from '../../src/db/command.ts';
import { decideRoleGrant, requestRoleGrant } from '../../src/identity/admin.ts';
import { ebmrCode } from '../../src/identity/errors.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seedAdministration, withReason, type SeededActor } from '../identity/seed.ts';
import { createStub, ensureSealKey, expectRefused, run, signStub, testActor } from '../esig/helpers.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
});

afterAll(async () => {
  await db.drop();
});

/** Gives the person's account a second role (requested by the administrator, approved by the process owner). */
async function grantRole(actor: SeededActor, roleCode: string): Promise<void> {
  const { admin, owner } = await seedAdministration(db);
  const grantId = await withCommand(db.app, withReason(admin), (c) => requestRoleGrant(c, { accountId: actor.accountId, roleCode, reason: 'second duty for test' }));
  await withCommand(db.app, withReason(owner), (c) => decideRoleGrant(c, grantId, true, 'approved for test'));
}

const as = (actor: SeededActor, roleCode: string): SeededActor => ({ ...actor, roleCode });

type Attempt<T> = { ok: true; value: T } | { ok: false; code: string | undefined; message: string };

async function attempt<T>(p: Promise<T>): Promise<Attempt<T>> {
  try {
    return { ok: true, value: await p };
  } catch (error) {
    return { ok: false, code: ebmrCode(error), message: error instanceof Error ? error.message : String(error) };
  }
}

/** A refusal that is about the person's independence (not an unrelated setup failure). */
const independenceRefusal = (a: Attempt<unknown>): boolean =>
  !a.ok && /EBMR-ESIG-04[2-9]|INV-03|INV-04|independen|involved|performed|other than/i.test(a.message);

async function violationsFor(signatureIds: string[]): Promise<{ invariant: string; signature_id: string; detail: string }[]> {
  const { rows } = await db.app.query<{ invariant: string; signature_id: string; detail: string }>(
    'select invariant, signature_id, detail from esig.invariant_violations() where signature_id = any($1::uuid[])',
    [signatureIds],
  );
  return rows;
}

async function stubState(id: string): Promise<{ state: string; completed_by_signature: string | null }> {
  const { rows } = await db.app.query<{ state: string; completed_by_signature: string | null }>(
    'select state, completed_by_signature from esig.stub_signable where id = $1',
    [id],
  );
  return rows[0] ?? { state: '(missing)', completed_by_signature: null };
}

const complete = (actor: SeededActor, id: string, signatureId: string) =>
  run(db, actor, (c) => c.query('select esig.stub_complete($1, $2)', [id, signatureId]));

describe('F13: independence rules are enforced whatever order the signatures are applied in', () => {
  it('[INV-03][INV-04][DI-35][DI-17] verify-then-perform and approve-then-check by one person are refused or detected', async () => {
    // ------------------------------------------------------------------------------------------
    // Scenario 1 (INV-03): B verifies a step, then signs PERFORMED on the same step.
    // ------------------------------------------------------------------------------------------
    const a = await testActor(db, { legalName: 'Step Enterer F13' });
    const b = await testActor(db, { roleCode: 'VERIFIER', legalName: 'Verifier And Operator F13' });
    await grantRole(b, 'OPERATOR');

    // Control (forward order): B performs, then B's verification is refused by INV-03.
    const ctlStep = await createStub(db, a, { title: 'Control step F13' });
    await signStub(db, as(b, 'OPERATOR'), ctlStep, { meaning: 'PERFORMED' });
    await expectRefused(signStub(db, b, ctlStep, { meaning: 'VERIFIED' }), 'EBMR-ESIG-044', /INV-03/);

    // Reverse order on a fresh step entered by A.
    const step = await createStub(db, a, { title: 'Granulation: binder added F13' });
    const verified = await signStub(db, b, step, { meaning: 'VERIFIED' });
    expect(await violationsFor([verified.signatureId]), 'baseline: B\'s VERIFIED is clean before B performs').toEqual([]);

    const performed = await attempt(signStub(db, as(b, 'OPERATOR'), step, { meaning: 'PERFORMED' }));
    const completion1 = performed.ok ? await attempt(complete(b, step, verified.signatureId)) : null;
    const state1 = await stubState(step);
    const sigIds1 = [verified.signatureId, ...(performed.ok ? [performed.value.signatureId] : [])];
    const violations1 = await violationsFor(sigIds1);
    const signers1 = (await db.admin.query<{ meaning_code: string; signer_person: string }>(
      'select meaning_code, signer_person from esig.signature where aggregate_ref = $1 order by recorded_at', [`esig_stub:${step}`])).rows;

    const prevented1 = independenceRefusal(performed) || (completion1 !== null && !completion1.ok);
    const detected1 = violations1.length > 0;
    const evidence1 = JSON.stringify({
      performedByVerifier: performed.ok ? 'ACCEPTED' : { code: performed.code, message: performed.message },
      completion: completion1 === null ? 'not attempted' : completion1.ok ? 'ACCEPTED' : { code: completion1.code, message: completion1.message },
      entry: state1,
      signatures: signers1.map((s) => ({ meaning: s.meaning_code, samePersonAsB: s.signer_person === b.personId })),
      invariantViolations: violations1,
    });
    expect.soft(prevented1 || detected1,
      `INV-03: one person (B) both VERIFIED and PERFORMED the step; this must be refused, block completion or be reported: ${evidence1}`).toBe(true);
    expect.soft(state1.state === 'COMPLETED' && performed.ok && !detected1,
      `INV-03: the step must not be COMPLETED, undetected, with B as performer and verifier: ${evidence1}`).toBe(false);

    // ------------------------------------------------------------------------------------------
    // Scenario 2 (INV-04, DI-35 APPROVED independent_of CHECKED): Q approves, then checks.
    // ------------------------------------------------------------------------------------------
    const author = await testActor(db, { roleCode: 'MBR_AUTHOR', legalName: 'MBR Author F13' });
    const q = await testActor(db, { roleCode: 'MBR_CHECKER', legalName: 'Checker And Approver F13' });
    await grantRole(q, 'QA_MBR_APPROVER');

    // Control (forward order): Q checks, then Q's approval is refused (APPROVED independent of CHECKED).
    const ctlDoc = await createStub(db, author, { kind: 'MASTER_DOCUMENT', title: 'Control MBR F13', value: 'text' });
    await signStub(db, author, ctlDoc, { meaning: 'PREPARED' });
    await signStub(db, q, ctlDoc, { meaning: 'CHECKED' });
    await expectRefused(signStub(db, as(q, 'QA_MBR_APPROVER'), ctlDoc, { meaning: 'APPROVED' }), 'EBMR-ESIG-043');

    // Reverse order on a fresh master document.
    const doc = await createStub(db, author, { kind: 'MASTER_DOCUMENT', title: 'MBR v1 F13', value: 'text' });
    await signStub(db, author, doc, { meaning: 'PREPARED' });
    const approved = await signStub(db, as(q, 'QA_MBR_APPROVER'), doc, { meaning: 'APPROVED' });
    expect(await violationsFor([approved.signatureId]), 'baseline: Q\'s APPROVED is clean before Q checks').toEqual([]);

    const checked = await attempt(signStub(db, q, doc, { meaning: 'CHECKED' }));
    const completion2 = checked.ok ? await attempt(complete(as(q, 'QA_MBR_APPROVER'), doc, approved.signatureId)) : null;
    const state2 = await stubState(doc);
    const sigIds2 = [approved.signatureId, ...(checked.ok ? [checked.value.signatureId] : [])];
    const violations2 = await violationsFor(sigIds2);
    const signers2 = (await db.admin.query<{ meaning_code: string; signer_person: string }>(
      'select meaning_code, signer_person from esig.signature where aggregate_ref = $1 order by recorded_at', [`esig_stub:${doc}`])).rows;

    const prevented2 = independenceRefusal(checked) || (completion2 !== null && !completion2.ok);
    const detected2 = violations2.length > 0;
    const evidence2 = JSON.stringify({
      checkedByApprover: checked.ok ? 'ACCEPTED' : { code: checked.code, message: checked.message },
      completion: completion2 === null ? 'not attempted' : completion2.ok ? 'ACCEPTED' : { code: completion2.code, message: completion2.message },
      entry: state2,
      signatures: signers2.map((s) => ({ meaning: s.meaning_code, samePersonAsQ: s.signer_person === q.personId })),
      invariantViolations: violations2,
    });
    expect.soft(prevented2 || detected2,
      `INV-04/DI-35: one person (Q) both APPROVED and CHECKED the master document; this must be refused, block completion or be reported: ${evidence2}`).toBe(true);
    expect.soft(state2.state === 'COMPLETED' && checked.ok && !detected2,
      `INV-04/DI-35: the master document must not be COMPLETED (approved), undetected, with Q as checker and approver: ${evidence2}`).toBe(false);
  });
});

/**
 * Review reproducer F14: the platform SIGNATURE hook adapter (esig.platform_signature_check, 0230)
 * ignores the actor it is given and the life-cycle state the signature was applied in. It only calls
 * esig.signature_problem (exists, meaning, record, still valid). The signed envelope (0200
 * esig.canonical_envelope) leaves the provider's `state` out, and esig.sign lets the caller choose
 * p_expected_state, so a signature is bound neither to the transition it authorises, nor to the state
 * it was given in, nor to the person who fires the transition. Only the single-use check on
 * platform.state_history restricts it.
 *
 * Scenario (outline 5.2: CHECKED -> APPROVED needs Sig(APPROVED) by QA after the independent check):
 *   1. A QA approver signs APPROVED ("I approve this document for use") on a sample_record while it
 *      is still DRAFT: before submission and before any independent check.
 *   2. The author submits; an independent checker signs CHECKED and fires CHECK.
 *   3. A different person (QA_REVIEWER) fires APPROVE citing the stored DRAFT-time signature id.
 *
 * Safe behaviour asserted: the DRAFT-time approval is either refused when it is applied, or it cannot
 * authorise the CHECKED -> APPROVED transition fired later by another person. With the defect the
 * transition is accepted and the history shows an approval that predates the check it must follow,
 * used by someone other than the signer.
 *
 * Positive control (same people, same roles): a proper approval, applied in state CHECKED as a
 * co-signature at the reviewer's terminal in the same command that fires APPROVE, is accepted. This
 * shows the roles, permissions, hook wiring and version numbers of the setup are right, and stays
 * valid under any of the suggested fixes (state binding, same-command binding, actor binding).
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand } from '../../src/db/command.ts';
import { sign } from '../../src/esig/signing.ts';
import { ebmrCode } from '../../src/identity/errors.ts';
import { createAggregateState, transition, type TransitionResult } from '../../src/state/engine.ts';
import type { SeededActor } from '../identity/seed.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { challengeFor, cmd, ensureSealKey, run, signatureAuth, signStub, testActor, testSealKey } from '../esig/helpers.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
  // The SIGNATURE hook (esig.platform_signature_check), the sample record's content provider and
  // its signed-table registration come from kernel migration 0910.
});

afterAll(async () => {
  await db.drop();
});

type Attempt<T> = { ok: true; value: T } | { ok: false; code: string | undefined; message: string };

async function attempt<T>(p: Promise<T>): Promise<Attempt<T>> {
  try {
    return { ok: true, value: await p };
  } catch (error) {
    return { ok: false, code: ebmrCode(error), message: error instanceof Error ? error.message : String(error) };
  }
}

async function newRecord(author: SeededActor): Promise<string> {
  return run(db, author, async (c) => {
    const { rows } = await c.query<{ id: string }>("insert into platform.stub_record (title, body) values ('Cleaning SOP', 'Version 1 text') returning id");
    const id = rows[0]?.id ?? '';
    await createAggregateState(c, 'sample_record', { aggregateType: 'sample_record', aggregateId: id });
    return id;
  });
}

const fire = async (actor: SeededActor, id: string, event: string, expectedVersion: number, signatureId?: string): Promise<TransitionResult> =>
  run(db, actor, (c) => transition(c, {
    machine: 'sample_record', aggregateType: 'sample_record', aggregateId: id, event, expectedVersion,
    ...(signatureId ? { payload: { signature_id: signatureId } } : {}),
  }));

/** The checker signs CHECKED in state SUBMITTED and fires CHECK in the same command. */
async function checkNow(checker: SeededActor, id: string, expectedVersion: number): Promise<TransitionResult> {
  const ch = await challengeFor(db, checker, id, { meaning: 'CHECKED', aggregateType: 'sample_record' });
  const ev = await signatureAuth(db, checker, checker, ch.challengeId);
  return withCommand(db.app, await cmd(db, checker), async (c) => {
    const s = await sign(c, { challengeId: ch.challengeId, authEventId: ev, expectedState: 'SUBMITTED' }, testSealKey);
    return transition(c, { machine: 'sample_record', aggregateType: 'sample_record', aggregateId: id, event: 'CHECK', expectedVersion,
                           payload: { signature_id: s.signatureId } });
  });
}

async function stateOf(id: string): Promise<{ state: string; version: string }> {
  const { rows } = await db.admin.query<{ state: string; version: string }>(
    "select state, version::text from platform.aggregate_state where aggregate_type = 'sample_record' and aggregate_id = $1", [id]);
  return rows[0] ?? { state: '?', version: '?' };
}

describe('F14: platform SIGNATURE hook binds the signature to the transition, its state and its actor', () => {
  it('[DI-37][DI-35][INV-04] an APPROVED signature applied while the record was DRAFT cannot authorise another person\'s CHECKED -> APPROVED transition', async () => {
    const author = await testActor(db, { roleCode: 'MBR_AUTHOR', legalName: 'A. Author' });
    const checker = await testActor(db, { roleCode: 'MBR_CHECKER', legalName: 'C. Checker' });
    const approver = await testActor(db, { roleCode: 'QA_MBR_APPROVER', legalName: 'Q. Approver' });
    const reviewer = await testActor(db, { roleCode: 'QA_REVIEWER', legalName: 'R. Reviewer' });

    // Positive control: the approver co-signs APPROVED at the reviewer's terminal in state CHECKED,
    // and the reviewer fires APPROVE with it in the same command. Accepted.
    const good = await newRecord(author);
    await fire(author, good, 'SUBMIT', 1);
    await checkNow(checker, good, 2);
    const gch = await challengeFor(db, reviewer, good, { meaning: 'APPROVED', aggregateType: 'sample_record', signer: approver });
    const gev = await signatureAuth(db, approver, reviewer, gch.challengeId);
    const approvedOk = await withCommand(db.app, await cmd(db, reviewer), async (c) => {
      const s = await sign(c, { challengeId: gch.challengeId, authEventId: gev, expectedState: 'CHECKED' }, testSealKey);
      return transition(c, { machine: 'sample_record', aggregateType: 'sample_record', aggregateId: good, event: 'APPROVE', expectedVersion: 3,
                             payload: { signature_id: s.signatureId } });
    });
    expect(approvedOk).toMatchObject({ from: 'CHECKED', to: 'APPROVED' });

    // The defect path. Step 1: the QA approver signs APPROVED while the record is still DRAFT.
    const id = await newRecord(author);
    const early = await attempt(signStub(db, approver, id, { meaning: 'APPROVED', aggregateType: 'sample_record', expectedState: 'DRAFT' }));
    if (!early.ok) {
      // Safe: an approval cannot be applied before the record was submitted and checked.
      expect(early.code ?? '').toMatch(/^EBMR-/);
      return;
    }

    // Step 2: normal life cycle up to CHECKED, with the independent check applied after the approval.
    await fire(author, id, 'SUBMIT', 1);
    await checkNow(checker, id, 2);
    expect(await stateOf(id)).toEqual({ state: 'CHECKED', version: '3' });

    // Step 3: another person (QA_REVIEWER) fires APPROVE citing the DRAFT-time signature.
    const used = await attempt(fire(reviewer, id, 'APPROVE', 3, early.value.signatureId));

    let evidence = '';
    if (used.ok) {
      const { rows } = await db.admin.query<{ event: string; from_state: string; person_id: string; signature_id: string | null; at: string }>(
        `select event, from_state, person_id::text, signature_id::text, recorded_at::text as at from platform.state_history
         where aggregate_type = 'sample_record' and aggregate_id = $1 and event is not null order by to_version`, [id]);
      const sig = await db.admin.query<{ signer_person: string; recorded_at: string }>(
        'select signer_person::text, recorded_at::text from esig.signature where id = $1', [early.value.signatureId]);
      evidence = JSON.stringify({ approvalSignature: sig.rows[0], approverPerson: approver.personId, reviewerPerson: reviewer.personId, history: rows });
    }
    expect(used.ok, `APPROVE was accepted with an APPROVED signature applied in DRAFT by another person: ${evidence}`).toBe(false);
    if (!used.ok) expect(used.message).toMatch(/signature/i);
    expect(await stateOf(id)).toEqual({ state: 'CHECKED', version: '3' });
  });
});

/**
 * Review reproducer F15: the WITNESSED rule "signed before the next step starts" (DI-35 guard
 * EBMR-ESIG-051, outline 5.5) rests on a boolean the caller supplies. esig.sign(...,
 * p_next_step_started boolean default false) hands the caller's value to esig.check_witness, which
 * refuses only when that value is true. The provider contract (0200) carries no field that tells the
 * database the next step has started, so the database never derives it from the record.
 *
 * Scenario (outline 5.5: WITNESSED means the signer watched the act; a late witness raises an
 * exception instead):
 *   1. Positive control: the witness, at a terminal in the performer's room, witnesses an act right
 *      after it is recorded, before anything else happens. Accepted. This shows the witness holds
 *      the role, is independent of the performer (INV-03) and is at an allowed terminal.
 *   2. The performer records step 1 (a manual reading, no objective evidence) and signs PERFORMED.
 *   3. The performer starts the next step: records step 2 on the same terminal and signs PERFORMED.
 *      Everything is still well inside the 5-minute witness window.
 *   4. The application now asks for a WITNESSED signature on step 1, leaving nextStepStarted out
 *      (the TypeScript wrapper and esig.sign both default it to false).
 *
 * Safe behaviour asserted: step 4 is refused with EBMR-ESIG-051 because the next step has started.
 * With the defect the database accepts the WITNESSED signature, since the only input it consults
 * is the caller's flag (the same attempt with nextStepStarted: true is refused, which shows the
 * rule exists but is decided by the application, not by the enforcement point).
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { createStub, ensureSealKey, expectRefused, signStub, testActor } from '../esig/helpers.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
});

afterAll(async () => {
  await db.drop();
});

describe('F15: WITNESSED "before the next step" is enforced by the database', () => {
  it('[DI-35][INV-03] a witness after the performer started the next step is refused even when the application omits nextStepStarted', async () => {
    const performer = await testActor(db, { deviceClass: 'GRADE_A_B', roomCode: 'ROOM-F15', legalName: 'Step Performer' });
    const witness = await testActor(db, { roleCode: 'VERIFIER', deviceClass: 'GRADE_A_B', roomCode: 'ROOM-F15', legalName: 'Room Witness' });

    // 1. Positive control: a timely witness on an act whose next step has not started is accepted.
    const control = await createStub(db, performer, { title: 'Control: manual pressure reading', value: '1.20', unit: 'bar' });
    await signStub(db, performer, control, { meaning: 'PERFORMED' });
    const ok = await signStub(db, witness, control, { meaning: 'WITNESSED' });
    const { rows: okRows } = await db.admin.query<{ w: Record<string, unknown> }>('select witness as w from esig.signature where id = $1', [ok.signatureId]);
    expect(okRows[0]?.w).toMatchObject({ room_code: 'ROOM-F15', act_device_id: performer.deviceId });

    // 2. Step 1: the act to be witnessed.
    const step1 = await createStub(db, performer, { title: 'Step 1: manual pressure reading before binder addition', value: '1.35', unit: 'bar' });
    await signStub(db, performer, step1, { meaning: 'PERFORMED' });

    // 3. The performer starts the next step on the same terminal and completes its act.
    const step2 = await createStub(db, performer, { title: 'Step 2: binder solution added', value: '12.503', unit: 'kg' });
    await signStub(db, performer, step2, { meaning: 'PERFORMED' });

    // The record shows step 2 was entered after step 1, on the same terminal, and step 1 is still
    // inside the witness window (so neither EBMR-ESIG-052 nor EBMR-ESIG-053 applies).
    const { rows: facts } = await db.admin.query<{ later: boolean; same_device: boolean; in_window: boolean; step1_state: string }>(
      `select s2.entered_at > s1.entered_at as later,
              s2.entered_device_id = s1.entered_device_id as same_device,
              clock_timestamp() - s1.entered_at < interval '240 seconds' as in_window,
              s1.state as step1_state
         from esig.stub_signable s1, esig.stub_signable s2 where s1.id = $1 and s2.id = $2`,
      [step1, step2],
    );
    expect(facts[0]).toEqual({ later: true, same_device: true, in_window: true, step1_state: 'OPEN' });
    const { rows: s2sig } = await db.admin.query<{ n: number }>(
      "select count(*)::int as n from esig.signature where aggregate_ref = $1 and meaning_code = 'PERFORMED'",
      [`esig_stub:${step2}`],
    );
    expect(s2sig[0]?.n).toBe(1);

    // The flag, when the application happens to pass it, is honoured (the rule exists) ...
    await expectRefused(signStub(db, witness, step1, { meaning: 'WITNESSED', nextStepStarted: true }), 'EBMR-ESIG-051');

    // 4. ... but the database must refuse the late witness on its own: the application omits the
    // flag, exactly as `select esig.sign(ch, ev, 'OPEN')` would.
    await expectRefused(signStub(db, witness, step1, { meaning: 'WITNESSED' }), 'EBMR-ESIG-051', /next step has started/);

    // Nothing was witnessed on step 1.
    const { rows: w1 } = await db.admin.query<{ n: number }>(
      "select count(*)::int as n from esig.signature where aggregate_ref = $1 and meaning_code = 'WITNESSED'",
      [`esig_stub:${step1}`],
    );
    expect(w1[0]?.n).toBe(0);
  });
});

/**
 * Review reproducer F16: a non-canonical spelling of an aggregate id (here the stub's UUID in upper
 * case) is a second identity for the same record. esig.create_challenge stores p_aggregate_id as the
 * caller passed it; esig.stub_content casts it with ::uuid, so the alias resolves to the same row.
 * Everything that relates signatures to the record compares the aggregate_ref text
 * (performers_of, check_independence "already holds" and independent_of, aggregate_lock,
 * content_changed, record_signatures, invariant_violations), and the esig.content_change and
 * performer signature rows carry the canonical lower-case id.
 *
 * Scenario (INV-03: a verifier or witness is never a person who performed, entered data in or
 * corrected the record):
 *   1. op (OPERATOR, also granted VERIFIER) enters a step and signs PERFORMED.
 *   2. Positive control: op, acting as VERIFIER, signs VERIFIED on the canonical id -> EBMR-ESIG-044.
 *   3. The alias resolves to the same record (same content version and content).
 *   4. op, acting as VERIFIER, runs content_for_signing / create_challenge / sign with the id in
 *      upper case and meaning VERIFIED.
 *
 * Safe behaviour asserted: step 4 is refused (either the alias is not accepted as an aggregate id,
 * or INV-03 is evaluated against the record and refuses op), and no VERIFIED signature by the
 * performer exists on the record under any spelling. With the defect the database stores a sealed
 * VERIFIED signature by the performer, esig.record_signatures lists it as VALID under the alias,
 * and esig.invariant_violations() reports no INV-03 row for it.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand } from '../../src/db/command.ts';
import { decideRoleGrant, requestRoleGrant } from '../../src/identity/admin.ts';
import { seedAdministration, withReason, type SeededActor } from '../identity/seed.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { createStub, ensureSealKey, expectRefused, signStub, testActor } from '../esig/helpers.ts';
import type { SignatureResult } from '../../src/esig/signing.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
});

afterAll(async () => {
  await db.drop();
});

/** Gives the person's account a second role (requested by the administrator, approved by the process owner). */
async function grantRole(actor: SeededActor, roleCode: string): Promise<void> {
  const { admin, owner } = await seedAdministration(db);
  const grantId = await withCommand(db.app, withReason(admin), (c) => requestRoleGrant(c, { accountId: actor.accountId, roleCode, reason: 'second duty for test' }));
  await withCommand(db.app, withReason(owner), (c) => decideRoleGrant(c, grantId, true, 'approved for test'));
}

const as = (actor: SeededActor, roleCode: string): SeededActor => ({ ...actor, roleCode });

describe('F16: a non-canonical aggregate id is not a second identity for the record', () => {
  it('[INV-03][DI-35][INV-09] the performer cannot verify their own step by spelling its id in upper case', async () => {
    // 1. The performer enters the step and signs PERFORMED.
    const op = await testActor(db, { legalName: 'Alias Dual Role Person' });
    await grantRole(op, 'VERIFIER');
    const id = await createStub(db, op, { title: 'Granulation: binder added (F16)', value: '12.503', unit: 'kg' });
    await signStub(db, op, id, { meaning: 'PERFORMED' });

    // 2. Positive control: on the canonical id INV-03 refuses the performer as verifier.
    await expectRefused(signStub(db, as(op, 'VERIFIER'), id, { meaning: 'VERIFIED' }), 'EBMR-ESIG-044', /INV-03/);

    // 3. The alias names the same record: the provider returns the same version and content.
    const alias = id.toUpperCase();
    expect(alias).not.toBe(id);
    const { rows: prov } = await db.admin.query<{ canon: Record<string, unknown>; aliased: Record<string, unknown> }>(
      "select esig.provide('esig_stub', $1) as canon, esig.provide('esig_stub', $2) as aliased",
      [id, alias],
    );
    expect(prov[0]?.canon['exists']).toBe(true);
    expect(prov[0]?.aliased['content']).toEqual(prov[0]?.canon['content']);
    expect(prov[0]?.aliased['content_version']).toEqual(prov[0]?.canon['content_version']);

    // 4. The same person, as VERIFIER, signs VERIFIED on the alias.
    let accepted: SignatureResult | undefined;
    let refusal: unknown;
    try {
      accepted = await signStub(db, as(op, 'VERIFIER'), alias, { meaning: 'VERIFIED' });
    } catch (error) {
      refusal = error;
    }

    // Evidence gathered from the database (superuser read) whatever the outcome.
    const { rows: verifiedByPerformer } = await db.admin.query<{ id: string; aggregate_id: string }>(
      "select id, aggregate_id from esig.signature where aggregate_type = 'esig_stub' and lower(aggregate_id) = lower($1) and meaning_code = 'VERIFIED' and signer_person = $2",
      [id, op.personId],
    );
    const { rows: listed } = await db.admin.query<{ meaning_code: string; status: string; valid: boolean }>(
      "select meaning_code, status, valid from esig.record_signatures('esig_stub', $1) where meaning_code = 'VERIFIED'",
      [alias],
    );
    const { rows: inv03 } = await db.admin.query<{ signature_id: string }>(
      "select signature_id from esig.invariant_violations() where invariant = 'INV-03'",
    );

    expect(
      {
        acceptedSignatureId: accepted?.signatureId ?? null,
        verifiedByPerformerOnRecord: verifiedByPerformer,
        listedAsValidUnderAlias: listed,
      },
      `INV-03 bypass: VERIFIED by the performer accepted under alias ${alias}; INV-03 invariant rows: ${JSON.stringify(inv03)}`,
    ).toEqual({ acceptedSignatureId: null, verifiedByPerformerOnRecord: [], listedAsValidUnderAlias: [] });

    // The refusal is a database refusal, not an error in the test.
    const message = refusal instanceof Error ? refusal.message : String(refusal);
    expect(message).toMatch(/EBMR-ESIG-/);
  });
});

/**
 * Review reproducer F17: the sample_record content provider (platform.sample_record_content, kernel
 * migration 0910) derives content_version from 1 + the number of kernel.audit_event UPDATE rows of the
 * record. The audit trigger (kernel.audit_row_change, 0010) records every UPDATE, including one that
 * changes nothing, while the signed-table registration covers only title and body, so
 * esig.on_signed_content_change (0220) returns early for a no-op UPDATE and writes no invalidation.
 * A no-op save therefore changes the signed envelope hash (content_version is part of it, 0200
 * esig.canonical_envelope) without superseding the signature.
 *
 * Scenario:
 *   1. The author creates a sample record (DRAFT) and signs PREPARED on it.
 *   2. In a command with a reason, the author saves the record without changing anything:
 *      update platform.stub_record set title = title where id = X.
 *
 * Safe behaviour asserted (INV-09: a signature that is not superseded is bound to the record's
 * current content hash; DI-37): after the no-op save the signature is either still VALID (nothing
 * signed changed) or properly SUPERSEDED_BY_CHANGE with an invalidation row; it is never
 * CONTENT_MISMATCH, and esig.invariant_violations() reports no INV-09 for it.
 *
 * Positive control: right after signing, the signature is VALID and INV-09 is clean, so the setup
 * (roles, provider, seal key) is right and only the no-op save changes the outcome.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { createAggregateState } from '../../src/state/engine.ts';
import type { SeededActor } from '../identity/seed.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { ensureSealKey, run, signStub, testActor } from '../esig/helpers.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
  // The sample record's content provider and its signed-table registration come from kernel migration 0910.
});

afterAll(async () => {
  await db.drop();
});

async function newRecord(author: SeededActor): Promise<string> {
  return run(db, author, async (c) => {
    const { rows } = await c.query<{ id: string }>("insert into platform.stub_record (title, body) values ('Cleaning SOP', 'Version 1 text') returning id");
    const id = rows[0]?.id ?? '';
    await createAggregateState(c, 'sample_record', { aggregateType: 'sample_record', aggregateId: id });
    return id;
  });
}

interface SigState {
  status: string;
  valid: boolean;
  content_version: string;
  invalidation: unknown;
}

async function stateOf(signatureId: string): Promise<SigState> {
  const { rows } = await db.admin.query<{ s: SigState }>('select esig.signature_state($1) as s', [signatureId]);
  return rows[0]?.s ?? { status: '?', valid: false, content_version: '?', invalidation: null };
}

async function inv09For(signatureId: string): Promise<string[]> {
  const { rows } = await db.admin.query<{ detail: string }>(
    "select detail from esig.invariant_violations() where invariant = 'INV-09' and signature_id = $1", [signatureId]);
  return rows.map((r) => r.detail);
}

async function evidence(id: string, signatureId: string): Promise<string> {
  const provided = await db.admin.query<{ p: unknown }>("select platform.sample_record_content($1) as p", [id]);
  const audits = await db.admin.query<{ action: string; body: unknown }>(
    "select action, payload as body from kernel.audit_event where table_name = 'platform.stub_record' and record_id = $1 order by seq", [id]);
  const inval = await db.admin.query<{ n: string }>('select count(*)::text as n from esig.signature_invalidation where signature_id = $1', [signatureId]);
  const resign = await db.admin.query<{ meaning_code: string }>("select meaning_code from esig.resigning_required('sample_record', $1)", [id]);
  return JSON.stringify({ provided: provided.rows[0]?.p, auditEvents: audits.rows.map((r) => r.action), invalidations: inval.rows[0]?.n,
                          resigningRequired: resign.rows.map((r) => r.meaning_code) });
}

describe('F17: a no-op save of a signed sample record never breaks the signature binding silently', () => {
  it('[INV-09][DI-37] after an UPDATE that changes no signed column the signature is VALID or SUPERSEDED_BY_CHANGE, never CONTENT_MISMATCH', async () => {
    const author = await testActor(db, { roleCode: 'MBR_AUTHOR', legalName: 'A. Author' });
    const id = await newRecord(author);

    // Step 1: the author signs PREPARED on the DRAFT record.
    const sig = await signStub(db, author, id, { meaning: 'PREPARED', aggregateType: 'sample_record', expectedState: 'DRAFT' });

    // Positive control: freshly signed, valid, and INV-09 clean.
    const before = await stateOf(sig.signatureId);
    expect(before.status).toBe('VALID');
    expect(await inv09For(sig.signatureId)).toEqual([]);

    // Step 2: a save that changes nothing (DRAFT allows edits; a reason is given as the audit trail requires).
    await run(db, author, (c) => c.query('update platform.stub_record set title = title where id = $1', [id]), {
      reasonCode: 'REWORK',
      reasonText: 'saved without changes',
    });
    const { rows: same } = await db.admin.query<{ title: string; body: string }>('select title, body from platform.stub_record where id = $1', [id]);
    expect(same[0]).toEqual({ title: 'Cleaning SOP', body: 'Version 1 text' });

    const after = await stateOf(sig.signatureId);
    const violations = await inv09For(sig.signatureId);
    const why = await evidence(id, sig.signatureId);

    // Safe: either nothing signed changed (VALID) or the change superseded the signature with an invalidation.
    expect.soft(['VALID', 'SUPERSEDED_BY_CHANGE'], `no-op save left signature ${after.status} (signed content_version ${before.content_version}): ${why}`)
      .toContain(after.status);
    if (after.status === 'SUPERSEDED_BY_CHANGE') expect(after.invalidation).not.toBeNull();
    expect(violations, `INV-09 raised for the signature after a no-op save: ${why}`).toEqual([]);
  });
});

/**
 * Review reproducer F20: for ALL_APPLY keys "a is at least as strict as b" is decided on criterion
 * ids only (market.at_least_as_strict, 0300: criteria_ids(a) @> criteria_ids(b); TS twin
 * isAtLeastAsStrict in src/market/strictness.ts). The content of a criterion (bands, sampling plan,
 * stage) is never compared, so a criterion that keeps its id but carries weaker content counts as
 * equal or stricter.
 *
 * The HARD India criterion under test is B-14.IN.ipBands (tablets.uniformity.acceptanceCriteria,
 * IP uniformity of weight: 10 / 7.5 / 5 %). The weakened copy keeps the id and replaces the bands by
 * a single 50 % band.
 *
 * Safe behaviour asserted here:
 *   1. A site value that weakens the HARD India criterion (same id, looser bands) is refused
 *      (IN-52: a site value looser than a HARD value is refused, with or without approvals), and the
 *      {IN} tablet batch evaluation keeps the India bands as its effective value.
 *   2. A tablets v2 UPDATE whose only change is the weakened India criterion (same id, effective
 *      since 2023-12-28, so already in force) is refused with EBMR-MKT-031: only a SOURCE_CORRECTION
 *      (citation, two approvers) may loosen a value in force.
 *   3. The TS comparator does not call the weakened criterion "at least as strict" as the India one.
 *
 * Positive controls (same key, same actors): dropping the India criterion id is refused on both
 * paths, so the setup (roles, scopes, publish gate) is right and only the same-id case slips through.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { batchFlags, evaluateStubScope, setSiteValue } from '../../src/market/repository.ts';
import { isAtLeastAsStrict, jsonEqual } from '../../src/market/strictness.ts';
import type { RuleTableDocument, RuleValue } from '../../src/market/types.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { asApp, MARKET_ROLES, publishDocument, publishSeedTables, seedDocument, seedStubWorld, type StubWorld } from '../market/helpers.ts';

let db: TestDatabase;
let world: StubWorld;

beforeAll(async () => {
  db = await createTestDatabase();
  await publishSeedTables(db);
  world = await seedStubWorld(db);
});

afterAll(async () => {
  await db.drop();
});

const KEY = 'tablets.uniformity.acceptanceCriteria';
const IP_ID = 'IP_UNIFORMITY_OF_WEIGHT_BANDS';

type Criterion = { id: string } & Record<string, unknown>;

async function outcomeOf<T>(p: Promise<T>, describeOk: (v: T) => string): Promise<string> {
  try {
    return describeOk(await p);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const code = /EBMR-[A-Z]+-\d+/.exec(message)?.[0] ?? 'UNCODED';
    return `REFUSED ${code}`;
  }
}

describe('F20: ALL_APPLY strictness must compare criterion content, not only ids', () => {
  it('[IN-52][INV-28][IN-34][ST-01] a HARD India criterion cannot be weakened under the same id, by a site value or by an UPDATE', async () => {
    const tablets = seedDocument('tablets');
    const rowsOf = (d: RuleTableDocument) => d.rows;
    const ipRow = rowsOf(tablets).find((r) => r.ref === 'B-14.IN.ipBands');
    const usRow = rowsOf(tablets).find((r) => r.ref === 'B-14.US.udu');
    const euRow = rowsOf(tablets).find((r) => r.ref === 'B-14.EU.udu');
    if (!ipRow || !usRow || !euRow) throw new Error('seed rows B-14.* not found');
    expect(ipRow.floor).toBe('HARD');
    const ip = (ipRow.value as Criterion[])[0] as Criterion;
    const usp = (usRow.value as Criterion[])[0] as Criterion;
    const phEur = (euRow.value as Criterion[])[0] as Criterion;
    expect(ip.id).toBe(IP_ID);

    // Same id, same stage and pharmacopoeia, one 50 % band instead of the IP 10 / 7.5 / 5 % bands.
    const weakIp: Criterion = { ...ip, bands: [{ deviationPercent: '50' }] };

    const setAsSteward = (value: RuleValue) =>
      asApp(db, (c) => setSiteValue(c, { siteId: world.siteId, key: KEY, value, effectiveFrom: '2026-01-01' }), { roleCode: MARKET_ROLES.siteValues });

    // Positive control 1: a site value that drops the India criterion id is refused (the site scope is {EU, IN, US}).
    const controlSite = await outcomeOf(setAsSteward([phEur, usp] as unknown as RuleValue), (sv) => `ACCEPTED ${sv.outcome}`);

    // Attack 1: weaken the India criterion under its own id; keep the EU and US criteria unchanged. No justification, no QA approval.
    const attackSite = await outcomeOf(setAsSteward([weakIp, phEur, usp] as unknown as RuleValue), (sv) => `ACCEPTED ${sv.outcome}`);

    // The {IN} tablet batch, evaluated by an operator after the site value's effective date.
    const e = await asApp(
      db,
      (c) => evaluateStubScope(c, { key: KEY, scope: { kind: 'PRODUCT', id: world.batch.tabletIn }, resolutionPoint: 'EXECUTION', asOf: '2026-03-01' }),
      { roleCode: MARKET_ROLES.evaluator },
    );
    const effectiveIp = (e.effectiveValue as unknown as Criterion[] | null)?.find((c) => c.id === IP_ID) ?? null;
    const flags = await batchFlags(db.app, world.batch.tabletIn);

    // Positive control 2: an UPDATE that replaces the India criterion by a different id is refused as a loosening in force.
    const renamed: RuleTableDocument = {
      ...tablets,
      version: 2,
      change: { kind: 'UPDATE', description: 'F20 control: India criterion under a new id' },
      rows: rowsOf(tablets).map((r) => (r.ref === 'B-14.IN.ipBands' ? { ...r, value: [{ ...ip, id: 'IP_UNIFORMITY_OF_WEIGHT_BANDS_X' }] as unknown as RuleValue } : r)),
    };
    const controlPublish = await outcomeOf(publishDocument(db, renamed), (p) => `PUBLISHED loosening=${p.loosening.length} impact=${p.impactCount}`);

    // Attack 2: an UPDATE whose only change is the weakened India criterion under its own id, in force since 2023-12-28.
    const weakened: RuleTableDocument = {
      ...tablets,
      version: 2,
      change: { kind: 'UPDATE', description: 'F20: IP weight bands edited' },
      rows: rowsOf(tablets).map((r) => (r.ref === 'B-14.IN.ipBands' ? { ...r, value: [weakIp] as unknown as RuleValue } : r)),
    };
    const attackPublish = await outcomeOf(publishDocument(db, weakened), (p) => `PUBLISHED loosening=${p.loosening.length} impact=${p.impactCount}`);

    // TS twin of the comparator.
    const tsSaysWeakIsAsStrict = isAtLeastAsStrict('ALL_APPLY', null, [weakIp] as unknown as RuleValue, [ip] as unknown as RuleValue);

    const observed = {
      controlSite,
      controlPublish,
      attackSite,
      evaluation: {
        resolvedIsIndiaBands: jsonEqual(e.resolvedValue, [ip]),
        effectiveIpIsIndiaBands: jsonEqual(effectiveIp, ip),
        siteOutcome: e.siteOutcome,
        batchFlagged: flags.length > 0,
      },
      attackPublish,
      tsSaysWeakIsAsStrict,
    };

    expect(observed).toEqual({
      controlSite: 'REFUSED EBMR-MKT-064',
      controlPublish: 'REFUSED EBMR-MKT-031',
      // A site value looser than a HARD value is refused (IN-52); the same id does not make it tighter.
      attackSite: expect.stringMatching(/^REFUSED EBMR-MKT-06[04]$/),
      evaluation: {
        resolvedIsIndiaBands: true,
        // The India HARD bands stay in force for the {IN} batch.
        effectiveIpIsIndiaBands: true,
        siteOutcome: expect.not.stringMatching(/^SITE_TIGHTER$|^SITE_EQUAL$/),
        batchFlagged: expect.any(Boolean),
      },
      // Loosening a value already in force needs a SOURCE_CORRECTION (EBMR-MKT-031).
      attackPublish: 'REFUSED EBMR-MKT-031',
      tsSaysWeakIsAsStrict: false,
    });
  });
});

/**
 * Review reproducer F21: market.evaluate_stub_scope (0330) passes
 * coalesce(p_req -> 'siteId', v_scope -> 'siteId') to market.record_evaluation, so the site whose
 * value is applied to a GMP evaluation is whatever the caller supplies. A JSON null also wins (it is
 * jsonb 'null', not SQL NULL), becomes site_id NULL, and market.apply_site_value then returns
 * NO_SITE_VALUE. site_id has no FK and no existence check.
 *
 * Setup: the stub site A (world.siteId) holds a TIGHTER value 15 min for
 * tablets.compression.ipcSampleMaxInterval (India 30 min). A second stub site B holds an approved
 * LOOSENED value 15 mo for kernel.managementReview.maxIntervalMonths (India GUIDANCE 12 mo); site A
 * holds no value for that key.
 *
 * Safe behaviour asserted: an OPERATOR (MARKET.RULE_EVALUATE) evaluating a batch made at site A
 * either gets site A's value applied (the site is the scope's site, whatever the request says) or
 * is refused. It must never get:
 *   - site A's tighter limit dropped by siteId = null or siteId = a random uuid, or
 *   - site B's approved loosening applied to a site A batch by siteId = site B.
 *
 * Positive control: without siteId the stored evaluation carries site A and effective value 15.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { evaluateStubScope, setSiteValue, type StoredEvaluation } from '../../src/market/repository.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { asApp, MARKET_ROLES, publishSeedTables, seedStubWorld, type StubWorld } from '../market/helpers.ts';

let db: TestDatabase;
let world: StubWorld;
let siteB: string;

const IPC_KEY = 'tablets.compression.ipcSampleMaxInterval';
const MR_KEY = 'kernel.managementReview.maxIntervalMonths';
const AS_OF = '2026-03-01';

beforeAll(async () => {
  db = await createTestDatabase();
  await publishSeedTables(db);
  world = await seedStubWorld(db);
  siteB = await asApp(
    db,
    async (c) => {
      const { rows } = await c.query<{ id: string }>('insert into market.stub_site (code, markets) values ($1, $2) returning id', [
        `SITE-B-${randomUUID().slice(0, 8)}`,
        ['IN'],
      ]);
      return rows[0]?.id ?? '';
    },
    { roleCode: MARKET_ROLES.stubs },
  );
  // Site A: a stricter IPC sampling interval than India's 30 min.
  const tighter = await asApp(db, (c) => setSiteValue(c, { siteId: world.siteId, key: IPC_KEY, value: '15', effectiveFrom: '2026-01-01' }), {
    roleCode: MARKET_ROLES.siteValues,
  });
  expect(tighter.outcome).toBe('TIGHTER');
  // Site B: an approved loosening of the India GUIDANCE management-review interval (12 -> 15 months).
  const loosened = await asApp(
    db,
    (c) =>
      setSiteValue(c, {
        siteId: siteB,
        key: MR_KEY,
        value: '15',
        effectiveFrom: '2026-01-01',
        justificationRef: 'MR-JUST-B',
        qaApprovalId: randomUUID(),
      }),
    { roleCode: MARKET_ROLES.siteValues },
  );
  expect(loosened.outcome).toBe('LOOSENED');
});

afterAll(async () => {
  await db.drop();
});

/** Evaluate a site A batch as an OPERATOR; `extra` is merged into the raw request (may carry siteId: null). */
async function evaluate(key: string, batch: string, extra: Record<string, unknown> = {}): Promise<StoredEvaluation> {
  return asApp(
    db,
    (c) =>
      evaluateStubScope(c, {
        key,
        scope: { kind: 'PRODUCT', id: batch },
        resolutionPoint: 'EXECUTION',
        asOf: AS_OF,
        ...(extra as { siteId?: string }),
      }),
    { roleCode: MARKET_ROLES.evaluator },
  );
}

/** A compact description: the stored site, outcome and effective value, or the refusal code. */
async function outcomeOf(p: Promise<StoredEvaluation>, siteName: (id: string | null) => string): Promise<string> {
  try {
    const e = await p;
    return `site=${siteName(e.siteId)} ${e.siteOutcome} effective=${JSON.stringify(e.effectiveValue)}`;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return `REFUSED ${/EBMR-[A-Z]+-\d+/.exec(message)?.[0] ?? message}`;
  }
}

describe('F21: the site applied to an evaluation is the scope\'s site, never the caller\'s choice', () => {
  it('[IN-52][ST-01][INV-29] siteId null, a random siteId or another site\'s id cannot drop the site\'s tighter value or import another site\'s loosening', async () => {
    const name = (id: string | null) => (id === null ? 'NULL' : id === world.siteId ? 'A' : id === siteB ? 'B' : 'FOREIGN');

    // Positive control: without siteId the batch at site A gets site A's tighter 15 min.
    const control = await outcomeOf(evaluate(IPC_KEY, world.batch.tabletIn), name);
    expect(control).toBe('site=A SITE_TIGHTER effective="15"');
    const controlMr = await outcomeOf(evaluate(MR_KEY, world.batch.injectableAll), name);
    expect(controlMr).toBe('site=A NO_SITE_VALUE effective="12"');

    const results = {
      ipcWithSiteNull: await outcomeOf(evaluate(IPC_KEY, world.batch.tabletIn, { siteId: null }), name),
      ipcWithRandomSite: await outcomeOf(evaluate(IPC_KEY, world.batch.tabletIn, { siteId: randomUUID() }), name),
      mrWithOtherSite: await outcomeOf(evaluate(MR_KEY, world.batch.injectableAll, { siteId: siteB }), name),
    };

    // Safe: the evaluation uses site A (same as the control) or the request is refused.
    const safe = (value: string, sameAsControl: string) => value === sameAsControl || value.startsWith('REFUSED ');
    expect({
      ipcWithSiteNull: safe(results.ipcWithSiteNull, control) ? 'SAFE' : results.ipcWithSiteNull,
      ipcWithRandomSite: safe(results.ipcWithRandomSite, control) ? 'SAFE' : results.ipcWithRandomSite,
      mrWithOtherSite: safe(results.mrWithOtherSite, controlMr) ? 'SAFE' : results.mrWithOtherSite,
    }).toEqual({ ipcWithSiteNull: 'SAFE', ipcWithRandomSite: 'SAFE', mrWithOtherSite: 'SAFE' });
  });
});

/**
 * Review reproducer F22: market.record_evaluation (0330) files an evaluation under
 * coalesce(p_req -> 'subject', <derived from scope>), and market.evaluate_stub_scope passes the
 * caller's subject through unchecked. The market set, predicates and site come from the SCOPE, but
 * the row is listed, flagged and audited under the SUBJECT (listEvaluations(subject),
 * market.batch_flags(subject), audit chain market_evaluation:<subject>).
 *
 * Setup: the IN-52 stub world. Batch T-IN serves {IN}; batch T-ALL (same product) serves
 * {EU, IN, US}. kernel.referenceSamples.monthsAfterExpiry is 3 mo for India and 12 mo for US/EU, so
 * T-ALL must resolve to 12. The site of every stub batch holds an approved LOOSENED value (15 mo)
 * for kernel.managementReview.maxIntervalMonths, so evaluating that key for batch I-ALL gives
 * SITE_LOOSENED, which must show in batch_flags(I-ALL).
 *
 * Safe behaviour asserted (the request is refused, or the subject is bound to the scope):
 *   1. An OPERATOR evaluating scope T-IN with subject BATCH T-ALL never gets a row filed under T-ALL
 *      whose market set is {IN} / value 3: every referenceSamples evaluation listed under T-ALL
 *      has market set {EU, IN, US} and resolved value 12, and T-ALL's audit chain holds no such row.
 *   2. An OPERATOR evaluating scope I-ALL (SITE_LOOSENED) with subject BATCH I-IN cannot hide the
 *      flag: if the evaluation is stored, batch_flags(I-ALL) lists it.
 *
 * Positive controls: without a subject, T-ALL resolves to 12 over {EU, IN, US} and is filed under
 * T-ALL; I-ALL's managementReview evaluation is SITE_LOOSENED and flagged on I-ALL.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { batchFlags, evaluateStubScope, listEvaluations, setSiteValue, type EvaluateStubScopeRequest, type StoredEvaluation } from '../../src/market/repository.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { asApp, MARKET_ROLES, publishSeedTables, seedStubWorld, type StubWorld } from '../market/helpers.ts';

let db: TestDatabase;
let world: StubWorld;

const REF_KEY = 'kernel.referenceSamples.monthsAfterExpiry';
const MR_KEY = 'kernel.managementReview.maxIntervalMonths';
const AS_OF = '2026-03-01';

beforeAll(async () => {
  db = await createTestDatabase();
  await publishSeedTables(db);
  world = await seedStubWorld(db);
  // An approved loosening of the GUIDANCE management-review interval (12 -> 15 months) at the site
  // where every stub batch is made.
  const loosened = await asApp(
    db,
    (c) =>
      setSiteValue(c, {
        siteId: world.siteId,
        key: MR_KEY,
        value: '15',
        effectiveFrom: '2026-01-01',
        justificationRef: 'MR-JUST-F22',
        qaApprovalId: randomUUID(),
      }),
    { roleCode: MARKET_ROLES.siteValues },
  );
  expect(loosened.outcome).toBe('LOOSENED');
});

afterAll(async () => {
  await db.drop();
});

/** Evaluate as an OPERATOR (MARKET.RULE_EVALUATE). */
function evaluate(request: EvaluateStubScopeRequest): Promise<StoredEvaluation> {
  return asApp(db, (c) => evaluateStubScope(c, request), { roleCode: MARKET_ROLES.evaluator });
}

/** The stored evaluation, or the refusal code. */
async function attempt(p: Promise<StoredEvaluation>): Promise<StoredEvaluation | string> {
  try {
    return await p;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return `REFUSED ${/EBMR-[A-Z]+-\d+/.exec(message)?.[0] ?? message}`;
  }
}

describe('F22: an evaluation is filed only under a subject its scope entails', () => {
  it('[INV-29][IN-52][INV-28] pairing a batch subject with another batch\'s scope cannot file a looser evaluation under it or hide its site-value flag', async () => {
    // Positive control 1: T-ALL resolves to 12 over {EU, IN, US} and is filed under T-ALL.
    const control = await evaluate({ key: REF_KEY, scope: { kind: 'PRODUCT', id: world.batch.tabletAll }, resolutionPoint: 'RELEASE', asOf: AS_OF });
    expect([control.subjectType, control.subjectId, control.marketSet, control.resolvedValue]).toEqual(['BATCH', world.batch.tabletAll, ['EU', 'IN', 'US'], '12']);
    // Positive control 2: I-ALL's management-review evaluation is SITE_LOOSENED and flagged on I-ALL.
    const controlMr = await evaluate({ key: MR_KEY, scope: { kind: 'PRODUCT', id: world.batch.injectableAll }, resolutionPoint: 'EXECUTION', asOf: AS_OF });
    expect([controlMr.subjectId, controlMr.siteOutcome, controlMr.effectiveValue]).toEqual([world.batch.injectableAll, 'SITE_LOOSENED', '15']);
    expect((await batchFlags(db.app, world.batch.injectableAll)).map((f) => f.evaluationId)).toContain(controlMr.id);

    // Attack 1: scope = T-IN ({IN}), subject = T-ALL.
    const swapped = await attempt(
      evaluate({
        key: REF_KEY,
        scope: { kind: 'PRODUCT', id: world.batch.tabletIn },
        subject: { type: 'BATCH', id: world.batch.tabletAll },
        resolutionPoint: 'RELEASE',
        asOf: AS_OF,
      }),
    );
    // Attack 2: scope = I-ALL (SITE_LOOSENED), subject = I-IN.
    const hidden = await attempt(
      evaluate({
        key: MR_KEY,
        scope: { kind: 'PRODUCT', id: world.batch.injectableAll },
        subject: { type: 'BATCH', id: world.batch.injectableIn },
        resolutionPoint: 'EXECUTION',
        asOf: AS_OF,
      }),
    );

    // 1. Every referenceSamples evaluation listed under T-ALL is T-ALL's own ({EU, IN, US}, 12).
    const underTAll = (await listEvaluations(db.app, world.batch.tabletAll)).filter((e) => e.key === REF_KEY);
    const foreignUnderTAll = underTAll
      .filter((e) => e.marketSet.join(',') !== 'EU,IN,US' || e.resolvedValue !== '12')
      .map((e) => `id=${e.id} scope=${e.scopeKind}:${e.scopeId === world.batch.tabletIn ? 'T-IN' : e.scopeId} markets=${e.marketSet.join(',')} value=${JSON.stringify(e.resolvedValue)}`);
    // ... and T-ALL's audit chain carries no such row.
    const { rows: chain } = await db.app.query<{ record_id: string }>(
      'select record_id from kernel.audit_event where chain_key = $1 and table_name = $2',
      [`market_evaluation:${world.batch.tabletAll}`, 'market.evaluation'],
    );
    const chainIds = new Set(chain.map((r) => r.record_id));
    const foreignInChain = typeof swapped === 'string' ? [] : chainIds.has(swapped.id) && swapped.marketSet.join(',') !== 'EU,IN,US' ? [swapped.id] : [];

    // 2. A stored SITE_LOOSENED evaluation of I-ALL is flagged on I-ALL.
    const flagsIAll = (await batchFlags(db.app, world.batch.injectableAll)).map((f) => f.evaluationId);
    const hiddenFlag =
      typeof hidden === 'string'
        ? 'REFUSED'
        : hidden.siteOutcome === 'SITE_LOOSENED' && !flagsIAll.includes(hidden.id)
          ? `HIDDEN: evaluation ${hidden.id} of scope I-ALL (${hidden.siteOutcome}, effective ${JSON.stringify(hidden.effectiveValue)}) filed under ${hidden.subjectId === world.batch.injectableIn ? 'I-IN' : hidden.subjectId}; batch_flags(I-ALL) omits it`
          : 'FLAGGED';

    expect({
      swappedRequest: typeof swapped === 'string' ? swapped.slice(0, 7) : `stored subject=${swapped.subjectId === world.batch.tabletAll ? 'T-ALL' : swapped.subjectId === world.batch.tabletIn ? 'T-IN' : swapped.subjectId} markets=${swapped.marketSet.join(',')} value=${JSON.stringify(swapped.resolvedValue)}`,
      foreignUnderTAll,
      foreignInChain,
      hiddenFlagSafe: hiddenFlag === 'REFUSED' || hiddenFlag === 'FLAGGED' ? 'SAFE' : hiddenFlag,
    }).toEqual({
      // Safe: refused, or filed under the scope's own batch T-IN.
      swappedRequest: typeof swapped === 'string' ? 'REFUSED' : `stored subject=T-IN markets=IN value="3"`,
      foreignUnderTAll: [],
      foreignInChain: [],
      hiddenFlagSafe: 'SAFE',
    });
  });
});

/**
 * Review reproducer F23: market.evaluate_stub_scope (0330) says "a PACK scope resolves a
 * PER_DESTINATION key for its own destination", but it fills in the pack's destination only when the
 * caller's stated.destination is null. A caller that names another destination of the batch's
