/** Evaluate as an OPERATOR (MARKET.RULE_EVALUATE). */
function evaluate(request: EvaluateStubScopeRequest): Promise<StoredEvaluation> {
  return asApp(db, (c) => evaluateStubScope(c, request), { roleCode: MARKET_ROLES.evaluator });
}

/** The stored evaluation, or the refusal code. */
async function attempt(p: Promise<StoredEvaluation>): Promise<StoredEvaluation | string> {
  try {
    return await p;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return `REFUSED ${/EBMR-[A-Z]+-\d+/.exec(message)?.[0] ?? message}`;
  }
}

function packDestination(e: StoredEvaluation): unknown {
  const pack = (e.marketDerivation as { source?: string; destination?: string }[]).find((d) => d.source === 'PACK');
  return pack?.destination;
}

describe('F23: a PACK scope resolves a PER_DESTINATION key only for its own destination', () => {
  it('[IN-52][IN-31][INV-28] an India-domestic pack cannot be resolved under the US label rule by naming destination US', async () => {
    // Positive control: without a destination, PK-IN resolves for IN.
    const control = await evaluate({
      key: KEY,
      scope: { kind: 'PACK', id: world.pack.tabletAllIn },
      resolutionPoint: 'EXECUTION',
      asOf: AS_OF,
      stated: { method: 'PER_DESTINATION', decisionRef: 'x' },
    });
    expect([control.resolvedValue, control.effectiveValue, control.governingMarkets, packDestination(control)]).toEqual([
      'MANDATORY_UNCODED',
      'MANDATORY_UNCODED',
      ['IN'],
      'IN',
    ]);

    // Attack: the same pack, naming destination US (inside the batch's market set {EU, IN, US}).
    const overridden = await attempt(
      evaluate({
        key: KEY,
        scope: { kind: 'PACK', id: world.pack.tabletAllIn },
        resolutionPoint: 'EXECUTION',
        asOf: AS_OF,
        stated: { method: 'PER_DESTINATION', decisionRef: 'x', destination: 'US' },
      }),
    );

    const observed =
      typeof overridden === 'string'
        ? 'REFUSED'
        : {
            packDestination: packDestination(overridden),
            resolvedValue: overridden.resolvedValue,
            effectiveValue: overridden.effectiveValue,
            governingMarkets: overridden.governingMarkets,
            statedDestination: (overridden.resolution as { stated?: { destination?: string } }).stated?.destination ?? null,
          };
    const safe =
      observed === 'REFUSED' ||
      (observed.resolvedValue === 'MANDATORY_UNCODED' &&
        observed.effectiveValue === 'MANDATORY_UNCODED' &&
        JSON.stringify(observed.governingMarkets) === '["IN"]' &&
        (observed.statedDestination === 'IN' || observed.statedDestination === null));

    expect(safe, `stored evaluation of PK-IN with stated destination US: ${JSON.stringify(observed)}`).toBe(true);
  });
});

/**
 * Review reproducer F24: the approvals that stand behind a loosening are free UUIDs that nothing
 * verifies.
 *
 *   - market.publish_rule_table (0340): a SOURCE_CORRECTION needs a citation and two distinct
 *     approverIds other than the publisher, but the ids are never checked against iam persons,
 *     roles or e-signatures. The outline (3.3.2, L-38) asks for two QA signatures.
 *   - market.set_site_value (0320): loosening a GUIDANCE value needs a justificationRef and any
 *     qaApprovalId uuid, so the steward can approve their own loosening.
 *   - market.set_policy_version / market.policy_version_guard (0350): a LOOSENING needs any
 *     approval_id uuid; policy.level (VENDOR / TENANT) and policy.loosening_requires
 *     (QA_APPROVAL / CHANGE_CONTROL / OWNER_CONFIRMATION) are stored but never checked.
 *
 * Safe behaviour asserted: each of these loosenings is refused when the named approval is not a
 * real e-signature by the named approver (random UUIDs, or real QA persons who signed nothing),
 * and a VENDOR-level policy that needs OWNER_CONFIRMATION cannot be loosened by the QA MBR
 * approver with an unverified approval id.
 *
 * Every attack runs in its own transaction that is rolled back, so the attacks are independent.
 * Positive controls, run first, show that the attack inputs are otherwise valid: the kernel v2
 * document validates and is a retroactive loosening (refused as an UPDATE with EBMR-MKT-031); the
 * steward may set a tighter site value for the key; the QA MBR approver may version the TENANT
 * policy. So a refusal of an attack can only come from the approval check.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { toDbContext, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';
import { MARKET_ROLES, publishSeedTables, seedDocument, seedStubWorld, type StubWorld } from '../market/helpers.ts';

