    // 3a. QA MBR approver loosens a TENANT policy (QA_APPROVAL) with an approval id that is no record at all.
    const attack3a = await attemptRolledBack(qaPolicy, POLICY_VERSION, [
      tenantPolicy,
      'OFF',
