      sourceCorrectionUnsignedQaApprovers: 'REFUSED',
      siteLooseningUnverifiedQaApproval: 'REFUSED',
      tenantPolicyLooseningUnverifiedApproval: 'REFUSED',
      vendorPolicyLooseningByQaMbrApprover: 'REFUSED',
