  });
});

/**
 * Review reproducer F25: an approved site loosening is re-applied to a later, different resolution
 * and is left out of the change-impact list.
 *
 *   - market.site_value_in_force (0320) picks the site value by (site, key, date) only; the
 *     resolution, table version, predicates and market set the approval was given against are
 *     stored on the row but never compared.
 *   - market.apply_site_value (0320) maps "LOOSENING against today's resolution, and the row was
 *     once LOOSENED" to SITE_LOOSENED and applies the site value.
 *   - market.compute_change_impact (0340) skips a site value when it is LOOSENING and approved
 *     (v_hit is false), so a new table version that moves the value being loosened creates no
 *     tracked change task (outline 3.3.5).
 *
 * Scenario (same shape as kernel.managementReview.maxIntervalMonths, B-24.IN GUIDANCE 12):
 *   1. v1 of a test table: IN GUIDANCE 12 months (SMALLER_STRICTER, no hard floor).
 *   2. The steward sets a site value of 18 with a justification and a QA approval: LOOSENED,
 *      approved against resolved value 12 (12 -> 18).
 *   3. v2 (UPDATE) tightens IN to 6 months. This is a tightening, so the UPDATE is allowed.
 *   4. A batch at the site is evaluated.
 *
 * Safe behaviour asserted: the new version produces a change-impact item for the approved
 * loosening (the value it loosens changed from 12 to 6), and the batch does not silently run the
 * 6 -> 18 loosening under the approval given for 12 -> 18 (it is not applied as SITE_LOOSENED with
 * effective value 18).
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { evaluateStubScope, setSiteValue } from '../../src/market/repository.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { asApp, createTestTable, MARKET_ROLES, publishDocument, seedStubWorld, type StubWorld } from '../market/helpers.ts';

let db: TestDatabase;
let world: StubWorld;

beforeAll(async () => {
  db = await createTestDatabase();
  world = await seedStubWorld(db);
});
afterAll(async () => {
  await db.drop();
});

describe('F25 approved site loosening bound to the resolution it was approved against', () => {
  it('[IN-52] [ST-01] an approved loosening is not re-applied after a new table version tightens the value it loosens, and it appears on the change-impact list', async () => {
    const table = `f25${randomUUID().slice(0, 6)}`;
    await createTestTable(db, table);
    const key = `${table}.reviewIntervalMonths`;
    const v1 = {
      table,
      version: 1,
      change: { kind: 'INITIAL', description: 'F25 test table' },
      keys: [{ key, title: 'Maximum interval between reviews', method: 'SMALLER_STRICTER', valueType: 'DECIMAL', unit: 'mo', indiaGoverns: true }],
      rows: [
        { ref: 'R.IN', key, market: 'IN', value: '12', unit: 'mo', floor: 'GUIDANCE', source: 'test source', verification: 'P', effectiveFrom: '2024-01-01' },
      ],
    };
    await publishDocument(db, v1);

    // Step 2: QA approves the loosening 12 -> 18.
    const approval = randomUUID();
    const sv = await asApp(
      db,
      (c) =>
        setSiteValue(c, {
          siteId: world.siteId,
          key,
          value: '18',
          effectiveFrom: '2026-01-01',
          justificationRef: 'JUST-12-TO-18',
          qaApprovalId: approval,
        }),
      { roleCode: MARKET_ROLES.siteValues },
    );
    expect(sv.outcome).toBe('LOOSENED');
    const { rows: stored } = await db.admin.query<{ approved_against: unknown }>(
      "select resolution -> 'value' as approved_against from market.site_value where id = $1",
      [sv.id],
    );
    expect(stored[0]?.approved_against).toBe('12');

    // Positive control: before the new version the approved loosening is applied as approved.
    const before = await asApp(db, (c) =>
      evaluateStubScope(c, { key, scope: { kind: 'PRODUCT', id: world.batch.tabletIn }, resolutionPoint: 'EXECUTION', asOf: '2026-03-01' }),
    );
    expect([before.resolvedValue, before.effectiveValue, before.siteOutcome]).toEqual(['12', '18', 'SITE_LOOSENED']);

    // Step 3: v2 tightens IN from 12 to 6 (an UPDATE may tighten retroactively).
    const v2 = {
      ...v1,
      version: 2,
      change: { kind: 'UPDATE', description: 'IN guidance tightened to 6 months' },
      rows: [{ ...v1.rows[0], value: '6' }],
    };
    const published = await publishDocument(db, v2);
    const { rows: impact } = await db.admin.query<{ ref_type: string; ref_id: string }>(
      'select ref_type, ref_id from market.change_impact where version_id = $1 and ref_id = $2',
      [published.versionId, sv.id],
    );

    // Step 4: a batch at the site is evaluated under v2.
    const after = await asApp(db, (c) =>
      evaluateStubScope(c, { key, scope: { kind: 'PRODUCT', id: world.batch.tabletIn }, resolutionPoint: 'EXECUTION', asOf: '2026-03-01' }),
    );

    const observed = {
      impactCount: published.impactCount,
      impactItemsForApprovedLoosening: impact.length,
      afterResolvedValue: after.resolvedValue,
      afterEffectiveValue: after.effectiveValue,
      afterSiteOutcome: after.siteOutcome,
    };
    // The resolved value really moved to 6 (the scenario is reached).
    expect(observed.afterResolvedValue).toBe('6');
    // Safe behaviour: a change-impact item exists for the approved loosening, and 18 is not applied
    // as an approved loosening against 6 (the approval covered 12 -> 18 only).
    expect({
      impactItemForApprovedLoosening: observed.impactItemsForApprovedLoosening > 0,
      appliesUnapprovedLoosening: observed.afterSiteOutcome === 'SITE_LOOSENED' && observed.afterEffectiveValue === '18',
      observed,
    }).toEqual({
      impactItemForApprovedLoosening: true,
      appliesUnapprovedLoosening: false,
      observed: expect.anything(),
    });
  });
});

/**
 * Review reproducer F26: concurrent market.apply_policy_tightening can leave a batch on a looser
 * policy position than one it already applied (INV-47 race).
 *
 *   - market.policy_pin_guard (0350) reads the batch's newest pin (v_cur) with no lock and compares
 *     the new version only against it.
 *   - The only serialisation point is the audit chain-head row lock taken in the AFTER trigger
 *     (kernel.audit_row_change), i.e. after the BEFORE guard has already passed.
 *   - market.batch_policy (0350) returns the newest pin by recorded_at, not the strictest one.
 *
 * Scenario:
 *   1. Policy positions [A, B, C] (least -> most strict), default A. A batch is issued: pinned at A.
 *   2. V2 = C (TIGHTENING). V3 = B (LOOSENING relative to C, approved, change reference).
 *   3. QA reviewer 1 applies V2 to the batch and has not committed yet.
 *   4. QA reviewer 2 applies V3 to the same batch; its guard sees only the issue pin (A), so B passes,
 *      and it then waits on the audit chain-head lock.
 *   5. Reviewer 1 commits, then reviewer 2 commits (if its call was accepted).
 *
 * Safe behaviour asserted: after both commands, the batch still applies C (the strictest position it
 * ever reached). Either reviewer 2's call is refused (EBMR-MKT-085), or at least what the batch
 * applies never drops from C back to B. Run one after the other, the second call is refused.
 */
import { randomUUID } from 'node:crypto';
import type pg from 'pg';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { toDbContext, withCommand, type ActorContext } from '../../src/db/command.ts';
import { applyPolicyTightening, batchPolicy, definePolicy, pinPoliciesForBatch, setPolicyVersion } from '../../src/market/policy.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';

let db: TestDatabase;
beforeAll(async () => {
  db = await createTestDatabase();
});
afterAll(async () => {
  await db.drop();
});

const ROLE = {
  policy: 'QA_MBR_APPROVER', // MARKET.POLICY_CHANGE
  tightening: 'QA_REVIEWER', // MARKET.POLICY_TIGHTEN_BATCH
  issuer: 'BATCH_ISSUER', // BATCH.ISSUE
} as const;

async function as<T>(roleCode: string, work: (c: pg.PoolClient) => Promise<T>): Promise<T> {
  return withCommand(db.app, await seededTestActor(db, { roleCode }), work);
}

async function begin(client: pg.PoolClient, ctx: ActorContext): Promise<void> {
  await client.query('begin');
  await client.query('select kernel.begin_command($1::jsonb)', [JSON.stringify(toDbContext(ctx))]);
}

/** Wait until the backend `pid` is waiting on a heavyweight lock, or `settled()` reports it finished. */
async function waitForLockWait(pid: number, settled: () => boolean, timeoutMs = 10_000): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (settled()) return false;
    const { rows } = await db.admin.query<{ waiting: boolean }>(
      "select coalesce(bool_or(wait_event_type = 'Lock'), false) as waiting from pg_stat_activity where pid = $1",
      [pid],
    );
    if (rows[0]?.waiting) return true;
    await new Promise((resolve) => setTimeout(resolve, 25));
  }
  return false;
}

describe('F26 concurrent policy tightenings on one batch', () => {
  it('[INV-47] [DI-09] two concurrent applications to one batch never leave it on a looser position than one it already applied', async () => {
    const code = `F26.pol${randomUUID().slice(0, 6)}`;
    await as(ROLE.policy, (c) =>
      definePolicy(c, { code, title: 'F26 policy', level: 'TENANT', positions: ['A', 'B', 'C'], defaultPosition: 'A', controls: ['DI-09'] }),
    );

    // Two batches issued at A: one for the sequential control, one for the concurrent scenario.
    const sequentialBatch = randomUUID();
    const batch = randomUUID();
    await as(ROLE.issuer, (c) => pinPoliciesForBatch(c, sequentialBatch));
    await as(ROLE.issuer, (c) => pinPoliciesForBatch(c, batch));
    expect((await batchPolicy(db.app, batch, code))?.position).toBe('A');

    const v2 = await as(ROLE.policy, (c) => setPolicyVersion(c, code, 'C', { changeRef: 'CC-V2' }));
    const v3 = await as(ROLE.policy, (c) => setPolicyVersion(c, code, 'B', { approvalId: randomUUID(), changeRef: 'CC-V3' }));
    expect([v2.position, v2.direction]).toEqual(['C', 'TIGHTENING']);
    expect([v3.position, v3.direction]).toEqual(['B', 'LOOSENING']);

    // Control: one after the other, the second application is refused and the batch stays at C.
    await as(ROLE.tightening, (c) => applyPolicyTightening(c, sequentialBatch, code, v2.id, 'CC-1'));
    await expect(as(ROLE.tightening, (c) => applyPolicyTightening(c, sequentialBatch, code, v3.id, 'CC-2'))).rejects.toThrow('EBMR-MKT-085');
    expect((await batchPolicy(db.app, sequentialBatch, code))?.position).toBe('C');

    // Concurrent: two QA reviewers on the same batch.
    const reviewer1 = await seededTestActor(db, { roleCode: ROLE.tightening });
    const reviewer2 = await seededTestActor(db, { roleCode: ROLE.tightening });
    const c1 = await db.app.connect();
    const c2 = await db.app.connect();
    let outcome2: string;
    let sawLockWait: boolean;
    try {
      const pid2 = (await c2.query<{ pid: number }>('select pg_backend_pid() as pid')).rows[0]?.pid as number;

      await begin(c1, reviewer1);
      await c1.query('select market.apply_policy_tightening($1, $2, $3, $4)', [batch, code, v2.id, 'CC-1']);

      await begin(c2, reviewer2);
      let done = false;
      const pending = c2
        .query('select market.apply_policy_tightening($1, $2, $3, $4)', [batch, code, v3.id, 'CC-2'])
        .then(
          () => 'APPLIED',
          (error: Error) => `REFUSED ${error.message}`,
        )
        .finally(() => {
          done = true;
        });

      // Reviewer 2 is past the BEFORE guard and waiting on reviewer 1's audit chain-head lock.
      sawLockWait = await waitForLockWait(pid2, () => done);

      await c1.query('commit');
      outcome2 = await pending;
      await c2.query(outcome2 === 'APPLIED' ? 'commit' : 'rollback');
    } finally {
      await c1.query('rollback').catch(() => undefined);
      await c2.query('rollback').catch(() => undefined);
      c1.release();
      c2.release();
    }

    const { rows: pins } = await db.admin.query<{ pin_kind: string; position: string }>(
      `select p.pin_kind, v.position from market.batch_policy_pin p join market.policy_version v on v.id = p.policy_version_id
        where p.batch_id = $1 and p.policy_code = $2 order by p.recorded_at, p.id`,
      [batch, code],
    );
    const applied = await batchPolicy(db.app, batch, code);
    const diagnostics = { sawLockWait, outcome2, pins, applied };

    // Safe behaviour: the batch reached C; nothing afterwards may drop it back to B (INV-47).
    expect(applied?.position, JSON.stringify(diagnostics)).toBe('C');
    // And the looser application must not have been recorded as a later pin on top of C.
    expect(pins.map((p) => p.position), JSON.stringify(diagnostics)).not.toContain('B');
  });
});

/**
 * Review reproducer F27: the "retroactive" test for rule-table loosenings uses the time zone the
 * client declares in its actor context.
 *
 *   - market.publish_rule_table (0340) computes today as
 *       (clock_timestamp() at time zone coalesce(v_ctx ->> 'site_zone', 'UTC'))::date
 *     and a loosening counts as retroactive (refused for an UPDATE, EBMR-MKT-031) only when its
 *     segment starts on or before that date.
 *   - kernel.begin_command (0010) and kernel.validate_actor_context (0190) check only that
 *     site_zone is non-empty; nothing compares it with the configured site zone
 *     (iam.policy_text('site.zone')), unlike esig (EBMR-ESIG-035).
 *   - PostgreSQL accepts POSIX zone strings such as 'X+167' (167 hours behind UTC), which moves
 *     "today" back by about seven days.
 *
 * Safe behaviour asserted: a kernel v2 UPDATE that loosens the India HARD self-inspection interval
 * (B-08, 12 months) to 36 months from five site days ago is refused when the steward's command
 * declares site_zone 'X+167', exactly as it is when the command declares the configured site zone.
 * Whether the refusal comes from the publish gate (EBMR-MKT-031) or from a zone check on the
 * command does not matter; accepting it does.
 *
 * Positive control, run first: the same document under the configured site zone is refused with
 * EBMR-MKT-031, so the document is otherwise valid and the loosening is in force in site time.
 * Every attempt runs in its own transaction that is rolled back.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { toDbContext, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';
import { SEED_ZONE } from '../identity/seed.ts';
import { MARKET_ROLES, publishSeedTables, seedDocument } from '../market/helpers.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
  await publishSeedTables(db);
});

afterAll(async () => {
  await db.drop();
});

type Attempt =
  | { accepted: true; result: Record<string, unknown>; resolvedValue: unknown }
  | { accepted: false; error: string };

const PUBLISH = 'select market.publish_rule_table($1::jsonb, $2::jsonb) as r';

/**
 * begin_command + publish as the application role, then roll back. A refusal at begin_command (a
 * zone check) or at the publish gate is returned as a refusal. When the publish is accepted, the
 * new version's resolution of the key for India at `asOf` is read in the same transaction.
 */
async function attemptPublish(ctx: ActorContext, doc: unknown, asOf: string): Promise<Attempt> {
  const client = await db.app.connect();
  try {
    await client.query('begin');
    try {
      await client.query('select kernel.begin_command($1::jsonb)', [JSON.stringify(toDbContext(ctx))]);
      const { rows } = await client.query<{ r: Record<string, unknown> }>(PUBLISH, [JSON.stringify(doc), '{}']);
      const result = rows[0]?.r ?? {};
      const { rows: res } = await client.query<{ r: { value: unknown } }>(
        "select market.resolve($1::uuid, 'kernel.selfInspection.maxIntervalMonths', array['IN'], '{}'::jsonb, $2::date) as r",
        [result['versionId'], asOf],
      );
      return { accepted: true, result, resolvedValue: res[0]?.r.value };
    } catch (error) {
      return { accepted: false, error: error instanceof Error ? error.message : String(error) };
    }
  } finally {
    await client.query('rollback');
    client.release();
  }
}

const code = (a: Attempt): string => (a.accepted ? 'ACCEPTED' : (/EBMR-[A-Z]+-\d+/.exec(a.error)?.[0] ?? a.error));

describe('F27: the retroactive-loosening test must use the site date, not a zone the client declares', () => {
  it('[IN-52] an UPDATE loosening a value in force since five site days ago is refused whatever site_zone the command declares', async () => {
    // --- Dates, computed by the database (no JavaScript clock).
    const { rows: d } = await db.admin.query<{ zone: string; today: string; from: string; as_of: string; skewed_today: string }>(
      `select z.zone,
              to_char(t.today, 'YYYY-MM-DD') as today,
              to_char(t.today - 5, 'YYYY-MM-DD') as "from",
              to_char(t.today - 3, 'YYYY-MM-DD') as as_of,
              to_char((clock_timestamp() at time zone 'X+167')::date, 'YYYY-MM-DD') as skewed_today
         from (select iam.policy_text('site.zone') as zone) z,
              lateral (select (clock_timestamp() at time zone z.zone)::date as today) t`,
    );
    const dates = d[0];
    expect(dates?.zone, 'configured site zone').toBe(SEED_ZONE);
    if (!dates) throw new Error('no dates');
    // The declared zone moves "today" back by more than five days.
    expect(dates.skewed_today < dates.from, `X+167 date ${dates.skewed_today} is before ${dates.from}`).toBe(true);

    // --- kernel v2 (UPDATE): B-08.IN.selfInspection (12 months, HARD, since 2023-12-28) ends five
    // site days ago and a 36-month India row takes over from that day. India coverage stays whole.
    const v2 = JSON.parse(JSON.stringify(seedDocument('kernel'))) as {
      version: number;
      change: Record<string, unknown>;
      rows: Record<string, unknown>[];
    };
    v2.version = 2;
    v2.change = { kind: 'UPDATE', description: 'self-inspection interval re-read' };
    const idx = v2.rows.findIndex((r) => r['ref'] === 'B-08.IN.selfInspection');
    expect(idx, 'seed row B-08.IN.selfInspection').toBeGreaterThanOrEqual(0);
    const b08 = v2.rows[idx] ?? {};
    expect([b08['value'], b08['floor'], b08['effectiveFrom']]).toEqual(['12', 'HARD', '2023-12-28']);
    expect(b08['effectiveTo'], 'seed row is open-ended').toBeUndefined();
    v2.rows[idx] = { ...b08, effectiveTo: dates.from };
    v2.rows.push({ ...b08, ref: 'B-08.IN.selfInspection.2', value: '36', effectiveFrom: dates.from });

    // --- Actors: the same master-data steward identity, declaring two zones.
    const steward = await seededTestActor(db, { roleCode: MARKET_ROLES.publisher }); // MASTER_DATA_STEWARD
    expect(steward.siteZone).toBe(SEED_ZONE);
    const skewed: ActorContext = { ...steward, siteZone: 'X+167' };

    // --- Positive control: in site time the loosening is already in force, so the UPDATE is refused.
    const control = await attemptPublish(steward, v2, dates.as_of);
    expect(code(control), `control: kernel v2 as an UPDATE under ${SEED_ZONE}`).toBe('EBMR-MKT-031');

    // --- Attack: the same document, the same steward, declaring site_zone 'X+167'.
    const attack = await attemptPublish(skewed, v2, dates.as_of);
    const detail = attack.accepted
      ? `accepted: loosening ${JSON.stringify(attack.result['loosening'])}; India resolves to ${JSON.stringify(attack.resolvedValue)} months on ${dates.as_of} (HARD value 12)`
      : attack.error;
    expect(code(attack), `attack: kernel v2 as an UPDATE under X+167 -> ${detail}`).not.toBe('ACCEPTED');
  });
});

/**
 * Review reproducer F29: a retention schedule can be put on any aggregate type, so the e-signatures
 * of a record can be scheduled, approved for disposal and purged on their own while the record they
 * sign is still retained.
 *
 *   - records.create_retention_schedule (0420) refuses only the retention machinery
 *     ('retention', 'retention_rule_set', 'record_hold', 'tombstone', 'true_copy'); the record type
 *     code is not tied to the aggregate type and the retention inputs are free.
 *   - records.purge (0440) deletes, for the schedule's aggregate type, the rows of every registered
 *     table (kernel.audited_table), disabling each insert-only guard. esig.signature,
 *     esig.signature_seal and esig.signature_invalidation are registered under aggregate type
 *     'esig_signature' keyed on aggregate_ref ('<type>:<id>' of the signed record) (0220).
 *
 * Safe behaviour asserted (outline 3.3.6 "audit trails and signatures follow their record", DI-47
 * "signature records at least as long as their subject record", Part 11.70): the signatures of a
 * record that is still retained survive any attempt to schedule, approve and purge them on their
 * own. Whether the refusal comes at scheduling, at the disposal approval or at the purge does not
 * matter; losing the signatures does.
 *
 * Two subjects, both still present and not scheduled for disposal themselves:
 *   1. a signed stub entry (esig_stub, the stand-in for steps and logbook entries), with a PERFORMED
 *      and a VERIFIED signature;
 *   2. the approval signature (RECORD_TYPE_APPROVED) of a record-type version in force in the
 *      record register (records.record_type_approval.approval_signature_id).
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import type { RetentionInputs } from '../../src/records/retention.ts';
import { createRetentionSchedule, purge } from '../../src/records/retention-store.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import type { SeededActor } from '../identity/seed.ts';
import { createStub, ensureSealKey, signStub, testActor as esigActor } from '../esig/helpers.ts';
import { again, approveDisposal, recordType, registerType, signerActor, testActor, withReason } from '../records/helpers.ts';

let db: TestDatabase;
let qa: ActorContext;
let qa2: SeededActor;
let retentionJob: ActorContext;

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
  await registerType(db, recordType('BATCH_PROCESSING_RECORD'));
  await registerType(db, recordType('F29_SIGNED_REGISTER_TYPE', { retentionKey: 'SUPPORTING_RECORD' }));
  // One QA reviewer holding RECORD.RETENTION_MANAGE and RECORD.DISPOSAL_APPROVE, and the retention job (RECORD.PURGE).
  qa = await testActor(db, { roleCode: 'QA_REVIEWER', legalName: 'QA Reviewer' });
  qa2 = await signerActor(db, 'QA_REVIEWER', 'QA Manager');
  retentionJob = await testActor(db, { source: 'SYSTEM', roleCode: 'SYSTEM', legalName: 'retention job' });
});

afterAll(async () => {
  await db.drop();
});

// Retention that ended long ago: India only, expiry 2010-01-31, so kept until 2011-01-31.
const PAST: RetentionInputs = { markets: ['IN'], manufactureDate: '2008-01-10', expiryDate: '2010-01-31' };

interface Attempt {
  scheduled: boolean;
  approved: boolean;
  purged: boolean;
  refusal: string | null;
}

/**
 * Schedules 'esig_signature:<subjectRef>' on its own, approves its disposal (a RECORD_DISPOSAL_APPROVED
 * signature by the QA reviewer, then records.approve_purge) and runs the retention job's purge.
 * Any refusal stops the attempt and is returned.
 */
async function purgeSignaturesOf(subjectRef: string): Promise<Attempt> {
  const attempt: Attempt = { scheduled: false, approved: false, purged: false, refusal: null };
  const key = `esig_signature:${subjectRef}`;
  try {
    await withCommand(db.app, again(qa), (c) => createRetentionSchedule(c, 'esig_signature', subjectRef, 'BATCH_PROCESSING_RECORD', PAST));
    attempt.scheduled = true;
    await approveDisposal(db, qa2, key, 'retention ended; signature records no longer needed');
    attempt.approved = true;
    await withCommand(db.app, withReason(retentionJob, 'RETENTION_ENDED', 'approved disposal'), (c) => purge(c, key));
    attempt.purged = true;
  } catch (error) {
    attempt.refusal = error instanceof Error ? error.message : String(error);
  }
  return attempt;
}

const count = async (sql: string, params: unknown[]): Promise<number> => {
  const { rows } = await db.admin.query<{ n: string }>(`select count(*)::text as n from (${sql}) x`, params);
  return Number(rows[0]?.n ?? '0');
};

describe('F29: signatures follow their record; they cannot be scheduled and purged on their own', () => {
  it('[DI-47][INV-22][DI-37] the signatures of a retained record survive a schedule, disposal approval and purge aimed at esig_signature:<record>', async () => {
    // --- Subject 1: a signed stub entry, PERFORMED by the operator and VERIFIED by an independent verifier.
    const operator = await esigActor(db);
    const verifier = await esigActor(db, { roleCode: 'VERIFIER' });
    const stub = await createStub(db, operator);
    await signStub(db, operator, stub, { meaning: 'PERFORMED' });
    await signStub(db, verifier, stub, { meaning: 'VERIFIED' });
    const stubRef = `esig_stub:${stub}`;
    const stubSignatures = () => count('select 1 from esig.signature where aggregate_ref = $1', [stubRef]);
    const stubSeals = () => count('select 1 from esig.signature_seal where aggregate_ref = $1', [stubRef]);
    const shownSignatures = async () => (await db.app.query('select * from esig.record_signatures($1, $2)', ['esig_stub', stub])).rowCount ?? 0;
    const stubExists = () => count('select 1 from esig.stub_signable where id = $1', [stub]);
    expect({ signatures: await stubSignatures(), seals: await stubSeals(), shown: await shownSignatures(), stubRow: await stubExists() }).toEqual({
      signatures: 2,
      seals: 2,
      shown: 2,
      stubRow: 1,
    });

    // --- Subject 2: the approval signature of a record-type version in force in the register.
    const { rows: reg } = await db.app.query<{ version: string; approval_signature_id: string }>(
      "select version::text as version, approval_signature_id::text as approval_signature_id from records.record_register where code = 'F29_SIGNED_REGISTER_TYPE'",
    );
    const version = reg[0]?.version ?? '';
    const approvalSignature = reg[0]?.approval_signature_id ?? '';
    const registerRef = `record_type_version:F29_SIGNED_REGISTER_TYPE:${version}`;
    const approvalSignatureRows = () => count('select 1 from esig.signature where id = $1 and aggregate_ref = $2', [approvalSignature, registerRef]);
    expect(await approvalSignatureRows()).toBe(1);

    // --- The attack: schedule the signatures on their own, approve their disposal, purge them.
    const onStub = await purgeSignaturesOf(stubRef);
    const onRegister = await purgeSignaturesOf(registerRef);

    // The signed records are still there (nothing scheduled them for disposal) ...
    expect(await stubExists()).toBe(1);
    expect(await count("select 1 from records.record_register where code = 'F29_SIGNED_REGISTER_TYPE'", [])).toBe(1);

    // ... so their signatures must still be there too, whatever step refused the attempt.
    expect({
      stub: { attempt: onStub, signatures: await stubSignatures(), seals: await stubSeals(), shown: await shownSignatures() },
      register: { attempt: onRegister, approvalSignatureRows: await approvalSignatureRows() },
    }).toMatchObject({
      stub: { attempt: { purged: false }, signatures: 2, seals: 2, shown: 2 },
      register: { attempt: { purged: false }, approvalSignatureRows: 1 },
    });
  });
});

/**
 * Review reproducer F30: a DI investigation of a person whose only act on a record is a signature
 * (verifier, witness, reviewer, approver) never links, holds or blocks the record that was signed.
 *
 *   - records.person_activity (0430) takes the aggregate from split_part(chain_key, ':', 1) of the
 *     person's row-level audit events. A signature row is audited on chain
 *     'esig_signature:<type>:<id>' and its challenge on 'esig_challenge:<type>:<id>' (0220), so the
 *     scope says aggregate 'esig_signature' / 'esig_challenge', never '<type>' / '<id>'.
 *   - records.link_investigation_scope (0430) links and holds 'esig_signature:esig_stub:<id>', not
 *     'esig_stub:<id>'.
 *   - records.open_blockers (0440) blocks '<type>:<id>' only when linked, or when the person has
 *     INSERT/UPDATE/DELETE events on chain '<type>:<id>' in the window; the signer's only event on
 *     that chain is a BUSINESS entry ("signed VERIFIED by ..."), which is filtered out.
 *
 * Safe behaviour asserted (DI-50 behaviour: "Linked records and audit trails go on hold until the
 * investigation closes: no archive purge and no disposal"; catalog_test: "The linked batches cannot be
 * disposed of until the investigation closes"): once an investigation is opened for the verifier over
 * a window in which the verifier signed two entries (one at their own terminal, one as a co-signature
 * at the performer's terminal), each signed entry is linked to the investigation, held, blocked for
 * disposition, and its disposal cannot be approved while the investigation is open.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { investigationScope, openDiInvestigation } from '../../src/records/investigations.ts';
import type { RetentionInputs } from '../../src/records/retention.ts';
import { createRetentionSchedule, openBlockers } from '../../src/records/retention-store.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import type { SeededActor } from '../identity/seed.ts';
import { createStub, ensureSealKey, signStub, testActor as esigActor } from '../esig/helpers.ts';
import { again, approveDisposal, recordType, registerType, signerActor, testActor } from '../records/helpers.ts';

let db: TestDatabase;
let performer: SeededActor;
let verifier: SeededActor;
let investigator: ActorContext;
let qa: SeededActor;

const now = async (): Promise<Date> => (await db.app.query<{ t: Date }>('select clock_timestamp() as t')).rows[0]?.t as Date;
const plusHours = (d: Date, h: number) => new Date(d.getTime() + h * 3_600_000);

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
  await registerType(db, recordType('BATCH_PROCESSING_RECORD'));
  // Shop-floor terminals with badge and PIN, so the verifier can also co-sign at the performer's terminal.
  performer = await esigActor(db, { deviceClass: 'SHARED', withPin: true, legalName: 'Performer' });
  verifier = await esigActor(db, { roleCode: 'VERIFIER', deviceClass: 'SHARED', withPin: true, legalName: 'Verifier under investigation' });
  investigator = await testActor(db, { roleCode: 'CSV_DI_LEAD', legalName: 'DI investigator' });
  qa = await signerActor(db, 'QA_REVIEWER', 'Head of QA');
});

afterAll(async () => {
  await db.drop();
});

// Retention that ended long ago: India only, expiry 2010-01-31, so kept until 2011-01-31.
const PAST: RetentionInputs = { markets: ['IN'], manufactureDate: '2008-01-10', expiryDate: '2010-01-31' };

describe('F30: a DI investigation holds and blocks the records the person signed', () => {
  it('[DI-50] records whose only involvement of the person is a signature (own terminal or co-signature) are linked, held and blocked', async () => {
    const from = await now();

    // Entry 1: the performer records and signs PERFORMED; the verifier signs VERIFIED at their own terminal.
    const stub1 = await createStub(db, performer, { value: '12.503' });
    await signStub(db, performer, stub1, { meaning: 'PERFORMED', method: 'BADGE_PIN' });
    await signStub(db, verifier, stub1, { meaning: 'VERIFIED', method: 'BADGE_PIN' });

    // Entry 2: the performer records and signs PERFORMED; the verifier co-signs VERIFIED at the performer's terminal.
    const stub2 = await createStub(db, performer, { value: '7.10' });
    await signStub(db, performer, stub2, { meaning: 'PERFORMED', method: 'BADGE_PIN' });
    const cosig = await signStub(db, performer, stub2, { meaning: 'VERIFIED', signer: verifier, method: 'BADGE_PIN' });
    expect(cosig.cosignature).toBe(true);

    // Preconditions: both VERIFIED signatures are the verifier's, and the verifier never wrote the entries' rows.
    const { rows: sigs } = await db.admin.query<{ aggregate_ref: string }>(
      "select aggregate_ref from esig.signature where signer_person = $1 and meaning_code = 'VERIFIED' order by aggregate_ref",
      [verifier.personId],
    );
    expect(sigs.map((r) => r.aggregate_ref).sort()).toEqual([`esig_stub:${stub1}`, `esig_stub:${stub2}`].sort());
    const { rows: direct } = await db.admin.query<{ n: string }>(
      "select count(*)::text as n from kernel.audit_event where chain_key in ($1, $2) and action in ('INSERT','UPDATE','DELETE') and payload -> 'actor' ->> 'person_id' = $3",
      [`esig_stub:${stub1}`, `esig_stub:${stub2}`, verifier.personId],
    );
    expect(direct[0]?.n).toBe('0');

    // The investigator opens a DI investigation of the verifier over the window.
    const id = await withCommand(db.app, again(investigator), (c) =>
      openDiInvestigation(c, {
        subjectPersonId: verifier.personId,
        windowFrom: from,
        windowTo: plusHours(from, 1),
        concern: 'verifications signed without witnessing the weighing',
        qmsReference: 'QMS-INV-F30',
      }),
    );

    // The scoping report does see the verifier's signatures (so the window and person are right).
    const scope = await investigationScope(db.app, id);
    expect(scope.some((s) => s.tableName === 'esig.signature')).toBe(true);

    // Safe behaviour: the signed entries themselves are linked, held and blocked while the investigation is open.
    const { rows: links } = await db.app.query<{ record_key: string }>(
      'select record_key from records.di_investigation_link where investigation_id = $1 order by record_key',
