/** The authoritative database evaluation (records.evaluate_retention, 0420). */
async function sqlEvaluate(inputs: RetentionInputs): Promise<OwnRetention> {
  const { rows } = await db.app.query<{ r: OwnRetention }>(
    `select records.evaluate_retention(records.normalize_retention_inputs($1::jsonb) || jsonb_build_object('retentionKey', 'BATCH_RECORD')) as r`,
    [JSON.stringify(inputs)],
  );
  return rows[0]?.r as OwnRetention;
}

async function effectiveOf(recordKey: string): Promise<EffectiveRetention> {
  const { rows } = await db.app.query<{ e: EffectiveRetention }>(
    'select records.compute_effective_retention(s.id) as e from records.retention_schedule s where s.record_key = $1',
    [recordKey],
  );
  return rows[0]?.e as EffectiveRetention;
}

describe('F31 Schedule M expiry + 1 year when the expiry date is unknown', () => {
  it('[DI-47][INV-22] India Form 25 batch without an expiry date: Schedule M rule is OPEN (MISSING_INPUT:EXPIRY), not manufacture + 5 years', async () => {
    const r = await sqlEvaluate({ markets: ['IN'], licenceForm: 'FORM_25', manufactureDate: '2026-01-10' });
    const scheduleM = r.evaluated.find((e) => e.ruleId === 'IN_SCHEDULE_M_EXPIRY');
    expect({ status: r.status, retainUntil: r.retainUntil, openReasons: r.openReasons, scheduleM }).toEqual({
      status: 'OPEN',
      retainUntil: null,
      openReasons: ['MISSING_INPUT:EXPIRY'],
      scheduleM: { ruleId: 'IN_SCHEDULE_M_EXPIRY', status: 'OPEN', date: null, reason: 'MISSING_INPUT:EXPIRY' },
    });
  });

  it('[DI-47][INV-22] India Form 28 batch without an expiry date: retention stays OPEN (Schedule M expiry + 1 year cannot be computed)', async () => {
    const r = await sqlEvaluate({ markets: ['IN'], licenceForm: 'FORM_28', manufactureDate: '2026-01-10' });
    expect({ status: r.status, retainUntil: r.retainUntil }).toEqual({ status: 'OPEN', retainUntil: null });
    expect(r.openReasons).toContain('MISSING_INPUT:EXPIRY');
  });

  it('[DI-47][INV-22] clearing a Form 25 batch expiry with update_retention_inputs leaves the stored effective retention OPEN, not DATED 2031-01-10', async () => {
    const batch = randomUUID();
    const key = `batch:${batch}`;
    await withCommand(db.app, again(qa), (c) =>
      createRetentionSchedule(c, 'batch', batch, 'BATCH_PROCESSING_RECORD', {
        markets: ['IN'],
        licenceForm: 'FORM_25',
        manufactureDate: '2026-01-10',
        expiryDate: '2031-01-31',
      }),
    );
    // With the real 60-month expiry the Schedule M floor governs.
    expect(await effectiveOf(key)).toMatchObject({ status: 'DATED', retainUntil: '2032-01-31' });

    const afterClear = await withCommand(db.app, again(qa), (c) =>
      updateRetentionInputs(c, key, { expiryDate: null }, 'expiry under re-assessment after stability excursion'),
    );
    expect({ status: afterClear.status, retainUntil: afterClear.retainUntil }).toEqual({ status: 'OPEN', retainUntil: null });

    const { rows } = await db.app.query<{ effective_status: string; effective_retain_until: string | null }>(
      "select effective_status, to_char(effective_retain_until, 'YYYY-MM-DD') as effective_retain_until from records.retention_evaluation where record_key = $1 order by id desc limit 1",
      [key],
    );
    expect(rows[0]).toEqual({ effective_status: 'OPEN', effective_retain_until: null });
  });
});

/**
 * Review reproducer F32: a record whose record type has retention key PERMANENT ("kept for the life of
 * the installation (no rule applies, so retention stays OPEN)", retention-rules.ts:25) gets own status
 * NONE, because no retention rule lists PERMANENT. records.compute_effective_retention (0420 line 440,
 * mirror combineEffectiveRetention in retention.ts) treats a NONE node as OPEN only while it has no
 * dependants. As soon as any record is linked as depending on the PERMANENT record, the PERMANENT record
 * takes the latest retain-until of its dependants, becomes DATED, and approve_purge / purge accept it.
 *
 * Safe behaviour asserted (retention-rules.ts:25 PERMANENT; DI-47; INV-22 "nothing is purged unless its
 * retention has ended"): a PERMANENT record stays OPEN whatever depends on it, disposal approval and
 * purge are refused, and its rows are still there.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import type { RetentionInputs } from '../../src/records/retention.ts';
import { createRetentionSchedule, linkRetentionDependency, purge, retentionOf } from '../../src/records/retention-store.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import type { SeededActor } from '../identity/seed.ts';
import { again, approveDisposal, createStubTables, recordType, registerType, scalar, signerActor, testActor, withReason } from '../records/helpers.ts';

let db: TestDatabase;
let operator: ActorContext;
let qa: ActorContext;
let qa2: SeededActor;
let retentionJob: ActorContext;

beforeAll(async () => {
  db = await createTestDatabase();
  await createStubTables(db);
  await registerType(db, recordType('BATCH_PROCESSING_RECORD'));
  await registerType(db, recordType('PERM_DOC', { retentionKey: 'PERMANENT' }));
  operator = await testActor(db, { roleCode: 'OPERATOR' });
  qa = await testActor(db, { roleCode: 'QA_REVIEWER', legalName: 'QA Reviewer' });
  qa2 = await signerActor(db, 'QA_REVIEWER', 'QA Manager');
  retentionJob = await testActor(db, { source: 'SYSTEM', roleCode: 'SYSTEM', legalName: 'retention job' });
});
afterAll(async () => {
  await db.drop();
});

const PAST_BATCH: RetentionInputs = { markets: ['IN', 'US'], manufactureDate: '2008-01-10', expiryDate: '2010-01-31' };

/** Runs a step and reports whether it was refused (and with what), instead of throwing. */
async function outcome(step: () => Promise<unknown>): Promise<string> {
  try {
    await step();
    return 'ACCEPTED';
  } catch (e) {
    const m = /EBMR-[A-Z]+-\d+/.exec((e as Error).message);
    return `REFUSED ${m ? m[0] : (e as Error).message}`;
  }
}

describe('F32 PERMANENT retention with dependants', () => {
  it('[DI-47][INV-22] a PERMANENT record stays OPEN and cannot be approved for disposal or purged once a record depends on it', async () => {
    const doc = randomUUID();
    const batch = randomUUID();
    const docKey = `component_lot:${doc}`;
    await withCommand(db.app, again(operator), (c) => c.query("insert into stub_b4.lot_record (lot_id, note) values ($1, 'permanent document')", [doc]));
    await withCommand(db.app, again(qa), async (c) => {
      await createRetentionSchedule(c, 'component_lot', doc, 'PERM_DOC', { markets: ['IN'] });
      await createRetentionSchedule(c, 'batch', batch, 'BATCH_PROCESSING_RECORD', PAST_BATCH);
    });

    // Sanity: before any dependency, the PERMANENT record is OPEN (no rule applies) and the batch ended on 2011-01-31.
    const before = await retentionOf(db.app, 'component_lot', doc);
    expect(before.retentionKey).toBe('PERMANENT');
    expect(before.own.status).toBe('NONE');
    expect(before.effective).toMatchObject({ status: 'OPEN', openBecause: [{ recordKey: docKey, reasons: ['NO_RULE_APPLIES'] }] });
    expect((await retentionOf(db.app, 'batch', batch)).effective).toMatchObject({ status: 'DATED', retainUntil: '2011-01-31' });

    // A batch that ended long ago is linked as depending on the PERMANENT record.
    await withCommand(db.app, again(qa), (c) => linkRetentionDependency(c, docKey, `batch:${batch}`, 'USED_BY'));

    const after = await retentionOf(db.app, 'component_lot', doc);
    const approval = await outcome(() => approveDisposal(db, qa2, docKey, 'retention ended'));
    const purged = await outcome(() =>
      withCommand(db.app, withReason(retentionJob, 'RETENTION_ENDED', 'approved disposal'), (c) => purge(c, docKey)),
    );
    const rowsLeft = await scalar<string>(db.app, 'select count(*)::text as v from stub_b4.lot_record where lot_id = $1', [doc]);
    const tombstones = await scalar<string>(db.app, 'select count(*)::text as v from records.tombstone where record_key = $1', [docKey]);

    expect({
      effectiveStatus: after.effective.status,
      effectiveRetainUntil: after.effective.retainUntil,
      approval,
      purged,
      rowsLeft,
      tombstones,
    }).toEqual({
      effectiveStatus: 'OPEN',
      effectiveRetainUntil: null,
      approval: 'REFUSED EBMR-REC-030',
      purged: expect.stringMatching(/^REFUSED EBMR-REC-03\d$/),
      rowsLeft: '1',
      tombstones: '0',
    });
  });
});

/**
 * Review reproducer F33: one QA reviewer can shorten a record's retention by rewriting its retention
 * inputs (records.update_retention_inputs, 0420) and then give the disposal approval for the shortened
 * date (RECORD_DISPOSAL_APPROVED signature + records.approve_purge, 0440 / 0720). The purge itself then
 * runs under the unattended retention job, so no second person ever looks at the record.
 *
 * Scenario: an EU batch {markets:[IN,EU], expiryDate:2010-01-31} with no QP certification date is OPEN
 * (PENDING_EU_CERTIFICATION). QA reviewer X drops EU from the market set with a reason only, which
 * makes the batch DATED 2011-01-31, then signs and approves its disposal. The retention job purges it.
 *
 * Safe behaviour asserted (DI-47 "Tenants may lengthen retention, never shorten it" and "No user ...
 * can delete a record during retention"; INV-22; DI-37 independence of the disposal approval): the
 * person who changed the inputs that ended an OPEN retention cannot also approve its disposal on their
 * own, so the approval is refused (either the shortening change was refused / held for an independent
 * approval and the record stays OPEN, or approve_purge / the signature refuses X), the purge is refused,
 * and every row of the batch is still there with no tombstone.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import type { RetentionInputs } from '../../src/records/retention.ts';
import { createRetentionSchedule, purge, retentionOf, updateRetentionInputs } from '../../src/records/retention-store.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import type { SeededActor } from '../identity/seed.ts';
import {
  again,
  approveDisposal,
  correctEntry,
  createStubTables,
  insertEntry,
  insertReading,
  recordType,
  registerType,
  scalar,
  signerActor,
  testActor,
  withReason,
} from '../records/helpers.ts';

let db: TestDatabase;
let operator: ActorContext;
let qa: ActorContext;
let reviewerX: SeededActor;
let retentionJob: ActorContext;

beforeAll(async () => {
  db = await createTestDatabase();
  await createStubTables(db);
  await registerType(db, recordType('BATCH_PROCESSING_RECORD'));
  operator = await testActor(db, { roleCode: 'OPERATOR' });
  qa = await testActor(db, { roleCode: 'QA_REVIEWER', legalName: 'QA Reviewer' });
  reviewerX = await signerActor(db, 'QA_REVIEWER', 'QA Reviewer X');
  retentionJob = await testActor(db, { source: 'SYSTEM', roleCode: 'SYSTEM', legalName: 'retention job' });
});
afterAll(async () => {
  await db.drop();
});

// An exported EU batch that expired long ago but whose QP certification date was never received.
const EU_BATCH_PENDING_CERT: RetentionInputs = { markets: ['IN', 'EU'], manufactureDate: '2008-01-10', expiryDate: '2010-01-31' };

/** Runs a step and reports whether it was refused (and with what), instead of throwing. */
async function outcome(step: () => Promise<unknown>): Promise<string> {
  try {
    await step();
    return 'ACCEPTED';
  } catch (e) {
    const m = /EBMR-[A-Z]+-\d+/.exec((e as Error).message);
    return `REFUSED ${m ? m[0] : (e as Error).message}`;
  }
}

const rowCount = async (batch: string): Promise<string> =>
  scalar<string>(
    db.app,
    'select ((select count(*) from stub_b4.batch_entry where batch_id = $1) + (select count(*) from stub_b4.batch_reading where batch_id = $1))::text as v',
    [batch],
  );

describe('F33 one QA reviewer shortens retention and approves the disposal alone', () => {
  it('[DI-47][INV-22] the person who ended an OPEN retention by changing its inputs cannot alone approve the disposal, and the batch is not purged', async () => {
    const batch = randomUUID();
    const key = `batch:${batch}`;
    const entry = await insertEntry(db, operator, batch, '12.503');
    await correctEntry(db, operator, entry, '12.530');
    await insertReading(db, operator, batch, '7.10');
    // The schedule is created by another QA reviewer (not X).
    await withCommand(db.app, again(qa), (c) => createRetentionSchedule(c, 'batch', batch, 'BATCH_PROCESSING_RECORD', EU_BATCH_PENDING_CERT));

    // Sanity: the batch is OPEN because the EU certification date is pending; nothing may be disposed of.
    const before = await retentionOf(db.app, 'batch', batch);
    expect(before.effective).toMatchObject({ status: 'OPEN', openBecause: [{ recordKey: key, reasons: ['PENDING_EU_CERTIFICATION'] }] });
    const rowsBefore = await rowCount(batch);
    expect(rowsBefore).toBe('2');

    // QA reviewer X removes EU from the market set, with a reason only.
    const inputChange = await outcome(() =>
      withCommand(db.app, again(reviewerX), (c) => updateRetentionInputs(c, key, { markets: ['IN'] }, 'market set corrected')),
    );
    const afterChange = await retentionOf(db.app, 'batch', batch);

    // The same X signs RECORD_DISPOSAL_APPROVED for the record at its (new) retain-until and approves the purge.
    const approval = await outcome(() => approveDisposal(db, reviewerX, key, 'retention ended'));

    // The unattended retention job purges it.
    const purged = await outcome(() => withCommand(db.app, withReason(retentionJob, 'RETENTION_ENDED', 'approved disposal'), (c) => purge(c, key)));

    const rowsLeft = await rowCount(batch);
    const tombstones = await scalar<string>(db.app, 'select count(*)::text as v from records.tombstone where record_key = $1', [key]);
    const chainEvents = await scalar<string>(db.app, 'select count(*)::text as v from kernel.audit_event where chain_key = $1', [key]);

    expect({
      inputChange,
      effectiveAfterChange: `${afterChange.effective.status} ${afterChange.effective.retainUntil ?? 'open'}`,
      approval: approval.startsWith('REFUSED') ? 'REFUSED' : approval,
      purged: purged.startsWith('REFUSED') ? 'REFUSED' : purged,
      rowsLeft,
      tombstones,
      chainKept: Number(chainEvents) > 0,
    }).toEqual({
      inputChange: expect.any(String),
      effectiveAfterChange: expect.any(String),
      approval: 'REFUSED',
      purged: 'REFUSED',
      rowsLeft: rowsBefore,
      tombstones: '0',
      chainKept: true,
    });
  });
});

/**
 * Review reproducer F34 (part b, the database side): a disposal approval can cite, as the archived
 * true copy of the record, a bundle built with buildTrueCopyBundle(..., { tables: [subset] }) that
 * leaves out a whole registered table of the aggregate type. records.register_true_copy (0440) checks
 * only that the head seq/hash exist, records.approve_purge only that the copy belongs to the record, and
 * records.purge (EBMR-REC-038) only that the copy's head equals the kept head. The purge then deletes
 * the rows of the omitted table and the chain events, and the tombstone records the subset bundle's
 * manifest SHA-256 as the true copy of the purged record. Rows of an omitted insert-only table exist in
 * the audit chain only as row_hash (0010 kernel.audit_row_change), so their values are gone for good.
 *
 * Scenario: batch B with a corrected entry (stub_b4.batch_entry, mutable) and two insert-only readings
 * (stub_b4.batch_reading) whose value 7.1234567 appears nowhere else. Its retention ended. QA builds a
 * true copy with tables ['stub_b4.batch_entry'] only (the offline verifier reports it VERIFIED), registers
 * it, signs and approves the disposal citing it; the retention job purges B.
 *
 * Safe behaviour asserted (DI-47 controlled disposal; INV-22 purge leaves a tombstone; the purge
 * comment "an archived true copy cited by the approval must cover exactly this head, so the archive is
 * complete at the moment of purge"): a copy that does not hold every registered table with rows of the
 * record is refused as the archive (at registration, approval or purge), the readings are still there
 * and no tombstone names that copy. A control batch archived with every table is approved and purged
 * through the same helpers, so a refusal of the subset copy cannot come from the test's setup.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import type { RetentionInputs } from '../../src/records/retention.ts';
import { createRetentionSchedule, purge } from '../../src/records/retention-store.ts';
import { buildTrueCopyBundle, registerTrueCopy, serializeBundle, verifyTrueCopyBundleText } from '../../src/records/true-copy.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import type { SeededActor } from '../identity/seed.ts';
import {
  again,
  approveDisposal,
  correctEntry,
  createStubTables,
  insertEntry,
  insertReading,
  recordType,
  registerType,
  scalar,
  signerActor,
  testActor,
  withReason,
} from '../records/helpers.ts';

let db: TestDatabase;
let operator: ActorContext;
let qa: ActorContext;
let qa2: SeededActor;
let retentionJob: ActorContext;

beforeAll(async () => {
  db = await createTestDatabase();
  await createStubTables(db);
  await registerType(db, recordType('BATCH_PROCESSING_RECORD'));
  operator = await testActor(db, { roleCode: 'OPERATOR' });
  qa = await testActor(db, { roleCode: 'QA_REVIEWER', legalName: 'QA Reviewer' });
  qa2 = await signerActor(db, 'QA_REVIEWER', 'QA Manager');
  retentionJob = await testActor(db, { source: 'SYSTEM', roleCode: 'SYSTEM', legalName: 'retention job' });
});
afterAll(async () => {
  await db.drop();
});

const PAST_BATCH: RetentionInputs = { markets: ['IN', 'US'], manufactureDate: '2008-01-10', expiryDate: '2010-01-31' };
const READING_VALUE = '7.1234567';
const UUID = /^[0-9a-f-]{36}$/;

async function batchWithRecords(): Promise<string> {
  const batch = randomUUID();
  const entry = await insertEntry(db, operator, batch, '12.503');
  await correctEntry(db, operator, entry, '12.530');
  await insertReading(db, operator, batch, READING_VALUE);
  await insertReading(db, operator, batch, '8.7654321');
  await withCommand(db.app, again(qa), (c) => createRetentionSchedule(c, 'batch', batch, 'BATCH_PROCESSING_RECORD', PAST_BATCH));
  return batch;
}

const runPurge = (key: string) => withCommand(db.app, withReason(retentionJob, 'RETENTION_ENDED', 'approved disposal'), (c) => purge(c, key));

describe('F34 true copy cited by a disposal approval', () => {
  it('[F34][DI-47][INV-22] a true copy that leaves out a registered table holding rows of the record is not accepted as the archive of a purge', async () => {
    // Control: the same flow with a copy of every registered table is approved and purged.
    const control = await batchWithRecords();
    const controlKey = `batch:${control}`;
    const full = await buildTrueCopyBundle(db.app, { chainKey: controlKey });
    expect((JSON.parse(full.manifest) as { tables: string[] }).tables).toEqual(expect.arrayContaining(['stub_b4.batch_entry', 'stub_b4.batch_reading']));
    expect(verifyTrueCopyBundleText(serializeBundle(full)).ok).toBe(true);
    const fullCopy = await withCommand(db.app, again(qa2), (c) => registerTrueCopy(c, full, 'archive before disposal'));
    await approveDisposal(db, qa2, controlKey, 'retention ended; archived true copy verified', fullCopy);
    await expect(runPurge(controlKey)).resolves.toMatch(UUID);

    // The record under test: archived with the insert-only readings table left out.
    const batch = await batchWithRecords();
    const key = `batch:${batch}`;
    const subset = await buildTrueCopyBundle(db.app, { chainKey: key, tables: ['stub_b4.batch_entry'] });
    const subsetText = serializeBundle(subset);
    const offline = verifyTrueCopyBundleText(subsetText);
    // Facts about the subset bundle (not the defect): the offline verifier calls it verified, the chain
    // part holds the readings' INSERT events, but the reading values are nowhere in the bundle.
    expect(offline.ok).toBe(true);
    expect(subsetText).toContain('stub_b4.batch_reading');
    expect(subsetText).not.toContain(READING_VALUE);
    expect(await scalar<string>(db.app, 'select count(*)::text as v from stub_b4.batch_reading where batch_id = $1', [batch])).toBe('2');

    let refusal: string | undefined;
    let copyId: string | undefined;
    try {
      copyId = await withCommand(db.app, again(qa2), (c) => registerTrueCopy(c, subset, 'archive before disposal'));
      await approveDisposal(db, qa2, key, 'retention ended; archived true copy verified', copyId);
      await runPurge(key);
    } catch (error) {
      refusal = (error as Error).message;
    }

    const readingsLeft = await scalar<string>(db.app, 'select count(*)::text as v from stub_b4.batch_reading where batch_id = $1', [batch]);
    const { rows: tombstones } = await db.app.query<{ true_copy_id: string | null; true_copy_manifest_sha256: string | null; purged_tables: unknown }>(
      'select true_copy_id, true_copy_manifest_sha256, purged_tables from records.tombstone where record_key = $1',
      [key],
    );
    const outcome = {
      refused: refusal !== undefined,
      readingsLeft,
      tombstoneCitingTheSubsetCopy: tombstones.some((t) => t.true_copy_manifest_sha256 === subset.manifestSha256),
    };
    const detail =
      `purge of ${key} cited true copy ${copyId ?? '?'} (manifest tables ${JSON.stringify((JSON.parse(subset.manifest) as { tables: string[] }).tables)}, ` +
      `sha256 ${subset.manifestSha256}); refusal: ${refusal ?? 'none'}; tombstones: ${JSON.stringify(tombstones)}`;
    expect(outcome, detail).toEqual({ refused: true, readingsLeft: '2', tombstoneCitingTheSubsetCopy: false });
  });
});

/**
 * Review reproducer F35: an implicit DI-investigation blocker (the person investigated writes to a
 * record inside the window after the investigation was opened) appears without moving the record's
 * blocker epoch.
 *
 *   - records.open_blockers (0440) blocks a record for disposition when an OPEN investigation is linked
 *     to it, or when the investigated person has INSERT/UPDATE/DELETE audit events on the record's
 *     chain inside the window (the implicit branch).
 *   - The blocker-epoch contract (0400, "Blocker epoch (outline 5.7)"; retention-store.ts
 *     lockBlockerEpoch): the release module evaluates open_blockers outside the signing transaction,
 *     then inside it locks the epoch with records.lock_blocker_epoch and refuses if the epoch moved.
 *   - The person's write goes through the ordinary audit trigger and never calls
 *     records.bump_blocker_epoch; the record is linked (and the epoch bumped) only on the next
 *     refresh_di_investigation_scope or at closure.
 *
 * Safe behaviour asserted: when a new disposition blocker appears on a record between the evaluation
 * of open_blockers and the signing transaction, the epoch the signing transaction locks differs from
 * the one seen at evaluation, so the release module's "epoch unchanged" check refuses.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { openDiInvestigation } from '../../src/records/investigations.ts';
import { lockBlockerEpoch, openBlockers } from '../../src/records/retention-store.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { again, createStubTables, insertEntry, testActor } from '../records/helpers.ts';

