let subject: ActorContext;
let colleague: ActorContext;
let investigator: ActorContext;
let releaser: ActorContext;

const now = async (): Promise<Date> => (await db.app.query<{ t: Date }>('select clock_timestamp() as t')).rows[0]?.t as Date;
const plusHours = (d: Date, h: number) => new Date(d.getTime() + h * 3_600_000);

beforeAll(async () => {
  db = await createTestDatabase();
  await createStubTables(db);
  subject = await testActor(db, { roleCode: 'OPERATOR', legalName: 'Operator under investigation' });
  colleague = await testActor(db, { roleCode: 'OPERATOR', legalName: 'Colleague' });
  investigator = await testActor(db, { roleCode: 'CSV_DI_LEAD', legalName: 'DI investigator' });
  releaser = await testActor(db, { roleCode: 'QA_REVIEWER', legalName: 'QA releaser' });
});

afterAll(async () => {
  await db.drop();
});

describe('F35: an implicit DI-investigation blocker moves the blocker epoch', () => {
  it('[DI-50][DI-12] a write by the person investigated inside the window, after opening, moves the epoch of the record it blocks', async () => {
    const batch = randomUUID();
    // The batch is being made by a colleague; the person investigated has not touched it yet.
    await insertEntry(db, colleague, batch, '4.20');

    const from = await now();
    const id = await withCommand(db.app, again(investigator), (c) =>
      openDiInvestigation(c, { subjectPersonId: subject.personId, windowFrom: from, windowTo: plusHours(from, 1), concern: 'suspected back-dating' }),
    );
    expect(id).toMatch(/^[0-9a-f-]{36}$/);

    // Release module, evaluation outside the signing transaction: nothing blocks the batch; epoch E0.
    const evaluated = await openBlockers(db.app, 'batch', batch);
    expect(evaluated.filter((b) => b.blocksDisposition)).toEqual([]);
    const epochAtEvaluation = await withCommand(db.app, again(releaser), (c) => lockBlockerEpoch(c, 'batch', batch));

    // The person investigated now writes to the batch inside the investigation window.
    await insertEntry(db, subject, batch, '5.55');

    // A disposition blocker has appeared on the batch (precondition: the implicit branch of open_blockers).
    const after = await openBlockers(db.app, 'batch', batch);
    expect(after.filter((b) => b.blocksDisposition).map((b) => [b.kind, b.id])).toEqual([['DI_INVESTIGATION', id]]);

    // Release module, inside the signing transaction: lock the epoch and compare. Because a new
    // disposition blocker appeared since evaluation, the epoch must have moved so the release refuses.
    const epochAtSigning = await withCommand(db.app, again(releaser), (c) => lockBlockerEpoch(c, 'batch', batch));
    expect(
      epochAtSigning,
      `blocker epoch still ${epochAtSigning} although DI investigation ${id} now blocks disposition of batch:${batch}; a release evaluated before the write passes the epoch check`,
    ).not.toBe(epochAtEvaluation);
  });
});

/**
 * Review reproducer F41: the state engine (platform.transition, kernel 0550) accepts for a
 * signature-bearing transition any valid, unused signature of the right meaning on the aggregate
 * (platform.verify_signature -> esig.platform_signature_check -> esig.signature_problem, 0230). It
 * does not bind the signature to the from-state or version of the aggregate (the signed envelope,
 * esig.canonical_envelope 0200, hashes only content_version and content, never the state), and the
 * SIGNATURE hook ignores the actor. esig independence (esig.check_independence) looks only at
 * signers that came BEFORE: APPROVED excludes earlier PREPARED/CHECKED signers, CHECKED excludes
 * only PREPARED signers. Signing in reverse order defeats INV-04 (checker != approver).
 *
 * Scenario (sample_record machine v1: DRAFT -SUBMIT-> SUBMITTED -CHECK[CHECKED]-> CHECKED -APPROVE[APPROVED]-> APPROVED):
 *   1. The author creates sample record R (DRAFT, version 1).
 *   2. Person P holds MBR_CHECKER and QA_MBR_APPROVER. As QA_MBR_APPROVER, P signs APPROVED on R
 *      while it is still DRAFT (esig.sign with expected state DRAFT): no CHECKED signer exists yet,
 *      so the independence rule passes.
 *   3. The author submits R (version 2, SUBMITTED).
 *   4. P, as MBR_CHECKER, signs CHECKED (independent only of PREPARED, so it passes) and fires CHECK
 *      (version 3, CHECKED).
 *   5. A QA reviewer (holds SAMPLE_RECORD.APPROVE) fires APPROVE with P's early APPROVED signature.
 *
 * Safe behaviour asserted (INV-04, DI-35, DI-37): the reverse-order attack is refused at some step
 * (by the state engine binding the signature to the from-state/version or the actor, or by esig
 * independence being symmetric); R never becomes APPROVED with the same person as checker and
 * approver, on an approval signature applied before the check. Any refusal must be a business
 * refusal of the e-signature module or the state engine (not a setup mistake).
 *
 * Positive controls: (a) in the normal order (P checks first, then tries to approve) esig refuses
 * with EBMR-ESIG-043, so the two-role setup is right and INV-04 is meant to hold; (b) with an
 * independent approver the same record flow reaches APPROVED, so roles, provider and seal key work.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand } from '../../src/db/command.ts';
import { decideRoleGrant, requestRoleGrant } from '../../src/identity/admin.ts';
import { createAggregateState, transition } from '../../src/state/engine.ts';
import { seedAdministration, withReason, type SeededActor } from '../identity/seed.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { ensureSealKey, run, signStub, testActor } from '../esig/helpers.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
  // The SIGNATURE hook, the sample record's content provider and its signed-table registration come
  // from kernel migration 0910.
});

afterAll(async () => {
  await db.drop();
});

async function grantRole(accountId: string, roleCode: string): Promise<void> {
  const { admin, owner } = await seedAdministration(db);
  const grant = await withCommand(db.app, withReason(admin), (c) => requestRoleGrant(c, { accountId, roleCode, reason: `needs ${roleCode}` }));
  await withCommand(db.app, withReason(owner), (c) => decideRoleGrant(c, grant, true, 'approved for test'));
}

async function newRecord(author: SeededActor): Promise<string> {
  return run(db, author, async (c) => {
    const { rows } = await c.query<{ id: string }>("insert into platform.stub_record (title, body) values ('Cleaning SOP', 'Version 1 text') returning id");
    const id = rows[0]?.id ?? '';
    await createAggregateState(c, 'sample_record', { aggregateType: 'sample_record', aggregateId: id });
    return id;
  });
}

const fire = async (actor: SeededActor, id: string, event: string, expectedVersion: number, signatureId?: string) =>
  run(db, actor, (c) =>
    transition(c, {
      machine: 'sample_record', aggregateType: 'sample_record', aggregateId: id, event, expectedVersion,
      ...(signatureId ? { payload: { signature_id: signatureId } } : {}),
    }),
  );

async function stateOf(id: string): Promise<{ state: string; version: string }> {
  const { rows } = await db.admin.query<{ state: string; version: string }>(
    "select state, version::text as version from platform.aggregate_state where aggregate_type = 'sample_record' and aggregate_id = $1",
    [id],
  );
  return rows[0] ?? { state: '?', version: '?' };
}

describe('F41 state engine accepts an out-of-order approval signature', () => {
  it('[INV-04][DI-35][DI-37] a checker cannot also approve by signing APPROVED before the check; the engine refuses a signature applied before the from-state', async () => {
    const author = await testActor(db, { roleCode: 'MBR_AUTHOR' });
    const p = await testActor(db, { roleCode: 'QA_MBR_APPROVER', legalName: 'Person P (checker and approver)' });
    await grantRole(p.accountId, 'MBR_CHECKER');
    const pApprover: SeededActor = { ...p, roleCode: 'QA_MBR_APPROVER', correlationId: randomUUID() };
    const pChecker: SeededActor = { ...p, roleCode: 'MBR_CHECKER', correlationId: randomUUID() };
    const qa = await testActor(db, { roleCode: 'QA_REVIEWER' });
    const approver = await testActor(db, { roleCode: 'QA_MBR_APPROVER' });

    // Positive control (a): normal order. P checks, then P's APPROVED signature is refused (INV-04).
    const r1 = await newRecord(author);
    await fire(author, r1, 'SUBMIT', 1);
    const c1 = await signStub(db, pChecker, r1, { meaning: 'CHECKED', aggregateType: 'sample_record', expectedState: 'SUBMITTED' });
    await fire(pChecker, r1, 'CHECK', 2, c1.signatureId);
    await expect(signStub(db, pApprover, r1, { meaning: 'APPROVED', aggregateType: 'sample_record', expectedState: 'CHECKED' })).rejects.toThrow(/EBMR-ESIG-043/);
    // Positive control (b): an independent approver signs in CHECKED and the flow reaches APPROVED.
    const a1 = await signStub(db, approver, r1, { meaning: 'APPROVED', aggregateType: 'sample_record', expectedState: 'CHECKED' });
    await fire(qa, r1, 'APPROVE', 3, a1.signatureId);
    expect((await stateOf(r1)).state).toBe('APPROVED');

    // The attack: reverse order on a fresh record R.
    const r = await newRecord(author);
    const steps: string[] = [];
    let refusal: string | null = null;
    let early: string | null = null;
    let check: string | null = null;
    try {
      // 2. P signs APPROVED while R is still DRAFT.
      early = (await signStub(db, pApprover, r, { meaning: 'APPROVED', aggregateType: 'sample_record', expectedState: 'DRAFT' })).signatureId;
      steps.push('P signed APPROVED in DRAFT');
      // 3. The author submits.
      await fire(author, r, 'SUBMIT', 1);
      steps.push('author SUBMIT');
      // 4. P signs CHECKED and fires CHECK.
      check = (await signStub(db, pChecker, r, { meaning: 'CHECKED', aggregateType: 'sample_record', expectedState: 'SUBMITTED' })).signatureId;
      steps.push('P signed CHECKED in SUBMITTED');
      await fire(pChecker, r, 'CHECK', 2, check);
      steps.push('P fired CHECK');
      // 5. A QA reviewer fires APPROVE with P's early APPROVED signature.
      await fire(qa, r, 'APPROVE', 3, early);
      steps.push('QA fired APPROVE with the early APPROVED signature');
    } catch (e) {
      refusal = (e as Error).message;
    }

    const final = await stateOf(r);
    const { rows: sigs } = await db.admin.query<{ id: string; meaning_code: string; signer_person: string; recorded_at: string }>(
      "select id, meaning_code, signer_person, recorded_at::text from esig.signature where aggregate_ref = 'sample_record:' || $1 order by recorded_at",
      [r],
    );
    const { rows: hist } = await db.admin.query<{ event: string; recorded_at: string; signature_id: string | null }>(
      "select event, recorded_at::text, signature_id::text from platform.state_history where aggregate_type = 'sample_record' and aggregate_id = $1 order by to_version",
      [r],
    );
    const evidence = JSON.stringify({ steps, refusal, final, signatures: sigs, history: hist, P: p.personId });

    // A refusal, if any, is a business refusal of the e-signature module or the state engine.
    if (refusal !== null) expect(refusal, evidence).toMatch(/EBMR-(ESIG|PLAT)-\d{3}/);
    // Safe behaviour: R never reaches APPROVED on a pre-check approval signature by the checker.
    expect(final.state, `INV-04 violated: the checker also approved, with a signature applied before the check. ${evidence}`).not.toBe('APPROVED');
  });
});

/**
 * Review reproducer F42: the trust level of occurred_at is whatever the caller says it is.
 *
 * platform.stub_step_entry (kernel 0530) grants the application INSERT on occurred_trust, and the
 * time-model trigger (platform.stub_step_entry_time_model) never checks the claimed trust against the
 * actor's source, the session's device or any instrument reading. platform.is_late_entry treats only
 * USER_CLAIMED and PAPER as late, and platform.time_basis drives time constraints from occurred_at
 * when the trust is DEVICE_SYNCED. So an ordinary person on a UI session, typing a time on a personal
 * terminal, can label it DEVICE_SYNCED and skip the late-entry path entirely.
 *
 * Scenario:
 *   1. A step started 3 h ago; its planned end (the kernel late-entry window) passed 30 min ago.
 *   2. Positive control: an operator (source UI, PERSONAL device, no instrument) back-dates a value
 *      by 170 min as USER_CLAIMED: refused without a reason (EBMR-PLAT-015), and with a reason but
 *      without a supervisor co-signature (EBMR-PLAT-016). So the late-entry rules are meant to apply.
 *   3. Attack: the same operator inserts the same value with the same typed time but labels it
 *      DEVICE_SYNCED.
 *
 * Safe behaviour asserted (DI-27: "client-device clocks and user-typed times are never used as the
 * time of an action"; DI-28/INV-16: a late entry goes only through the late-entry path with a reason,
 * review flag and, beyond the window, a supervisor co-signature): the person-typed DEVICE_SYNCED claim
 * is either refused with a business error, or, if accepted, it is not stored as trusted device time
 * (not DEVICE_SYNCED, time basis RECORDED_AT) and it is flagged as a late entry.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';
import { withTriggersDisabled } from '../platform/helpers.ts';

let db: TestDatabase;
beforeAll(async () => {
  db = await createTestDatabase();
});
afterAll(async () => {
  await db.drop();
});

interface EntryRow {
  id: string;
  recorded_at: string;
  occurred_at: string | null;
  occurred_trust: string | null;
  time_basis: string;
  time_basis_at: string;
  is_late: boolean;
  late_window_ends_at: string | null;
  late_reason_code: string | null;
  cosignature_id: string | null;
  review_flags: string[];
  entered_by: string;
}

const ENTRY_COLUMNS = `id, recorded_at::text, occurred_at::text, occurred_trust, time_basis, time_basis_at::text, is_late,
  late_window_ends_at::text, late_reason_code, cosignature_id::text, review_flags, entered_by`;

async function newStep(actor: ActorContext): Promise<string> {
  const stepId = await withCommand(db.app, actor, async (c) => {
    const { rows } = await c.query<{ id: string }>(
      `insert into platform.stub_step (batch_id, planned_end_at) values ($1, clock_timestamp() - interval '30 minutes') returning id`,
      [randomUUID()],
    );
    return rows[0]?.id ?? '';
  });
  // Test set-up only: the step started 3 hours ago (triggers off for this superuser transaction).
  await withTriggersDisabled(db, (c) => c.query("update platform.stub_step set started_at = started_at - interval '3 hours' where id = $1", [stepId]));
  return stepId;
}

async function addEntry(actor: ActorContext, stepId: string, trust: string, lateReason: string | null = null): Promise<EntryRow> {
  return withCommand(db.app, actor, async (c) => {
    const { rows } = await c.query<EntryRow>(
      `insert into platform.stub_step_entry (step_id, item_no, value, unit, occurred_at, occurred_trust, late_reason_code)
       values ($1, 1, 12.5, 'kg', clock_timestamp() - interval '170 minutes', $2, $3)
       returning ${ENTRY_COLUMNS}`,
      [stepId, trust, lateReason],
    );
    const row = rows[0];
    if (!row) throw new Error('no row');
    return row;
  });
}

describe('F42: trust of a claimed event time is asserted by the caller', () => {
  it('[DI-27][INV-16] a person-typed time labelled DEVICE_SYNCED from a UI session does not skip the late-entry controls', async () => {
    const operator = await seededTestActor(db); // ordinary person, source UI, PERSONAL device
    expect(operator.source).toBe('UI');
    const { rows: dev } = await db.admin.query<{ device_class: string }>('select device_class from iam.device where id = $1', [operator.deviceId]);
    expect(dev[0]?.device_class).toBe('PERSONAL');

    const stepId = await newStep(operator);

    // Positive control: the same back-dated time, honestly labelled as typed by a person.
    await expect(addEntry(operator, stepId, 'USER_CLAIMED')).rejects.toThrow('EBMR-PLAT-015');
    await expect(addEntry(operator, stepId, 'USER_CLAIMED', 'FORGOT_TO_RECORD')).rejects.toThrow('EBMR-PLAT-016');

    // Attack: the same typed time, labelled as a synchronised instrument clock.
    const outcome = await addEntry(operator, stepId, 'DEVICE_SYNCED').then(
      (row) => ({ row, error: undefined as Error | undefined }),
      (error: Error) => ({ row: undefined as EntryRow | undefined, error }),
    );

    if (outcome.error) {
      // Refused: must be a business refusal of the time model, not a set-up mistake.
      expect(outcome.error.message).toMatch(/EBMR-/);
      expect(outcome.error.message).not.toMatch(/EBMR-PLAT-018|EBMR-PLAT-014|EBMR-PLAT-013|EBMR-PLAT-012/);
      return;
    }

    // Accepted: the typed time must not be trusted as device time, and the late-entry path must apply.
    const row = outcome.row as EntryRow;
    const summary = JSON.stringify({
      occurred_trust: row.occurred_trust,
      time_basis: row.time_basis,
      is_late: row.is_late,
      review_flags: row.review_flags,
      late_reason_code: row.late_reason_code,
      cosignature_id: row.cosignature_id,
    });
    expect(row.occurred_trust, `accepted as ${summary}`).not.toBe('DEVICE_SYNCED');
    expect(row.time_basis, `accepted as ${summary}`).toBe('RECORDED_AT');
    expect(row.is_late, `accepted as ${summary}`).toBe(true);
    expect(row.review_flags, `accepted as ${summary}`).toEqual(expect.arrayContaining(['LATE_ENTRY', 'LATE_BEYOND_WINDOW']));
  });
});

/**
 * Review reproducer F43: time-fault review windows are bounded by the faulty clock.
 *
 * platform.time_fault_windows (kernel 0520) takes window_start = alarm.window_start (the recorded_at
 * of the node's last within-threshold drift sample, platform.time_window_start) and window_end = the
 * clearance's recorded_at; platform.entries_in_time_fault_windows then selects audit events by
 * kernel.audit_event.recorded_at between the two. All three times come from the same database clock
 * whose fault is under review. When the fault appears or is corrected by a clock STEP, the entries
 * recorded across the step carry times outside [window_start, window_end] and drop out of the DI-27
 * review list.
 *
 * The test database cannot move the server clock, so the step is simulated the way the finding's
 * suggested test does it: the real product path records everything (drift checks through
 * platform.record_drift_check as the time monitor, entries through platform.stub_step_entry as an
 * operator), and a superuser set-up (triggers disabled for that transaction only) then rewrites the
 * recorded_at values that the stepped node clock would have produced for the rows written while the
 * clock was wrong: kernel.audit_event, platform.drift_sample and platform.alarm. Rows recorded before
 * the step (the last good sample) and after the correction (the clearance) keep true times.
 *
 * Scenario A (backward step, finding steps 1-6):
 *   1. A healthy check on node db-step-back (last good sample L).
 *   2. The node clock steps back 1 h.
 *   3. An operator records entry E1 (audit recorded_at ~ L - 1 h).
 *   4. The next check sees offset -3600 s and raises DRIFT_EXCEEDED (window_start = L).
 *   5. The operator records entry E2 during the alarm.
 *   6. The clock is corrected and a healthy check clears the alarm.
 * Scenario B (forward case): node db-step-fwd jumps 30 s ahead after a healthy check; the check sees
 * +30 s and raises DRIFT_EXCEEDED; entry E3 is recorded; NTP steps the clock back and the clearing
 * check runs at once, so window_end is earlier than E3's recorded_at.
 *
 * Positive control: before the step is applied (true times) the same entries are listed for the
 * open alarm, so the set-up is right and only the clock-stamped times make them disappear.
 *
 * Safe behaviour asserted (DI-27: entries made in a time-fault window are flagged for review;
 * INV-16): every entry recorded between the last good sample and the clearance of a time-fault
 * alarm is listed by platform.entries_in_time_fault_windows() for that alarm, whatever the faulty
 * clock stamped on it: E1 and E2 for the backward alarm, E3 for the forward alarm.
 */
import { randomUUID } from 'node:crypto';
import type pg from 'pg';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
