describe('F43 time-fault review windows across a clock step', () => {
  it('[DI-27][INV-16] entries recorded across a backward or forward clock step are listed for review with their alarm', async () => {
    // ---- Scenario A: backward step of 1 h ----------------------------------------------------
    const nodeA = 'db-step-back';
    const batchA = randomUUID();
    expect((await drift(nodeA, '0.000020', '-0.000030')).raised).toEqual([]); // last good sample L
    const stepA = await dbClock(); // the node clock steps back 1 h here
    const e1 = await newEntry(batchA); // after the step, before the alarm
    const faultA = await drift(nodeA, '-3600.000020', '-3600.000030');
    expect(faultA.raised.map((a) => a.kind)).toEqual(['DRIFT_EXCEEDED']);
    const alarmA = faultA.raised[0]?.alarm_id ?? '';
    const e2 = await newEntry(batchA); // during the alarm
    // Positive control: with true times (no step) both entries are in the open window's list, so
    // the alarm, the window and the entry filter are set up right; only the stepped times differ.
    expect(await listedFor(alarmA, batchA)).toEqual([e1.id, e2.id].sort());
    await applyClockStep(stepA, '-1 hour');
    // The clock is corrected; the next healthy check clears the alarm.
    expect((await drift(nodeA, '0.000020', '-0.000030')).cleared).toEqual([{ kind: 'DRIFT_EXCEEDED', alarm_id: alarmA }]);

    // ---- Scenario B: forward jump of 30 s, corrected by an NTP step ---------------------------
    const nodeB = 'db-step-fwd';
    const batchB = randomUUID();
    expect((await drift(nodeB, '0.000020', '-0.000030')).raised).toEqual([]); // last good sample
    const stepB = await dbClock(); // the node clock jumps 30 s ahead here
    const faultB = await drift(nodeB, '30.000020', '30.000030');
    expect(faultB.raised.map((a) => a.kind)).toEqual(['DRIFT_EXCEEDED']);
    const alarmB = faultB.raised[0]?.alarm_id ?? '';
    const e3 = await newEntry(batchB); // during the alarm, recorded with the node 30 s ahead
    expect(await listedFor(alarmB, batchB)).toEqual([e3.id]); // positive control, true times
    await applyClockStep(stepB, '30 seconds');
    // NTP steps the clock back; the clearing check runs at once.
    expect((await drift(nodeB, '0.000020', '-0.000030')).cleared).toEqual([{ kind: 'DRIFT_EXCEEDED', alarm_id: alarmB }]);

    const diagnostics = {
      backward: { window: await windowOf(alarmA), entries: await auditTimes(batchA), e1Flags: e1.review_flags, e2Flags: e2.review_flags },
      forward: { window: await windowOf(alarmB), entries: await auditTimes(batchB), e3Flags: e3.review_flags },
    };

    // Safe behaviour: the DI-27 review list for each alarm holds every entry recorded while the
    // node's time was in doubt (between the last good sample and the clearance).
    const listed = { backward: await listedFor(alarmA, batchA), forward: await listedFor(alarmB, batchB) };
    expect(listed, `DI-27 review list per alarm; windows and entry times: ${JSON.stringify(diagnostics)}`).toEqual({
      backward: [e1.id, e2.id].sort(),
      forward: [e3.id],
    });
  });
});

/**
 * Review reproducer F44: the sample record's edit guard (platform.stub_record_edit_guard, kernel
 * 0551) allows an UPDATE when a plain, unlocked SELECT of platform.aggregate_state shows DRAFT, and
 * the SUBMIT guard (platform.guard_sample_record_has_body, 0551, run by platform.transition, 0550)
 * reads platform.stub_record with a plain MVCC read. platform.transition locks only the
 * aggregate_state row (FOR UPDATE); the edit never touches that row. Neither side takes a lock the
 * other conflicts with before it evaluates its guard (write skew), although outline 5.2 requires
 * guards to run with the relevant rows locked.
 *
 * The two commands need two different sessions: kernel.begin_command locks the actor's iam.session
 * row (0190), so two commands of the SAME session are serialised whole. Two authors (or one person
 * on two workstations) are the realistic case, so the test uses two MBR_AUTHOR actors.
 *
 * Scenario 1 (has_body guard bypass, the finding's order):
 *   A: begin; begin_command(author A, reason); update stub_record set body = '' where id = R
 *      -> the edit guard sees DRAFT and passes; A stays open.
 *   B: begin; begin_command(author B); platform.transition(... R, 'SUBMIT', 1)
 *      -> has_body reads the committed (non-empty) body and passes. (B may then wait on the audit
 *         chain head of sample_record:R that A holds, but only after the guard has passed.)
 *   A: commit. B: completes, commit.
 *   Unsafe result: R is SUBMITTED with an empty body; EBMR-PLAT-068 never fired.
 *
 * Scenario 2 (content change after submission, reverse order):
 *   B: begin; begin_command(author B); platform.transition(... R2, 'SUBMIT', 1) -> done, B open.
 *   A: begin; begin_command(author A, reason); update stub_record set body = 'changed' where id = R2
 *      -> the edit guard reads the committed state DRAFT and passes.
 *   B: commit. A: completes, commit.
 *   Unsafe result: R2 is SUBMITTED and its body is not the body that was submitted; EBMR-PLAT-074
 *   never fired.
 *
 * Safe behaviour asserted (ADR-0012, INV-04, outline 5.2): in both races the guard that must
 * refuse does refuse (the loser waits for the winner's lock and then sees the committed data), so a
 * SUBMITTED record never has an empty body, and a SUBMITTED record's content is exactly what was
 * submitted. Any refusal must be a business refusal (EBMR-PLAT-068 / EBMR-PLAT-074), not a setup
 * mistake.
 *
 * Positive controls: sequentially, SUBMIT of an empty body is refused with EBMR-PLAT-068 and an edit
 * after SUBMIT is refused with EBMR-PLAT-074, so the guards and the actors are set up correctly and
 * only the interleaving changes the outcome.
 */
import { randomUUID } from 'node:crypto';
import type pg from 'pg';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { toDbContext, withCommand, type ActorContext } from '../../src/db/command.ts';
import { createAggregateState, transition } from '../../src/state/engine.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';

let db: TestDatabase;
let authorA: ActorContext;
let authorB: ActorContext;

beforeAll(async () => {
  db = await createTestDatabase();
  // Real AUTHORITY hook (identity module): MBR_AUTHOR holds SAMPLE_RECORD.SUBMIT (kernel 0700).
  authorA = await seededTestActor(db, { roleCode: 'MBR_AUTHOR', legalName: 'A. Editor' });
  authorB = await seededTestActor(db, { roleCode: 'MBR_AUTHOR', legalName: 'B. Submitter' });
});

afterAll(async () => {
  await db.drop();
});

const editCtx = (): ActorContext => ({ ...authorA, reasonCode: 'REWORK', reasonText: 'edit of the draft', correlationId: randomUUID() });
const submitCtx = (): ActorContext => ({ ...authorB, correlationId: randomUUID() });

async function newRecord(body: string): Promise<string> {
  return withCommand(db.app, submitCtx(), async (c) => {
    const { rows } = await c.query<{ id: string }>('insert into platform.stub_record (title, body) values ($1, $2) returning id', ['Sample SOP', body]);
    const id = rows[0]?.id ?? '';
    await createAggregateState(c, 'sample_record', { aggregateType: 'sample_record', aggregateId: id });
    return id;
  });
}

async function snapshot(id: string): Promise<{ state: string; version: string; body: string }> {
  const { rows } = await db.admin.query<{ state: string; version: string; body: string }>(
    `select s.state, s.version::text as version, r.body
       from platform.stub_record r join platform.aggregate_state s on s.aggregate_type = 'sample_record' and s.aggregate_id = r.id
      where r.id = $1`,
    [id],
  );
  return rows[0] ?? { state: '?', version: '?', body: '?' };
}

/** Opens a command (begin + kernel.begin_command) on its own connection and leaves it open. */
async function openCommand(ctx: ActorContext): Promise<{ client: pg.PoolClient; pid: number }> {
  const client = await db.app.connect();
  await client.query('begin');
  await client.query('select kernel.begin_command($1::jsonb)', [JSON.stringify(toDbContext(ctx))]);
  const { rows } = await client.query<{ pid: number }>('select pg_backend_pid() as pid');
  return { client, pid: rows[0]?.pid ?? -1 };
}

async function close(client: pg.PoolClient, commit: boolean): Promise<string | null> {
  try {
    await client.query(commit ? 'commit' : 'rollback');
    return null;
  } catch (e) {
    await client.query('rollback').catch(() => undefined);
    return (e as Error).message;
  } finally {
    client.release();
  }
}

type Outcome = { ok: true } | { ok: false; error: string };
const settle = (p: Promise<unknown>): Promise<Outcome> =>
  p.then(
    () => ({ ok: true }) as const,
    (e: unknown) => ({ ok: false, error: (e as Error).message }) as const,
  );

/** Waits until the statement on `pid` is waiting for a lock, or until it has finished. */
async function blockedOrDone(pid: number, pending: Promise<Outcome>): Promise<{ status: string; waitingOn: string | null }> {
  let done = false;
  void pending.then(() => {
    done = true;
  });
  for (let i = 0; i < 200 && !done; i++) {
    const { rows } = await db.admin.query<{ wait_event_type: string | null; query: string }>(
      'select wait_event_type, query from pg_stat_activity where pid = $1',
      [pid],
    );
    if (rows[0]?.wait_event_type === 'Lock') {
      const { rows: locks } = await db.admin.query<{ what: string }>(
        `select string_agg(l.locktype || coalesce(':' || l.relation::regclass::text, '') || ':' || l.mode, ', ') as what
           from pg_locks l where l.pid = $1 and not l.granted`,
        [pid],
      );
      return { status: 'blocked', waitingOn: locks[0]?.what ?? null };
    }
    await new Promise((r) => setTimeout(r, 25));
  }
  return { status: done ? 'done' : 'timeout', waitingOn: null };
}

describe('F44 the edit guard and the SUBMIT guard of the sample record run without locking each other', () => {
  it('[INV-04] concurrent edit and SUBMIT: a SUBMITTED record never has an empty body and never changes after submission', async () => {
    // Positive controls (sequential): both guards work and the actors can edit and submit.
    const empty = await newRecord('   ');
    await expect(
      withCommand(db.app, submitCtx(), (c) => transition(c, { machine: 'sample_record', aggregateType: 'sample_record', aggregateId: empty, event: 'SUBMIT', expectedVersion: 1 })),
    ).rejects.toThrow('EBMR-PLAT-068 SUBMIT refused in state DRAFT: sample_record.has_body: the record body is empty');
    const seq = await newRecord('Version 1 text');
    await withCommand(db.app, editCtx(), (c) => c.query("update platform.stub_record set body = 'Version 1 text, edited' where id = $1", [seq]));
    await withCommand(db.app, submitCtx(), (c) => transition(c, { machine: 'sample_record', aggregateType: 'sample_record', aggregateId: seq, event: 'SUBMIT', expectedVersion: 1 }));
    await expect(
      withCommand(db.app, editCtx(), (c) => c.query("update platform.stub_record set body = 'changed after submit' where id = $1", [seq])),
    ).rejects.toThrow('EBMR-PLAT-074');
    expect(await snapshot(seq)).toEqual({ state: 'SUBMITTED', version: '2', body: 'Version 1 text, edited' });

    // ---- Scenario 1: A empties the body (open), B submits, A commits, B commits. ----
    const r1 = await newRecord('Version 1 text');
    const s1: Record<string, unknown> = {};
    {
      const a = await openCommand(editCtx());
      const b = await openCommand(submitCtx());
      try {
        s1['editA'] = await settle(a.client.query("update platform.stub_record set body = '' where id = $1", [r1]));
        const submit = settle(b.client.query("select platform.transition('sample_record', 'sample_record', $1, 'SUBMIT', 1, '{}'::jsonb)", [r1]));
        s1['submitB_before_commitA'] = await blockedOrDone(b.pid, submit);
        s1['commitA'] = await close(a.client, (s1['editA'] as Outcome).ok);
        s1['submitB'] = await submit;
        s1['commitB'] = await close(b.client, (s1['submitB'] as Outcome).ok);
      } catch (e) {
        s1['unexpected'] = (e as Error).message;
        await close(a.client, false).catch(() => undefined);
        await close(b.client, false).catch(() => undefined);
      }
    }
    s1['final'] = await snapshot(r1);

    // ---- Scenario 2: B submits (open), A edits, B commits, A commits. ----
    const r2 = await newRecord('Version 1 text');
    const s2: Record<string, unknown> = {};
    {
      const b = await openCommand(submitCtx());
      const a = await openCommand(editCtx());
      try {
        s2['submitB'] = await settle(b.client.query("select platform.transition('sample_record', 'sample_record', $1, 'SUBMIT', 1, '{}'::jsonb)", [r2]));
        const edit = settle(a.client.query("update platform.stub_record set body = 'changed after submission' where id = $1", [r2]));
        s2['editA_before_commitB'] = await blockedOrDone(a.pid, edit);
        s2['commitB'] = await close(b.client, (s2['submitB'] as Outcome).ok);
        s2['editA'] = await edit;
        s2['commitA'] = await close(a.client, (s2['editA'] as Outcome).ok);
      } catch (e) {
        s2['unexpected'] = (e as Error).message;
        await close(b.client, false).catch(() => undefined);
        await close(a.client, false).catch(() => undefined);
      }
    }
    s2['final'] = await snapshot(r2);

    const evidence = JSON.stringify({ scenario1: s1, scenario2: s2 });
    expect(s1['unexpected'], evidence).toBeUndefined();
    expect(s2['unexpected'], evidence).toBeUndefined();
    // Any refusal is the business refusal of the guard that must fire, not a setup mistake.
    for (const o of [s1['editA'], s1['submitB'], s2['submitB'], s2['editA']] as Outcome[]) {
      if (!o.ok) expect(o.error, evidence).toMatch(/EBMR-PLAT-06[68]|EBMR-PLAT-074/);
    }

    const f1 = s1['final'] as { state: string; body: string };
    const f2 = s2['final'] as { state: string; body: string };
    const violations: string[] = [];
    if (f1.state === 'SUBMITTED' && f1.body.trim() === '') {
      violations.push('scenario 1: record SUBMITTED with an empty body (sample_record.has_body bypassed, EBMR-PLAT-068 never fired)');
    }
    if (f2.state === 'SUBMITTED' && f2.body !== 'Version 1 text') {
      violations.push(`scenario 2: record SUBMITTED but its content changed after submission to "${f2.body}" (EBMR-PLAT-074 never fired)`);
    }
    expect(violations, evidence).toEqual([]);
  });
});

/**
 * Review reproducer F45: platform.create_aggregate_state (kernel 0550, line 398; the only definition,
 * never replaced later) is granted to ebmr_app and checks only platform.require_actor() (a validated
 * actor exists). It never calls iam.assert_not_administrator(), so a SYSTEM_ADMINISTRATOR command
 * creates GMP state: an aggregate_state row, a state_history row attributed to the administrator, a
 * BUSINESS audit entry on the GMP aggregate's chain and a 'state.created' outbox message.
 *
 * DI-18 (behaviour: "Administrators cannot change GMP data values"; catalog_test: "An administrator
 * tries to edit a GMP value through the UI or API. Refused and logged.") and the iam guard itself
 * (0130: "an administrator role ... never creates or changes GMP data, whatever else it holds.
 * Modules call it in their GMP write functions") require the refusal EBMR-IAM-042.
 *
 * Steps (all as ebmr_app, through kernel.begin_command, exactly as the product would):
 *   1. Positive control: the seeded installation administrator (role SYSTEM_ADMINISTRATOR) is refused
 *      by iam.assert_not_administrator() with EBMR-IAM-042, so the actor really is an administrator
 *      in the DI-18 sense and its command context is valid.
 *   2. Positive control: an MBR_AUTHOR creates a sample_record state through the same call, so the
 *      call itself is well-formed and succeeds for a GMP role.
 *   3. The administrator runs
 *        select platform.create_aggregate_state('sample_record', 'sample_record', <new uuid>)
 *      Safe behaviour asserted: refused with EBMR-IAM-042, and no state row, history row or audit
 *      entry exists for that aggregate afterwards.
 *
 * With the defect, step 3 resolves (state DRAFT, version 1) instead of rejecting, and a
 * state_history row with role_code SYSTEM_ADMINISTRATOR exists.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';
import { seedAdministration, withReason } from '../identity/seed.ts';

let db: TestDatabase;
let admin: ActorContext;
let author: ActorContext;

beforeAll(async () => {
  db = await createTestDatabase();
  const { admin: seededAdmin } = await seedAdministration(db);
  const { seed: _seed, ...adminCtx } = seededAdmin;
  void _seed;
  admin = adminCtx;
  author = await seededTestActor(db, { roleCode: 'MBR_AUTHOR', legalName: 'A. Author' });
});

afterAll(async () => {
  await db.drop();
});

const createState = (actor: ActorContext, id: string) =>
  withCommand(db.app, actor, async (c) => {
    const { rows } = await c.query<{ r: { state: string; version: number; machine_version: number } }>(
      "select platform.create_aggregate_state('sample_record', 'sample_record', $1::uuid) as r",
      [id],
    );
    return rows[0]?.r;
  });

describe('F45: platform.create_aggregate_state and DI-18', () => {
  it('an administrator cannot create GMP aggregate state (state row, history, audit entry) through create_aggregate_state', async () => {
    // 1. Positive control: the actor is an administrator in the DI-18 sense and its context is valid.
    expect(admin.roleCode).toBe('SYSTEM_ADMINISTRATOR');
    await expect(withCommand(db.app, withReason(admin), (c) => c.query('select iam.assert_not_administrator()'))).rejects.toThrow('EBMR-IAM-042');

    // 2. Positive control: a GMP role can create a sample_record state with the same call.
    const authored = randomUUID();
    await expect(createState(author, authored)).resolves.toMatchObject({ state: 'DRAFT', version: 1 });

    // 3. The administrator attempts the same GMP write. DI-18 requires a refusal.
    const id = randomUUID();
    let outcome: string;
    try {
      const r = await createState(withReason(admin), id);
      outcome = `created: ${JSON.stringify(r)}`;
    } catch (error) {
      outcome = `refused: ${(error as Error).message}`;
    }

    const { rows: history } = await db.admin.query<{ role_code: string; to_state: string; person_id: string }>(
      "select role_code, to_state, person_id from platform.state_history where aggregate_type = 'sample_record' and aggregate_id = $1",
      [id],
    );
    const { rows: audit } = await db.admin.query<{ n: string }>('select count(*)::text as n from kernel.audit_event where chain_key = $1', [
      `sample_record:${id}`,
    ]);
    const { rows: state } = await db.admin.query<{ n: string }>(
      "select count(*)::text as n from platform.aggregate_state where aggregate_type = 'sample_record' and aggregate_id = $1",
      [id],
    );

    expect({ outcome, history, auditEntries: audit[0]?.n, stateRows: state[0]?.n }).toEqual({
      outcome: expect.stringMatching(/^refused: .*EBMR-IAM-042/),
      history: [],
      auditEntries: '0',
      stateRows: '0',
    });
  });
});

/**
 * Review reproducer F46: platform.stub_step_entry_time_model (kernel 0530, line 273; the only
 * definition, never replaced later) sets
 *     new.site_zone := v_ctx ->> 'site_zone'
 * and derives site_utc_offset from it, after checking only that the name is a valid IANA zone.
 * kernel.validate_actor_context (0010 shape check, replaced in 0190) only requires that site_zone is
 * present; it never compares it with the site's configured zone iam.policy_text('site.zone')
 * (0100, default 'Asia/Kolkata'). esig.sign does compare them (0230, EBMR-ESIG-035); the time model
 * does not. So the zone stored with a GMP entry - which fixes the stored UTC offset, the displayed
 * local time and the site-local calendar day - is chosen by the caller.
 *
 * DI-27 (behaviour: "Timestamps are stored in UTC with the site time zone and offset, and displayed
 * as site-local time with the offset"; "Client-device clocks and user-typed times are never used as
 * the time of an action") requires the stored zone to be the site's zone, not a client-declared one.
 *
 * Steps (all as ebmr_app, through kernel.begin_command, exactly as the product would):
 *   1. Positive control: the site's configured zone iam.policy_text('site.zone') is Asia/Kolkata.
 *   2. Positive control: an operator whose context declares Asia/Kolkata records an entry; it stores
 *      Asia/Kolkata with offset +05:30.
 *   3. An operator (same seeded identity kind, same site) whose command context declares
 *      site_zone 'America/Los_Angeles' records an entry on the same step.
 *      Safe behaviour asserted: either the command is refused, or the stored entry carries the site
 *      zone (Asia/Kolkata) and its offset (+05:30), so the site-local calendar day computed from the
 *      stored zone is the site's own day.
 *
 * With the defect, step 3 stores site_zone America/Los_Angeles with offset -07:00 (PDT), and
 * platform.site_calendar_day(recorded_at, site_zone) is the Los Angeles day, not the site's day.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';
import { SEED_ZONE } from '../identity/seed.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
});

afterAll(async () => {
  await db.drop();
});

interface EntryRow {
  site_zone: string;
  site_utc_offset: string;
  recorded_at: string;
  stored_day: string;
  site_day: string;
}

async function newStep(): Promise<string> {
  return withCommand(db.app, await seededTestActor(db), async (c) => {
    const { rows } = await c.query<{ id: string }>(
      "insert into platform.stub_step (batch_id, planned_end_at) values ($1, clock_timestamp() + interval '8 hours') returning id",
      [randomUUID()],
    );
    return rows[0]?.id ?? '';
  });
}

async function addEntry(stepId: string, itemNo: number, ctx: ActorContext): Promise<EntryRow> {
  return withCommand(db.app, ctx, async (c) => {
    const { rows } = await c.query<EntryRow>(
      `with e as (
         insert into platform.stub_step_entry (step_id, item_no, value, unit) values ($1, $2, '12.503', 'kg')
         returning site_zone, site_utc_offset, recorded_at)
       select e.site_zone, e.site_utc_offset::text, e.recorded_at::text,
              platform.site_calendar_day(e.recorded_at, e.site_zone)::text as stored_day,
              platform.site_calendar_day(e.recorded_at, iam.policy_text('site.zone'))::text as site_day
         from e`,
      [stepId, itemNo],
    );
    const row = rows[0];
    if (!row) throw new Error('no row');
    return row;
  });
}

describe('F46: the site zone stored with a GMP entry (DI-27)', () => {
  it('an entry does not store a caller-declared foreign zone and offset: it is refused or stored with the site zone', async () => {
    // 1. Positive control: the site's configured zone.
    const { rows: policy } = await db.app.query<{ z: string }>("select iam.policy_text('site.zone') as z");
    expect(policy[0]?.z).toBe('Asia/Kolkata');
    expect(SEED_ZONE).toBe('Asia/Kolkata');

    const stepId = await newStep();

    // 2. Positive control: the site zone is stored with its offset.
    const local = await addEntry(stepId, 1, await seededTestActor(db, { siteZone: 'Asia/Kolkata' }));
    expect(local.site_zone).toBe('Asia/Kolkata');
    expect(local.site_utc_offset).toBe('05:30:00');
    expect(local.stored_day).toBe(local.site_day);

    // 3. Same site, a command context that declares a foreign zone.
    const foreign = { ...(await seededTestActor(db)), siteZone: 'America/Los_Angeles' };
    let outcome: string;
    let stored: EntryRow | undefined;
    try {
      stored = await addEntry(stepId, 2, foreign);
      outcome = 'stored';
    } catch (error) {
      outcome = `refused: ${(error as Error).message}`;
    }

    if (outcome === 'stored') {
      // Accepted: then the stored zone, offset and site-local day must be the site's own.
      expect({ site_zone: stored?.site_zone, site_utc_offset: stored?.site_utc_offset, day_matches_site: stored?.stored_day === stored?.site_day }).toEqual({
        site_zone: 'Asia/Kolkata',
        site_utc_offset: '05:30:00',
        day_matches_site: true,
      });
    } else {
      expect(outcome).toMatch(/^refused: .*EBMR-/);
    }
  });
});

/**
 * Review reproducer F47: the drift decision ignores measurement uncertainty.
 *
 * platform.record_drift_check (kernel 0520) marks a sample within_threshold when
 * abs(offset_s) <= threshold_s; uncertainty_s is stored but never used. The monitor
 * (src/time/drift-monitor.ts measureReference) estimates the offset as the midpoint of two node-clock
 * reads around the reference read, with half the bracket as uncertainty, and the default read timeout
 * is 5 s against a default 1 s threshold. A slow reference read therefore produces a sample whose
 * uncertainty exceeds the threshold (it proves nothing about the offset), yet it counts as healthy:
 * it clears DRIFT_EXCEEDED (ends the fault window) and becomes the node's "last good sample".
 *
 * Scenario (finding's failure scenario, driven through the real monitor path runDriftCheck):
 *   1. Healthy check on node db-uncertain (last good sample).
 *   2. The node clock is truly 1.8 s ahead of both references: the next check raises DRIFT_EXCEEDED.
 *   3. The node is STILL 1.8 s ahead, but both reference reads are slow (~3 s round trip) and each
 *      reference returns its time at the end of the bracket (as a server answering at resolution
 *      does). The monitor measures offset ~0.3 s with uncertainty ~1.5 s for both sources.
 *   4. An operator records an entry after that check.
 *
 * Positive control: the readings of step 3 really are |offset| < threshold and uncertainty > threshold,
 * so the scenario is the one described (and the true offset of 1.8 s is inside offset +/- uncertainty).
 *
 * Safe behaviour asserted (DI-27, outline 5.6 "Drift and monotonicity"): a sample whose uncertainty
 * exceeds the threshold is not evidence that the clock is within tolerance, so
 *   - it is not stored as within_threshold (so it cannot become the last good sample),
 *   - it does not clear the open DRIFT_EXCEEDED alarm (the fault window stays open),
 *   - an entry recorded afterwards, while the clock is still 1.8 s off, is flagged TIME_FAULT_WINDOW
 *     and is listed for review with the DRIFT_EXCEEDED alarm.
 */
import { randomUUID } from 'node:crypto';
import type pg from 'pg';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { nodeClock, runDriftCheck, type TimeReference } from '../../src/time/drift-monitor.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { grantPermission, installStubHooks, testActor } from '../platform/helpers.ts';

let db: TestDatabase;
let system: ActorContext;
let operator: ActorContext;
let npl = '';
let nic = '';

const TRUE_SKEW_MICROS = 1_800_000n; // the node is truly 1.8 s ahead of the references
const SLOW_READ_MS = 3000; // round trip of a slow reference read (below the default 5 s timeout)

async function rows<T extends pg.QueryResultRow>(text: string, params: unknown[] = []): Promise<T[]> {
  return (await db.app.query<T>(text, params)).rows;
}

async function registerSource(name: string, reference: string): Promise<string> {
  const admin = await testActor(db, { roleCode: 'CSV_DI_LEAD' });
  return withCommand(db.app, admin, async (c) => {
    const { rows: r } = await c.query<{ id: string }>(
      "select platform.register_time_source($1, 'NTP', $2, $3, $4, 'VAL-TS-2026-001') as id",
      [name, `${name.toLowerCase().replace(/\W+/g, '-')}.example`, reference, randomUUID()],
    );
    return r[0]?.id ?? '';
  });
}

/** A reference whose clock is `skewMicros` behind the node, answering at once. */
function reference(sourceId: string, skewMicros: bigint): TimeReference {
  return { sourceId, read: async () => (await nodeClock(db.app)).plusMicros(-skewMicros) };
}

/**
 * A reference whose clock is `skewMicros` behind the node, whose answer arrives after `delayMs` and
 * whose timestamp is taken at the end of the round trip (true reference time at that moment).
 */
function slowReference(sourceId: string, skewMicros: bigint, delayMs: number): TimeReference {
  return {
    sourceId,
    read: async () => {
      await new Promise((resolve) => setTimeout(resolve, delayMs));
      return (await nodeClock(db.app)).plusMicros(-skewMicros);
    },
  };
}

async function check(node: string, references: TimeReference[]) {
  // Default monitor timeout (5000 ms), as in production wiring.
  return runDriftCheck(db.app, { node, actor: system, references });
}

async function openAlarms(node: string) {
  return rows<{ id: string; kind: string }>(
    `select a.id, a.kind from platform.alarm a
      where a.subject = $1 and not exists (select 1 from platform.alarm_clearance c where c.alarm_id = a.id) order by a.recorded_at`,
    [node],
  );
}

async function newEntry(batchId: string): Promise<{ id: string; review_flags: string[] }> {
  return withCommand(db.app, operator, async (c) => {
    const step = await c.query<{ id: string }>('insert into platform.stub_step (batch_id) values ($1) returning id', [batchId]);
    const { rows: r } = await c.query<{ id: string; review_flags: string[] }>(
      "insert into platform.stub_step_entry (step_id, item_no, value, unit) values ($1, 1, '12.503', 'kg') returning id, review_flags",
      [step.rows[0]?.id],
    );
    return r[0] as { id: string; review_flags: string[] };
  });
}

