describe('F49 validated time sources', () => {
  it('[DI-27][DI-18] a time source whose validated_by names no person, signature or validation record is refused', async () => {
    // Control: the system administrator holds platform.time_source.manage (the gate passes and the
    // function reaches its own lookup), so a refusal below is not a permission refusal.
    const unknown = await attempt(() => setActive(admin, randomUUID(), false));
    expect(unknown.ok ? 'accepted' : unknown.error).toMatch(/EBMR-PLAT-030/);
    // Control: a role without the permission is refused.
    const operator = await seedActor(db, { roleCode: 'OPERATOR', acknowledgeEsig: false });
    const op = await attempt(() => register(operator, `Op ${randomBytes(3).toString('hex')}`, '10.0.0.8', 'anything', null, 'n/a'));
    expect(op.ok ? 'accepted' : op.error).toMatch(/EBMR-PLAT-006/);

    const validator = randomUUID();
    const name = `Local ${randomBytes(3).toString('hex')}`;
    const outcome = await attempt(() => register(admin, name, '10.0.0.9', 'anything', validator, 'n/a'));
    // The claimed validator is nobody: no person, no e-signature.
    const [evidence] = await adminRows<{ person: boolean; signature: boolean }>(
      'select exists (select 1 from iam.person where id = $1) as person, exists (select 1 from esig.signature where id = $1) as signature',
      [validator],
    );
    expect(evidence).toEqual({ person: false, signature: false });
    const stored = await adminRows<{ id: string; validated_by: string; validation_ref: string; active: boolean }>(
      'select id::text, validated_by::text, validation_ref, active from platform.time_source where name = $1',
      [name],
    );
    if (stored.length > 0) {
      // Test clean-up only (superuser, triggers off): keep the next test to the finding's exact scenario.
      const client = await db.admin.connect();
      try {
        await client.query('begin');
        await client.query('set local session_replication_role = replica');
        await client.query('update platform.time_source set active = false where name = $1', [name]);
        await client.query('commit');
      } finally {
        client.release();
      }
    }
    expect(
      outcome.ok
        ? `registered as ${JSON.stringify(stored)} by one SYSTEM_ADMINISTRATOR with validated_by ${validator} (no person, no signature) and validation_ref 'n/a'`
        : 'refused',
    ).toBe('refused');
    expect(stored).toEqual([]);
  });

  it('[DI-27][DI-24] one administrator alone cannot swap the references so that a node 30 s off raises no time-fault incident', async () => {
    // Positive control: with the traceable references active, a 30 s offset raises DRIFT_EXCEEDED with an incident.
    const control = await monitorCheck('db-f49-control', '30.000000');
    expect(control.raised.map((a) => a.kind)).toEqual(['DRIFT_EXCEEDED']);
    expect(await incidentAlarms('db-f49-control')).toEqual([{ kind: 'DRIFT_EXCEEDED', severity: 'MAJOR' }]);

    // The attack of the finding, by one SYSTEM_ADMINISTRATOR with a reason on each change.
    const rogueName = `Local ${randomBytes(3).toString('hex')}`;
    const steps = {
      registerUnvalidated: await attempt(() => register(admin, rogueName, '10.0.0.9', 'anything', null, 'n/a')),
      deactivateNpl: await attempt(() => setActive(admin, npl, false)),
      deactivateNic: await attempt(() => setActive(admin, nic, false)),
    };
    const accepted = Object.entries(steps)
      .filter(([, r]) => r.ok)
      .map(([k]) => k);
    const active = (await activeSources()).map((s) => s.name);

    // The database node's clock is now 30 s ahead of UTC; the administrator's server follows it.
    const node = 'db-f49-attacked';
    const result = await monitorCheck(node, '30.000000');
    const incidents = await incidentAlarms(node);
    expect(
      incidents.length > 0
        ? 'time-fault incident raised'
        : `no time-fault incident: steps accepted ${JSON.stringify(accepted)}, active sources ${JSON.stringify(active)}, ` +
            `raised ${JSON.stringify(result.raised.map((a) => a.kind))} (sources over threshold ${result.sources_over_threshold})`,
    ).toBe('time-fault incident raised');
    expect(await incidentRequests(node)).toBeGreaterThan(0);
  });
});

/**
 * Review reproducer F55: the incarnation guard (continuity.current_incarnation, kernel 0600:223) is
 * system_identifier:WAL timeline:database OID:counter table OID. A physical restore that finishes with
 * crash recovery (a pg_basebackup -X stream copy started WITHOUT recovery.signal, or a storage / VM
 * snapshot rollback) keeps all four parts, so continuity.next_counter_value (0600:318) passes the
 * EBMR-CONT-012 check and issues again every value between the restored last_value and the restored
 * reserved_ceiling - values that were already issued on the original after the backup (INV-27).
 *
 * This test performs a REAL physical restore of the test cluster:
 *   1. a protected counter gets a ledger-first block (ceiling 50) and issues 1..10; an anchor is exported;
 *   2. pg_basebackup -X stream -c fast takes a physical backup of the running cluster (time T);
 *   3. the original issues 11..30 (same block: no new ceiling reservation, no new anchor);
 *   4. the backup is started as a second postmaster with NO recovery.signal / standby.signal (it comes
 *      up by crash recovery from backup_label, on the same timeline);
 *   5. the application issues the next number in the restored database.
 *
 * Safe behaviour asserted: the restored database must NOT issue a value already issued after the
 * backup (11..30). Refusing (e.g. EBMR-CONT-012, incarnation changed) is safe; issuing a value above
 * 30 is safe; issuing 11 is the defect.
 */
import { execFileSync } from 'node:child_process';
import { chmodSync, existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import pg from 'pg';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { exportAnchor } from '../../src/continuity/anchors.ts';
import type { FileLedger } from '../../src/continuity/ledger.ts';
import { reserveCounterBlock } from '../../src/continuity/numbers.ts';
import { checkAgainstLedger } from '../../src/continuity/restore.ts';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { ADMIN_URL, createTestDatabase, type TestDatabase } from '../support/db.ts';
import { installNumberStub, tempDir, tempLedger, testActor } from '../continuity/helpers.ts';

const KEY = 'test.number:F55';
const BIN = execFileSync('pg_config', ['--bindir']).toString().trim();

let db: TestDatabase;
let ops: ActorContext;
let ledger: FileLedger;
const dir = tempDir('f55');

// Physical copy of the cluster (outside the repository, removed in afterAll).
const work = mkdtempSync(join(tmpdir(), 'ebmr-f55-pg-'));
const dataDir = join(work, 'data');
const sockDir = join(work, 'sock');
const logFile = join(work, 'restored.log');
const port = 20000 + Math.floor(Math.random() * 20000);
let started = false;
let restoredApp: pg.Pool | undefined;
let restoredAdmin: pg.Pool | undefined;

const issueOn = (pool: pg.Pool) =>
  withCommand(pool, ops, async (c) => (await c.query<{ v: string }>('select testgmp.issue_number($1)::text as v', [KEY])).rows[0]?.v ?? '');

function asPostgres(cmd: string, args: string[]): string {
  return execFileSync('runuser', ['-u', 'postgres', '--', cmd, ...args], { stdio: ['ignore', 'pipe', 'pipe'] }).toString();
}

function restoredUrl(database: string, user: { name: string; password: string }): string {
  const u = new URL(ADMIN_URL);
  u.hostname = '127.0.0.1';
  u.port = String(port);
  u.pathname = `/${database}`;
  u.username = user.name;
  u.password = user.password;
  return u.toString();
}

beforeAll(async () => {
  db = await createTestDatabase();
  ops = await testActor(db, { roleCode: 'SERVICE_ACCOUNT', source: 'SYSTEM' });
  await installNumberStub(db, KEY, 50);
  ledger = tempLedger('f55', dir.path);
  expect(await reserveCounterBlock(db.app, ops, ledger, KEY)).toBe(50n);
  for (let i = 1; i <= 10; i++) expect(await issueOn(db.app)).toBe(String(i));
  // The anchor job ran before the backup: its anchor (and high-water marks) are in the external ledger.
  await exportAnchor(db.app, ledger);
}, 120_000);

afterAll(async () => {
  await restoredApp?.end().catch(() => undefined);
  await restoredAdmin?.end().catch(() => undefined);
  if (started) {
    try {
      asPostgres(join(BIN, 'pg_ctl'), ['-D', dataDir, '-m', 'immediate', '-w', 'stop']);
    } catch {
      /* already stopped */
    }
  }
  rmSync(work, { recursive: true, force: true });
  await db.drop();
  dir.cleanup();
}, 180_000);

describe('F55 incarnation guard after a physical restore that ends with crash recovery', () => {
  it('[INV-27] a pg_basebackup copy started without recovery.signal does not reissue counter values issued after the backup', async () => {
    const incarnationBefore = (await db.admin.query<{ i: string }>('select continuity.current_incarnation() as i')).rows[0]?.i;

    // (2) Physical backup of the running cluster at time T (WAL streamed into the backup).
    execFileSync(join(BIN, 'pg_basebackup'), ['-d', ADMIN_URL, '-D', dataDir, '-X', 'stream', '-c', 'fast', '--no-sync'], {
      stdio: ['ignore', 'pipe', 'pipe'],
      maxBuffer: 64 * 1024 * 1024,
    });
    expect(existsSync(join(dataDir, 'backup_label'))).toBe(true);
    expect(existsSync(join(dataDir, 'recovery.signal'))).toBe(false);
    expect(existsSync(join(dataDir, 'standby.signal'))).toBe(false);

    // (3) After the backup the original keeps issuing from the same block: 11..30, labels printed.
    const afterBackup: string[] = [];
    for (let i = 0; i < 20; i++) afterBackup.push(await issueOn(db.app));
    expect(afterBackup).toEqual(Array.from({ length: 20 }, (_, i) => String(11 + i)));

    // (4) Start the backup as a second postmaster, without recovery.signal (crash recovery from backup_label).
    mkdirSync(sockDir);
    // Debian keeps postgresql.conf outside the data directory; give the copy a minimal one like the original's.
    writeFileSync(join(dataDir, 'postgresql.conf'), "timezone = 'Etc/UTC'\ndatestyle = 'iso, mdy'\n");
    chmodSync(work, 0o755);
    execFileSync('chown', ['-R', 'postgres:postgres', dataDir, sockDir]);
    chmodSync(dataDir, 0o700);
    const opts = [
      `-p ${port}`,
      "-c listen_addresses='127.0.0.1'",
      `-c unix_socket_directories='${sockDir}'`,
      '-c shared_buffers=128MB',
      '-c max_connections=30',
      '-c hba_file=/etc/postgresql/16/main/pg_hba.conf',
      '-c ident_file=/etc/postgresql/16/main/pg_ident.conf',
      '-c archive_mode=off',
    ].join(' ');
    execFileSync('touch', [logFile]);
    execFileSync('chown', ['postgres:postgres', logFile]);
    started = true;
    try {
      asPostgres(join(BIN, 'pg_ctl'), ['-D', dataDir, '-l', logFile, '-w', '-t', '180', '-o', opts, 'start']);
    } catch (error) {
      throw new Error(`setup: the restored cluster did not start: ${(error as Error).message}\n${readFileSync(logFile, 'utf8')}`);
    }
    const serverLog = readFileSync(logFile, 'utf8');

    restoredAdmin = new pg.Pool({ connectionString: restoredUrl(db.name, { name: new URL(ADMIN_URL).username, password: new URL(ADMIN_URL).password }), max: 2 });
    restoredApp = new pg.Pool({ connectionString: restoredUrl(db.name, { name: 'ebmr_app', password: 'ebmr_app' }), max: 2 });

    // Sanity: the restored database holds the state at T (last_value 10, same block of 50).
    const counter = (
      await restoredAdmin.query<{ last_value: string; reserved_ceiling: string; ceiling_incarnation: string; now_incarnation: string; in_recovery: boolean }>(
        `select last_value::text, reserved_ceiling::text, ceiling_incarnation, continuity.current_incarnation() as now_incarnation,
                pg_is_in_recovery() as in_recovery
           from continuity.counter where sequence_key = $1`,
        [KEY],
      )
    ).rows[0];
    expect(counter).toMatchObject({ last_value: '10', reserved_ceiling: '50', in_recovery: false });

    // Evidence only (not asserted): the start-up check against the external ledger.
    const check = await checkAgainstLedger(restoredApp, ledger);

    // (5) The next number issued in the restored database.
    let outcome: { issued?: string; refused?: string };
    try {
      outcome = { issued: await issueOn(restoredApp) };
    } catch (error) {
      outcome = { refused: (error as Error).message };
    }

    const evidence = JSON.stringify(
      {
        incarnationBeforeBackup: incarnationBefore,
        ceilingIncarnation: counter?.ceiling_incarnation,
        incarnationAfterRestore: counter?.now_incarnation,
        alreadyIssuedAfterBackup: `${afterBackup[0]}..${afterBackup[afterBackup.length - 1]}`,
        restoredOutcome: outcome,
        checkAgainstLedger: { ok: check.ok, findings: check.findings.map((f) => `${f.severity} ${f.code} ${f.subject}`) },
        serverLog: serverLog.split('\n').filter((l) => /backup recovery|timeline|redo|ready to accept/.test(l)),
      },
      null,
      2,
    );

    // Safe behaviour: never hand out again a number that the original issued after the backup.
    const reissued = outcome.issued !== undefined && afterBackup.includes(outcome.issued);
    expect(reissued, `restored database reissued an already-issued protected number:\n${evidence}`).toBe(false);
  }, 600_000);
});

/**
 * Review reproducer F56: protected PG_SEQUENCE sources (kernel.audit_event.id, records.incident.incident_no,
 * ...) have no issue guard after a restore. They are moved past the external ledger only by
 * continuity.after_restore (kernel 0600:742), the LAST step of the restore procedure. Every write made in
 * the restored database before that step (the runbook's step-4 data-integrity / time incident, the restore
 * event itself (record_restore_event, 0600:601), the approval e-signature challenge and signature,
 * approve_restore_event, after_restore's own first rows) draws ids from the restored sequences, i.e. ids
 * that the source already issued in the lost window.
 *
 * Flow (mirrors test/continuity/restore.test.ts):
 *   source: history on batch:<id>, anchor, backup (max audit_event.id = B, max incident_no = N);
 *           after the backup: more history on batch:<id>, a lost-window incident (incident_no N+1), anchor
 *           (max audit_event.id = S > B);
 *   restored copy: the runbook step-4 incident is opened, then record -> sign -> approve -> complete.
 *
 * Safe behaviour asserted (INV-27: no identifier issued before the restore is ever issued again):
 *   - no audit event in the restored database has an id in (B, S] (those ids belong to lost-window
 *     events of the source);
 *   - the incident opened in the restored database does not get an incident_no the source issued in the
 *     lost window (a refusal to raise an incident before completion would also be safe).
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { exportAnchor } from '../../src/continuity/anchors.ts';
import type { BackupArtefact } from '../../src/continuity/backup-drill.ts';
import type { FileLedger } from '../../src/continuity/ledger.ts';
import { approveRestoreEvent, completeRestore, recordRestoreEvent } from '../../src/continuity/restore.ts';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { raiseIncident } from '../../src/records/incidents.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import type { SeededActor } from '../identity/seed.ts';
import { backupTestDatabase, dbTime, ensureSealKey, restoreCopy, signerActor, signFor, tempDir, tempLedger, testActor } from '../continuity/helpers.ts';

const dir = tempDir('f56');
let source: TestDatabase;
let restored: TestDatabase;
let ledger: FileLedger;
let ops: ActorContext;
let gateway: ActorContext;
let operator: ActorContext;
let approver: SeededActor;
const batch = randomUUID();
let backup: BackupArtefact;
let backupMaxEventId: bigint;
let sourceMaxEventId: bigint;
let sourceLostEvents: Map<string, string>; // id -> chain_key, events the source wrote after the backup
let sourceLostIncidentNos: string[];
let restoredIncidentId: string | null = null;
let restoredIncidentError: string | null = null;
let restoreEventId: string;

function fresh(ctx: ActorContext): ActorContext {
  return { ...ctx, correlationId: randomUUID() };
}
async function sample(db: TestDatabase, value: string): Promise<void> {
  await withCommand(db.app, fresh(ops), (c) => c.query('insert into testgmp.sample (batch_id, value) values ($1, $2)', [batch, value]));
}
async function maxEventId(db: TestDatabase): Promise<bigint> {
  return BigInt((await db.app.query<{ m: string | null }>('select max(id)::text as m from kernel.audit_event')).rows[0]?.m ?? '0');
}
async function timeIncident(db: TestDatabase, title: string): Promise<string> {
  return withCommand(db.app, fresh(gateway), (c) =>
    raiseIncident(c, { source: 'TIME_SYNC', type: 'CLOCK_DRIFT', severity: 'MAJOR', title, description: 'clock offset check' }),
  );
}

beforeAll(async () => {
  source = await createTestDatabase();
  ledger = tempLedger('f56-source', dir.path);
  ops = await testActor(source, { roleCode: 'SERVICE_ACCOUNT', source: 'SYSTEM' });
  gateway = await testActor(source, { source: 'SYSTEM', roleCode: 'SYSTEM', legalName: 'site gateway (time monitor)' });
  operator = await testActor(source, { roleCode: 'SYSTEM_ADMINISTRATOR', legalName: 'Restore Operator' });
  approver = await signerActor(source, 'QA_REVIEWER', 'QA Approver');
  await ensureSealKey(source);

  // History before the backup.
  await sample(source, '1');
  await sample(source, '2');
  await timeIncident(source, 'pre-backup drift');
  await exportAnchor(source.app, ledger);
  backupMaxEventId = await maxEventId(source);
  backup = await backupTestDatabase(source, dir.path);

  // The lost window: history and an incident the source issues after the backup.
  await sample(source, '3');
  await sample(source, '4');
  await sample(source, '5');
  const lostIncident = await timeIncident(source, 'lost-window incident (quoted in a CAPA / CERT-In report)');
  sourceLostIncidentNos = (
    await source.app.query<{ n: string }>('select incident_no::text as n from records.incident where id = $1', [lostIncident])
  ).rows.map((r) => r.n);
  await exportAnchor(source.app, ledger);
  sourceMaxEventId = await maxEventId(source);
  const lost = await source.app.query<{ id: string; chain_key: string }>(
    'select id::text as id, chain_key from kernel.audit_event where id > $1 order by id',
    [backupMaxEventId.toString()],
  );
  sourceLostEvents = new Map(lost.rows.map((r) => [r.id, r.chain_key]));

  // The disaster: the backup is restored into a new database.
  restored = await restoreCopy(source, backup, dir.path);

  // Runbook 5.2 step 4 / 5.4 step 3: the clock offset check fails and a data-integrity incident is opened
  // in the restored database, before the restore event is recorded.
  try {
    restoredIncidentId = await timeIncident(restored, 'clock offset above threshold after restore');
  } catch (error) {
    restoredIncidentError = error instanceof Error ? error.message : String(error);
  }

  // Runbook steps 6-8: record, approve (signed), complete.
  const recorded = await recordRestoreEvent(restored.app, fresh(operator), ledger, {
    eventKind: 'FULL_RESTORE',
    backupId: backup.backupId,
    backupTakenAt: backup.snapshotTakenAt,
    restorePoint: backup.snapshotTakenAt,
    performedAt: await dbTime(restored),
    reason: 'Primary storage failure; restored from the last good backup',
    changeReference: 'INC-2026-0056',
    approverPersonIds: [approver.personId],
  });
  restoreEventId = recorded.restoreEventId;
  const signature = await signFor(restored, approver, { type: 'restore_event', id: restoreEventId }, 'RESTORE_APPROVED', 'RECORDED', { registerKey: false });
  await approveRestoreEvent(restored.app, fresh(approver), restoreEventId, signature);
  await completeRestore(restored.app, fresh(operator), ledger, restoreEventId);
}, 120_000);

afterAll(async () => {
  await restored?.drop();
  await source?.drop();
  dir.cleanup();
});

describe('F56: protected PG_SEQUENCE ids written before after_restore', () => {
  it('sanity: the source really issued audit event ids and an incident number after the backup', () => {
    expect(sourceMaxEventId).toBeGreaterThan(backupMaxEventId);
    expect(sourceLostEvents.size).toBeGreaterThan(0);
    expect([...sourceLostEvents.values()]).toContain(`batch:${batch}`);
    expect(sourceLostIncidentNos).toHaveLength(1);
  });

  it('[INV-27] no audit event id the source issued in the lost window is issued again in the restored database', async () => {
    const { rows } = await restored.app.query<{ id: string; chain_key: string; action: string }>(
      'select id::text as id, chain_key, action from kernel.audit_event where id > $1 and id <= $2 order by id',
      [backupMaxEventId.toString(), sourceMaxEventId.toString()],
    );
    const reused = rows.map((r) => `id ${r.id}: restored ${r.chain_key} (${r.action}) / source ${sourceLostEvents.get(r.id) ?? '?'}`);
    expect(reused, `audit event ids reissued after the restore:\n${reused.join('\n')}`).toEqual([]);
  });

  it('[INV-27] an incident opened in the restored database never reuses a lost-window incident number', async () => {
    if (restoredIncidentId === null) {
      // Refusing to raise an incident before the restore is completed is safe, but only as a deliberate refusal.
      expect(restoredIncidentError).toMatch(/EBMR-/);
      return;
    }
    const { rows } = await restored.app.query<{ n: string; reference: string }>(
      'select incident_no::text as n, reference from records.incident_current where id = $1',
      [restoredIncidentId],
    );
    const no = rows[0]?.n ?? '';
    expect(no).not.toBe('');
    expect(sourceLostIncidentNos, `restored incident ${rows[0]?.reference} reuses a lost-window incident number`).not.toContain(no);
  });
});

/**
 * Review reproducer F57: continuity.compare_external_anchors (kernel 0600:502) classifies an external
 * anchor DISCARDABLE when it is absent from kernel.audit_anchor and only chain heads differ. It never
 * checks that the chain actually ENDS before the anchored seq (ADR 0007 decision 6: the verifier accepts
 * "a chain that ends at the restore point"), that the anchor post-dates the restore point / backup, or
 * that the database was restored or failed over at all. continuity.verify_external_anchors (0600:857)
 * then reports the difference as COVERED once an approved restore event lists the anchor.
 *
 * Scenario (one database, never restored):
 *   1. three GMP writes on batch:<id> (seq 1..3); anchor A1 exported at seq 2, A2 at seq 3.
 *   2. a superuser (session_replication_role = replica, so no trigger and no ddl_log entry) rewrites the
 *      GMP value of the third write (3 -> 99), rewrites audit event seq 3 with a recomputed hash, moves
 *      the chain head, and deletes the kernel.audit_anchor row of A2. The chain still verifies; only the
 *      external copy of A2 shows the change (PROBLEM).
 *   3. a SYSTEM_ADMINISTRATOR records a FAILOVER restore event (no backup needed) with the ledger anchors;
 *      the QA approver signs RESTORE_APPROVED and approves; the restore is completed.
 *
 * Safe behaviour asserted: history that is still present at the anchored seq (changed, not lost) is never
 * DISCARDABLE, so no restore event can cover it: after step 3, A2 is still a PROBLEM and the start-up
 * check against the ledger still fails with ANCHOR_MISMATCH. (A fix that refuses to record the event on a
 * database that was never restored is equally safe; the test accepts that too.)
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { exportAnchor, verifyExternalAnchors } from '../../src/continuity/anchors.ts';
import type { ExternalAnchor, FileLedger } from '../../src/continuity/ledger.ts';
import { approveRestoreEvent, checkAgainstLedger, completeRestore, recordRestoreEvent } from '../../src/continuity/restore.ts';
import { verifyChain } from '../../src/audit/verify.ts';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import type { SeededActor } from '../identity/seed.ts';
import { dbTime, ensureSealKey, signerActor, signFor, tempDir, tempLedger, testActor } from '../continuity/helpers.ts';

const dir = tempDir('f57');
let db: TestDatabase;
let ledger: FileLedger;
let ops: ActorContext;
let operator: ActorContext;
let approver: SeededActor;
const batch = randomUUID();
const chain = `batch:${batch}`;
let a1: ExternalAnchor;
let a2: ExternalAnchor;

function fresh(ctx: ActorContext): ActorContext {
  return { ...ctx, correlationId: randomUUID() };
}
async function sample(value: string): Promise<void> {
  await withCommand(db.app, fresh(ops), (c) => c.query('insert into testgmp.sample (batch_id, value) values ($1, $2)', [batch, value]));
}

beforeAll(async () => {
  db = await createTestDatabase();
  ledger = tempLedger('f57', dir.path);
  ops = await testActor(db, { roleCode: 'SERVICE_ACCOUNT', source: 'SYSTEM' });
  operator = await testActor(db, { roleCode: 'SYSTEM_ADMINISTRATOR', legalName: 'Restore Operator' });
  approver = await signerActor(db, 'QA_REVIEWER', 'QA Approver');
  await ensureSealKey(db);

  // (1) Three GMP writes on the batch chain; A1 anchors seq 2, A2 anchors seq 3.
  await sample('1');
  await sample('2');
  a1 = await exportAnchor(db.app, ledger);
  await sample('3');
  a2 = await exportAnchor(db.app, ledger);
}, 60_000);

afterAll(async () => {
  await db?.drop();
  dir.cleanup();
});

describe('F57: an approved restore event must not cover changed (not lost) anchored history', () => {
  it('[INV-08][DI-45][DI-23] a FAILOVER event on a never-restored database does not turn a rewritten anchored event into COVERED', async () => {
    // Preconditions: A1 anchors the batch chain at seq 2, A2 at seq 3; both match.
    expect(a1.heads.find((h) => h.chain_key === chain)?.seq).toBe(2);
    expect(a2.heads.find((h) => h.chain_key === chain)?.seq).toBe(3);
    const before = await verifyExternalAnchors(db.app, ledger);
    expect(before.filter((r) => r.status !== 'MATCH')).toEqual([]);

    // (2) Superuser tampering without triggers: change the GMP value 3 -> 99, rewrite audit event seq 3
    // with a recomputed hash, move the chain head, delete the database copy of A2.
    const c = await db.admin.connect();
    try {
      await c.query('begin');
      await c.query("set local session_replication_role = 'replica'");
      await c.query("update testgmp.sample set value = 99 where batch_id = $1 and value = 3", [batch]);
      await c.query(
        `update kernel.audit_event set payload = jsonb_set(payload, '{body,new,value}', '99'),
                hash = sha256(prev_hash || convert_to(jsonb_set(payload, '{body,new,value}', '99')::text, 'UTF8'))
          where chain_key = $1 and seq = 3`,
        [chain],
      );
      await c.query(
        `update kernel.audit_chain_head h set last_hash = e.hash
           from kernel.audit_event e where e.chain_key = h.chain_key and e.seq = h.last_seq and h.chain_key = $1`,
        [chain],
      );
      await c.query('delete from kernel.audit_anchor where id = $1', [a2.anchor_id]);
      await c.query('commit');
    } catch (error) {
      await c.query('rollback');
      throw error;
    } finally {
      c.release();
    }

    // The tampering is effective: the GMP value is 99, the chain still verifies and still has seq 3,
    // and only the external copy of A2 reveals the change.
    const values = await db.app.query<{ v: string }>('select value::text as v from testgmp.sample where batch_id = $1 order by value', [batch]);
    expect(values.rows.map((r) => r.v)).toEqual(['1', '2', '99']);
    expect(await verifyChain(db.app, chain)).toEqual([]);
    const head = await db.app.query<{ s: string }>('select last_seq::text as s from kernel.audit_chain_head where chain_key = $1', [chain]);
    expect(head.rows[0]?.s).toBe('3');
    const tampered = await verifyExternalAnchors(db.app, ledger);
    expect(tampered.filter((r) => r.anchorId === a1.anchor_id).map((r) => r.status)).toEqual(['MATCH']);
    expect(tampered.filter((r) => r.anchorId === a2.anchor_id).map((r) => r.status)).toEqual(['PROBLEM']);

    // (3) A FAILOVER restore event (no backup, no restore took place), signed and approved by QA, completed.
    let a2Classification: string | undefined;
    let affected: string[] = [];
    let recordError: string | null = null;
    try {
      const recorded = await recordRestoreEvent(db.app, fresh(operator), ledger, {
        eventKind: 'FAILOVER',
        performedAt: await dbTime(db),
        reason: 'Planned failover to the standby node',
        changeReference: 'CHG-2026-0057',
        approverPersonIds: [approver.personId],
      });
      a2Classification = recorded.comparison.find((x) => String(x.anchor_id) === a2.anchor_id)?.status;
      affected = recorded.affectedChainKeys;
      const signature = await signFor(db, approver, { type: 'restore_event', id: recorded.restoreEventId }, 'RESTORE_APPROVED', 'RECORDED');
      await approveRestoreEvent(db.app, approver, recorded.restoreEventId, signature);
      await completeRestore(db.app, fresh(operator), ledger, recorded.restoreEventId);
    } catch (error) {
      // Refusing to record/approve such an event is safe behaviour.
      recordError = error instanceof Error ? error.message : String(error);
    }

    // Safe behaviour: the rewritten anchored event is still reported; nothing covers it.
    const after = await verifyExternalAnchors(db.app, ledger);
    const a2After = after.filter((r) => r.anchorId === a2.anchor_id);
    expect.soft(
      a2After.map((r) => ({ status: r.status, problem: r.problem })),
      `A2 anchored ${chain} at seq 3, which is still present with a different hash (changed, not lost); recordError=${recordError}; ` +
        `A2 classified ${a2Classification}; affected chains ${JSON.stringify(affected)}`,
    ).toEqual([{ status: 'PROBLEM', problem: `chain ${chain} at seq 3 differs from external anchor ${a2.anchor_id}` }]);
    expect.soft(a2Classification, 'history still present at the anchored seq must not be DISCARDABLE').not.toBe('DISCARDABLE');
    const check = await checkAgainstLedger(db.app, ledger);
    expect.soft(check.findings.map((f) => f.code), 'start-up check against the ledger').toContain('ANCHOR_MISMATCH');
    expect.soft(check.ok, 'start-up check against the ledger').toBe(false);
  });
});

/**
 * Review reproducer F58: reserveCounterBlock (packages/kernel/src/continuity/numbers.ts:77) appends the
 * CEILING entry to the external ledger BEFORE it opens the transaction, runs kernel.begin_command and
 * calls continuity.reserve_counter_ceiling, which is where DI-18 and CONTINUITY.COUNTER_RESERVE (at the
 * actor's location) are checked. A refused reservation therefore leaves a ceiling in the ledger that the
 * database never acknowledged.
 *
 * Scenario (batch-number rule PX-TAB, block 5, SITE-1; the README says product-limited issuers cannot
 * reserve and rely on ceilings reserved by an unrestricted issuer):
 *   1. an unrestricted BATCH_ISSUER allocates PX0001 (ledger and database ceiling 5);
 *   2. a BATCH_ISSUER whose grant is limited to product PX allocates PX0002..PX0005 (block used up);
 *   3. the product-limited issuer tries 4 more allocations; each is refused (it cannot reserve);
 *   4. the unrestricted issuer allocates the next number.
 *
 * Safe behaviour asserted: a refused reservation writes nothing outside the database, so after step 3
 * the ledger ceiling still equals the database ceiling (5), step 4 returns serial 6 (PX0006), and no
 * LEDGER_AHEAD alarm or sequence bump is raised (that alarm is the signal of an unrecorded restore and
 * must not fire in routine operation). The refusal itself may be EBMR-IAM-040 (current behaviour) or
 * EBMR-CONT-011 (a fix that skips the reservation for actors without the permission).
 */
import { randomUUID } from 'node:crypto';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type pg from 'pg';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { FileLedger, ledgerMaxCeiling } from '../../src/continuity/ledger.ts';
import { withProtectedNumbers } from '../../src/continuity/numbers.ts';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { seedActor } from '../identity/seed.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';

const SITE = 'SITE-1'; // the seeded devices are at SITE-1
const ZONE = 'Asia/Kolkata';
const PRODUCT = 'PX';
const RULE = 'PX-TAB';
const KEY = `site.batch_number:${RULE}`;

let db: TestDatabase;
let dir: string;
let ledger: FileLedger;
let steward: ActorContext;
let issuer: ActorContext;
let limited: ActorContext;

const again = (ctx: ActorContext): ActorContext => ({ ...ctx, correlationId: randomUUID() });

async function allocateOn(c: pg.PoolClient): Promise<{ batch_number: string; serial: string }> {
  const { rows } = await c.query<{ batch_number: string; serial: string }>(
    'select batch_number, serial::text as serial from site.allocate_batch_number($1::jsonb)',
    [
      JSON.stringify({
        site_code: SITE,
        product_code: PRODUCT,
        product_name: 'Product PX',
        edition: 'TABLETS',
        batch_kind: 'PROCESSING',
        batch_size: '1000',
        batch_size_unit: '{tbl}',
      }),
    ],
  );
  const r = rows[0];
  if (!r) throw new Error('no row');
  return r;
}

const allocate = (ctx: ActorContext) => withProtectedNumbers(db.app, again(ctx), ledger, allocateOn);

beforeAll(async () => {
  db = await createTestDatabase();
  dir = mkdtempSync(join(tmpdir(), 'ebmr-f58-'));
  ledger = new FileLedger(join(dir, 'f58.ledger.jsonl'), { database: 'f58' });
  steward = await seededTestActor(db, { roleCode: 'MASTER_DATA_STEWARD' });
  issuer = await seededTestActor(db, { roleCode: 'BATCH_ISSUER' });
  const { seed: _seed, ...ctx } = await seedActor(db, { roleCode: 'BATCH_ISSUER', scope: { site: SITE, product: PRODUCT }, acknowledgeEsig: false });
  void _seed;
  limited = ctx;
  await withCommand(db.app, again(steward), (c) =>
    c.query('select site.define_batch_number_rule($1::jsonb)', [
      JSON.stringify({
        rule_code: RULE,
        site_code: SITE,
        product_code: PRODUCT,
        batch_kind: 'PROCESSING',
        format: 'PX{SEQ:4}',
        site_zone: ZONE,
        effective_from: null,
        reason: 'SOP-QA-017',
        block_size: 5,
      }),
    ]),
  );
});

afterAll(async () => {
  await db.drop();
  rmSync(dir, { recursive: true, force: true });
});

describe('F58 counter reservation writes to the ledger before authorisation', () => {
  it('[INV-27][IN-18][DI-17] a reservation refused by the database leaves no ceiling in the external ledger, burns no serials and raises no LEDGER_AHEAD alarm', async () => {
    // 1. unrestricted issuer: first number, ceiling 5 in the ledger and in the database.
    expect((await allocate(issuer)).batch_number).toBe('PX0001');
    expect(await ledgerMaxCeiling(ledger, KEY)).toBe(5n);

    // 2. product-limited issuer uses up the block (no reservation needed).
    const used: string[] = [];
    for (let i = 0; i < 4; i++) used.push((await allocate(limited)).batch_number);
    expect(used).toEqual(['PX0002', 'PX0003', 'PX0004', 'PX0005']);

    // 3. product-limited issuer: 4 more attempts, each refused because it cannot reserve a block.
    const refusals: string[] = [];
    for (let i = 0; i < 4; i++) {
      try {
        await allocate(limited);
        refusals.push('ALLOCATED');
      } catch (error) {
        refusals.push(String((error as Error).message));
      }
    }
    for (const r of refusals) expect(r).toMatch(/^(EBMR-IAM-040 .*CONTINUITY\.COUNTER_RESERVE|EBMR-CONT-011)/);

    const ledgerAfterRefusals = await ledgerMaxCeiling(ledger, KEY);
    const dbCounter = await db.app.query<{ reserved_ceiling: string; last_value: string }>(
      'select reserved_ceiling::text, last_value::text from continuity.counter where sequence_key = $1',
      [KEY],
    );

    // 4. the next authorised allocation.
    const next = await allocate(issuer);
    const alarms = await db.app.query<{ severity: string; details: Record<string, unknown> }>(
      "select severity, details from continuity.open_alarm where alarm_code = 'LEDGER_AHEAD' and details ->> 'sequence_key' = $1",
      [KEY],
    );
    const bumps = await db.app.query<{ value_before: string; value_after: string }>(
      "select value_before::text, value_after::text from continuity.sequence_bump where sequence_key = $1 and reason = 'LEDGER_AHEAD'",
      [KEY],
    );

    expect({
      databaseCounter: dbCounter.rows[0],
      ledgerCeilingAfterRefusals: ledgerAfterRefusals?.toString(),
      nextAuthorisedNumber: next.batch_number,
      ledgerAheadAlarms: alarms.rows,
      ledgerAheadBumps: bumps.rows,
    }).toEqual({
      databaseCounter: { reserved_ceiling: '5', last_value: '5' },
      ledgerCeilingAfterRefusals: '5',
      nextAuthorisedNumber: 'PX0006',
      ledgerAheadAlarms: [],
      ledgerAheadBumps: [],
    });
  });
});

/**
 * Review reproducer F59: INV-27 says user IDs are never reused "including after a restore". The restore
 * procedure (continuity.after_restore, packages/kernel/sql/0600_continuity_core.sql:742) only moves
 * numeric PG sequences and protected counters past the external ledger's high-water marks. Login names
 * live only in iam.issued_identifier / iam.account (0110_iam_persons_accounts.sql); they are not written
 * to the external ledger, so a login name issued in a restore's lost window is unknown to the restored
 * database and iam.create_account (0110:340) issues it again, to another person.
 *
 * Scenario:
 *   1. Persons A and B exist (identity verified); an anchor is exported; the database is backed up.
 *   2. After the backup, an administrator creates account 'asharma' for person A; an anchor is exported
 *      (so the external ledger holds the account's chain).
 *   3. Disaster: the backup is restored into a new database; the full restore procedure runs (recorded,
 *      approved with the approver's RESTORE_APPROVED signature, completed).
 *   4. The administrator creates account 'asharma' for person B in the restored database.
 *
 * Safe behaviour asserted: step 4 is refused (the user ID was issued before the restore and must never be
 * issued again). Control: in the same restored database, the same administrator can create an account for
 * a third person under a fresh login name, and person B has no account there, so a refusal in step 4 is
 * about the name and nothing else.
 */
import { randomBytes } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { exportAnchor } from '../../src/continuity/anchors.ts';
import type { BackupArtefact } from '../../src/continuity/backup-drill.ts';
import type { FileLedger } from '../../src/continuity/ledger.ts';
import { approveRestoreEvent, completeRestore, lostWindow, recordRestoreEvent } from '../../src/continuity/restore.ts';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { createAccount, createPerson, recordIdentityVerification } from '../../src/identity/admin.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seedAdministration, withReason, type SeededActor } from '../identity/seed.ts';
import { backupTestDatabase, dbTime, ensureSealKey, restoreCopy, signerActor, signFor, tempDir, tempLedger, testActor } from '../continuity/helpers.ts';

const dir = tempDir('f59');
const LOGIN = 'asharma';
let source: TestDatabase;
let restored: TestDatabase;
let ledger: FileLedger;
let admin: SeededActor;
let operator: ActorContext;
let approver: SeededActor;
let personA: string;
let personB: string;
let personC: string;
let accountA: string;
let backup: BackupArtefact;
let restoreEventId: string;

async function verifiedPerson(db: TestDatabase, legalName: string): Promise<string> {
  return withCommand(db.app, withReason(admin), async (c) => {
    const personId = await createPerson(c, 'NATURAL', legalName);
    await recordIdentityVerification(c, {
      personId, purpose: 'INITIAL', method: 'IN_PERSON_DOCUMENT', documentType: 'Employee ID card',
      evidenceRef: `HR-${randomBytes(4).toString('hex')}`, occurredAt: new Date(Date.UTC(2026, 0, 5)).toISOString(),
    });
    return personId;
  });
}

function newAccount(db: TestDatabase, personId: string, loginName: string): Promise<string> {
  return withCommand(db.app, withReason(admin), (c) => createAccount(c, { personId, loginName, kind: 'HUMAN' }));
}

beforeAll(async () => {
  source = await createTestDatabase();
  ledger = tempLedger('f59-source', dir.path);
  admin = (await seedAdministration(source)).admin;
  operator = await testActor(source, { roleCode: 'SYSTEM_ADMINISTRATOR', legalName: 'Restore Operator' });
  approver = await signerActor(source, 'QA_REVIEWER', 'QA Approver');
  await ensureSealKey(source);

  // 1. Before the backup: persons A and B, identity verified, no account with the login name yet.
  personA = await verifiedPerson(source, 'Anil Sharma');
  personB = await verifiedPerson(source, 'Asha Sharma');
  personC = await verifiedPerson(source, 'Control Person');
  await exportAnchor(source.app, ledger);
  backup = await backupTestDatabase(source, dir.path);

  // 2. In the window that the restore will lose: 'asharma' is issued to person A (10:05).
  accountA = await newAccount(source, personA, LOGIN);
  await exportAnchor(source.app, ledger);

  // 3. Disaster at the site: the backup (10:00) is restored and the full restore procedure runs.
  restored = await restoreCopy(source, backup, dir.path);
  const recorded = await recordRestoreEvent(restored.app, operator, ledger, {
    eventKind: 'FULL_RESTORE',
    backupId: backup.backupId,
    backupTakenAt: backup.snapshotTakenAt,
    restorePoint: backup.snapshotTakenAt,
    performedAt: await dbTime(restored),
    reason: 'Primary storage failure; restored from the last good backup',
    changeReference: 'INC-2026-0059',
    approverPersonIds: [approver.personId],
  });
  restoreEventId = recorded.restoreEventId;
  const signature = await signFor(restored, approver, { type: 'restore_event', id: restoreEventId }, 'RESTORE_APPROVED', 'RECORDED', { registerKey: false });
  await approveRestoreEvent(restored.app, approver, restoreEventId, signature);
  await completeRestore(restored.app, operator, ledger, restoreEventId);
}, 120_000);

afterAll(async () => {
  await restored?.drop();
  await source?.drop();
  dir.cleanup();
});

describe('F59: login names issued in a restore lost window', () => {
  it('precondition: the name was issued to person A in the source after the backup, and the restore procedure completed', async () => {
    const src = await source.app.query<{ person_id: string }>('select person_id::text from iam.account where login_name = $1', [LOGIN]);
    expect(src.rows.map((r) => r.person_id)).toEqual([personA]);
    const status = await restored.app.query<{ status: string }>('select status from continuity.restore_event_status where id = $1', [restoreEventId]);
    expect(status.rows[0]?.status).toBe('COMPLETED');
    // The lost window names the account's chain (a uuid), not its login name.
    const lost = await lostWindow(restored.app, restoreEventId);
    expect(lost.map((l) => l.chainKey)).toContain(`account:${accountA}`);
  });

  it('control: the administrator can create accounts in the restored database (fresh name, another person)', async () => {
    const fresh = `csharma-${randomBytes(3).toString('hex')}`;
    const id = await newAccount(restored, personC, fresh);
    expect(id).toMatch(/^[0-9a-f-]{36}$/);
    // Person B has no account in the restored database, so nothing but the name can refuse the next step.
    const b = await restored.app.query('select 1 from iam.account where person_id = $1', [personB]);
    expect(b.rowCount).toBe(0);
  });

  it('[INV-27][DI-15] a login name issued before the restore (in the lost window) is never issued again, to anyone', async () => {
    let issuedTo: string | undefined;
    let refusal: unknown;
    try {
      await newAccount(restored, personB, LOGIN);
      const r = await restored.app.query<{ person_id: string }>('select person_id::text from iam.account where login_name = $1', [LOGIN]);
      issuedTo = r.rows[0]?.person_id;
    } catch (error) {
      refusal = error;
    }
    expect(issuedTo, `user ID '${LOGIN}' (issued to person ${personA} before the restore) was issued again to person ${issuedTo} after the restore`).toBeUndefined();
    expect(String(refusal)).toMatch(/EBMR-/);
  });
});

/**
 * Review reproducer F68: after a co-signature, the co-signer's actor context stays validated for the
 * rest of the transaction, so the application role can re-install it with set_config and act as the
 * co-signer (authorization checks, attribution, audit actor).
 *
 * esig.sign (0230) installs the co-signer's context with iam.set_internal_actor, which leaves a
 * kernel.command_marker row and an iam.command_log row for the context's hash, and then restores the
 * terminal owner's context with kernel.set_actor_context without removing those rows.
 * kernel.actor_context_validated / iam.actor_is_validated accept any context whose hash has a marker
 * in the current transaction, and the context itself is the transaction-local GUC ebmr.ctx that any
 * role may set.
 *
 * Safe behaviour asserted here: once esig.sign has handed the command back to the performer, a
 * set_config back to the co-signer's exact context is not a validated actor
 * (iam.actor_is_validated() is false, kernel.current_actor() is NULL) and records.raise_incident
 * under it is refused, so no incident and no audit event is attributed to the co-signer.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type pg from 'pg';
import { toDbContext } from '../../src/db/command.ts';
import { sign } from '../../src/esig/signing.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { challengeFor, cmd, createStub, ensureSealKey, signatureAuth, signStub, testActor, testSealKey } from '../esig/helpers.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
});

afterAll(async () => {
  await db.drop();
});

const codeOf = (e: unknown): string => {
  const m = e instanceof Error ? e.message : String(e);
  return m.match(/EBMR-[A-Z]+-\d+/)?.[0] ?? `UNEXPECTED: ${m}`;
};

async function attempt<T>(c: pg.PoolClient, name: string, work: () => Promise<T>): Promise<{ ok: true; value: T } | { ok: false; code: string }> {
  await c.query(`savepoint ${name}`);
  try {
    const value = await work();
    await c.query(`release savepoint ${name}`);
    return { ok: true, value };
  } catch (e) {
    await c.query(`rollback to savepoint ${name}`);
    return { ok: false, code: codeOf(e) };
  }
}

describe('F68: the co-signer context cannot be re-installed by the application after esig.sign', () => {
  it('[DI-17][DI-18][INV-40][INV-07][DI-22] after a co-signature, set_config to the co-signer context is not validated and raise_incident is not attributed to the co-signer', async () => {
    const performer = await testActor(db, { deviceClass: 'SHARED', withPin: true, legalName: 'F68 Performer' });
    const verifier = await testActor(db, { roleCode: 'VERIFIER', deviceClass: 'SHARED', withPin: true, legalName: 'F68 Verifier' });
    const stubId = await createStub(db, performer);
    await signStub(db, performer, stubId, { meaning: 'PERFORMED', method: 'BADGE_PIN' });

    // Normal co-signature: challenge for VERIFIED naming the verifier, the verifier authenticates at
    // the performer's shared terminal, esig.sign applies the co-signature in the performer's command.
    const ch = await challengeFor(db, performer, stubId, { meaning: 'VERIFIED', signer: verifier });
    expect(ch.cosignature).toBe(true);
    const verifierEvent = await signatureAuth(db, verifier, performer, ch.challengeId, 'BADGE_PIN');
    const performerCtx = await cmd(db, performer);

    const observed: Record<string, unknown> = {};
    const c = await db.app.connect();
    try {
      await c.query('begin');
      await c.query('select kernel.begin_command($1::jsonb)', [JSON.stringify(toDbContext(performerCtx))]);
      const sig = await sign(c, { challengeId: ch.challengeId, authEventId: verifierEvent, expectedState: 'OPEN' }, testSealKey);
      expect(sig.cosignature).toBe(true);

      // esig.sign handed the command back to the performer.
      const back = await c.query<{ p: string }>("select iam.assert_validated_actor() ->> 'person_id' as p");
      expect(back.rows[0]?.p).toBe(performer.personId);

      // Control: with the performer's context back, raising an incident is attributed to the performer.
      const control = await attempt(c, 'control', () =>
        c.query<{ id: string }>("select records.raise_incident('OTHER', 'F68_CONTROL', 'MINOR', 'F68 control incident', 'by the performer') as id"));
      expect(control.ok).toBe(true);
      if (control.ok) {
        const { rows } = await c.query<{ p: string }>('select raised_by_person::text as p from records.incident where id = $1', [control.value.rows[0]?.id]);
        expect(rows[0]?.p).toBe(performer.personId);
      }

      // What the application can read from the signature it just wrote (ebmr_app has select on esig.signature).
      const { rows: sigRows } = await c.query<{ person_id: string; account_id: string; role_code: string; auth_event_id: string; legal_name: string }>(
        `select signer_person::text as person_id, signer_account::text as account_id, signer_role_code as role_code,
                auth_event_id::text as auth_event_id, signer_legal_name as legal_name
           from esig.signature where id = $1`, [sig.signatureId]);
      const s = sigRows[0];
      expect(s?.person_id).toBe(verifier.personId);

      // The application re-installs the co-signer's context with set_config (no kernel code involved).
      await c.query("select set_config('ebmr.ctx', (current_setting('ebmr.ctx')::jsonb || $1::jsonb)::text, true)", [JSON.stringify(s)]);

      // 1. Not a validated actor.
      const v = await c.query<{ ok: boolean }>('select iam.actor_is_validated() as ok');
      observed['actorIsValidated'] = v.rows[0]?.ok ?? null;
      const cur = await c.query<{ p: string | null }>("select kernel.current_actor() ->> 'person_id' as p");
      observed['currentActorPerson'] = cur.rows[0]?.p ?? null;

      // 2. A GMP write under it must not be attributed to the co-signer.
      const forged = await attempt(c, 'forged', () =>
        c.query<{ id: string }>("select records.raise_incident('OTHER', 'F68_FORGED', 'MINOR', 'F68 forged incident', 'raised as the verifier') as id"));
      if (forged.ok) {
        const id = forged.value.rows[0]?.id;
        const inc = await c.query<{ p: string }>('select raised_by_person::text as p from records.incident where id = $1', [id]);
        const aud = await c.query<{ p: string; ev: string; sess: string }>(
          `select payload -> 'actor' ->> 'person_id' as p, payload -> 'actor' ->> 'auth_event_id' as ev, payload -> 'actor' ->> 'session_id' as sess
             from kernel.audit_event where table_name = 'records.incident' and record_id = $1`, [id]);
        observed['forgedIncident'] = {
          accepted: true,
          raisedByVerifier: inc.rows[0]?.p === verifier.personId,
          auditActorIsVerifier: aud.rows[0]?.p === verifier.personId,
          auditReusesConsumedSignatureEvent: aud.rows[0]?.ev === verifierEvent,
          auditInPerformersSession: aud.rows[0]?.sess === performer.sessionId,
        };
      } else {
        observed['forgedIncident'] = forged.code;
      }
    } finally {
      // Nothing is committed: the forgery is observed inside the transaction only.
      await c.query('rollback');
      c.release();
    }

    expect(observed).toEqual({
      actorIsValidated: false,
      currentActorPerson: null,
      forgedIncident: expect.stringMatching(/^EBMR-(IAM|AUDIT)-\d+$/),
    });
  });
});

/**
 * Review reproducer F69: platform.raise_time_incident is callable by the application role with no
 * source or permission check of its own, so any person holding INCIDENT.RAISE (every shop-floor
 * role) can forge a data-integrity time-fault alarm and incident, and - worse - pre-empt the time
 * monitor: record_drift_check raises a fault only "once per open condition" (open_alarm_id), so a
 * user-raised MINOR DRIFT_EXCEEDED alarm for the real node suppresses the monitor's MAJOR alarm and
 * automatic DATA_INTEGRITY incident when a genuine drift is measured (DI-27, DI-17, INV-16).
 *
 * 0520 grants EXECUTE on platform.raise_time_incident to ebmr_app; 0900 redefines it (the live
 * version) to call platform.raise_alarm and records.raise_incident as owner, with no
 * source = 'SYSTEM' check and no platform.authorize('platform.time_check.record', ...) - unlike
 * platform.record_drift_check (0520:204-207), which refuses anyone but the SYSTEM time monitor.
 *
 * Safe behaviour asserted here:
 *   (a) an OPERATOR calling platform.raise_time_incident directly is refused, and no time-fault
 *       alarm or TIME_SYNC incident is attributed to the operator;
 *   (b) after an operator's attempt to pre-raise a MINOR DRIFT_EXCEEDED alarm for the real node,
 *       a genuine 3.5 s drift measured by the time monitor still raises the DRIFT_EXCEEDED alarm
 *       (MAJOR) and its automatic DATA_INTEGRITY / TIME_SYNC incident detected by SYSTEM.
 * Control: on an untouched node the same monitor check raises DRIFT_EXCEEDED with its incident,
 * which proves the test's drift readings do trigger the monitor.
 */
import { randomBytes, randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';
import { seedAdministration } from '../identity/seed.ts';

let db: TestDatabase;
let monitor: ActorContext;
let operator: ActorContext;
let npl = '';
let nic = '';

const again = <T extends ActorContext>(ctx: T): T => ({ ...ctx, correlationId: randomUUID() });

const codeOf = (e: unknown): string => {
  const m = e instanceof Error ? e.message : String(e);
  if (/permission denied/.test(m)) return 'PERMISSION_DENIED';
  return m.match(/EBMR-[A-Z]+-\d+/)?.[0] ?? `UNEXPECTED: ${m}`;
};

async function registerSource(admin: ActorContext, name: string, reference: string): Promise<string> {
  return withCommand(db.app, again(admin), async (c) => {
    const { rows } = await c.query<{ id: string }>(
      "select platform.register_time_source($1, 'NTP', $2, $3, $4, 'VAL-TS-F69') as id",
      [name, `${name.toLowerCase().replace(/\W+/g, '-')}.example`, reference, randomUUID()],
    );
    return rows[0]?.id ?? '';
  });
}

/** The time monitor (SYSTEM service identity holding PLATFORM.TIME_CHECK_RECORD) submits a drift check: the node is 3.5 s ahead of both references. */
async function monitorDriftCheck(node: string): Promise<{ raised: { kind: string; alarm_id: string }[] }> {
  const samples = [
    { source_id: npl, reachable: true, offset_s: '3.500000', uncertainty_s: '0.000800' },
    { source_id: nic, reachable: true, offset_s: '3.480000', uncertainty_s: '0.000900' },
  ];
  return withCommand(db.app, again(monitor), async (c) => {
    const { rows } = await c.query<{ r: { raised: { kind: string; alarm_id: string }[] } }>(
      'select platform.record_drift_check($1, $2::jsonb) as r',
      [node, JSON.stringify(samples)],
    );
    return rows[0]?.r ?? { raised: [] };
  });
}

/** An operator calls the time-incident hook directly, as the application role may. */
async function operatorRaises(node: string, severity: string): Promise<{ ok: true; alarmId: string } | { ok: false; code: string }> {
  try {
    const alarmId = await withCommand(db.app, again(operator), async (c) => {
      const { rows } = await c.query<{ id: string }>(
        "select platform.raise_time_incident('DRIFT_EXCEEDED', $1, $2, '{}'::jsonb) as id",
        [node, severity],
      );
      return rows[0]?.id ?? '';
    });
    return { ok: true, alarmId };
  } catch (e) {
    return { ok: false, code: codeOf(e) };
  }
}

/** The DATA_INTEGRITY / TIME_SYNC incident linked to an alarm, if any. */
async function incidentForAlarm(alarmId: string) {
  const { rows } = await db.admin.query<{ source: string; incident_type: string; initial_severity: string; detected_by: string }>(
    `select i.source, i.incident_type, i.initial_severity, i.detected_by
       from records.incident i join records.incident_link l on l.incident_id = i.id
      where l.aggregate_type = 'platform_alarm' and l.aggregate_id = $1`,
    [alarmId],
  );
  return rows;
}

beforeAll(async () => {
  db = await createTestDatabase();
  const { admin } = await seedAdministration(db); // SYSTEM_ADMINISTRATOR holds PLATFORM.TIME_SOURCE_MANAGE
  npl = await registerSource(admin, `NPL India NTP ${randomBytes(2).toString('hex')}`, 'NPL India, traceable to UTC(NPLI)');
  nic = await registerSource(admin, `NIC NTP ${randomBytes(2).toString('hex')}`, 'NIC time service, traceable to NPL India');
  monitor = await seededTestActor(db, { source: 'SYSTEM', legalName: 'F69 time monitor' });
  operator = await seededTestActor(db, { roleCode: 'OPERATOR', legalName: 'F69 Operator' });
});

afterAll(async () => {
  await db.drop();
});

describe('F69: only the time monitor raises time-fault alarms and their data-integrity incidents', () => {
  it('[DI-27][DI-17][INV-16] an operator cannot forge a time-fault incident, nor pre-empt the monitor so that a genuine drift raises nothing', async () => {
    const observed: Record<string, unknown> = {};

    // (a) Forgery: an operator raises a MINOR DRIFT_EXCEEDED incident for a node that does not exist.
    const ghost = await operatorRaises('ghost-node', 'MINOR');
    observed['ghostRaise'] = ghost.ok ? 'ACCEPTED' : ghost.code;
    const { rows: forged } = await db.admin.query<{ n: number }>(
      `select count(*)::int as n from records.incident where source = 'TIME_SYNC' and raised_by_person = $1`,
      [operator.personId],
    );
    observed['timeSyncIncidentsRaisedByOperator'] = forged[0]?.n ?? -1;
    const { rows: ghostAlarms } = await db.admin.query<{ n: number }>(
      `select count(*)::int as n from platform.alarm where subject = 'ghost-node'`,
    );
    observed['ghostNodeAlarms'] = ghostAlarms[0]?.n ?? -1;
    const { rows: faultOpen } = await db.admin.query<{ open: boolean }>('select platform.time_fault_open() as open');
    observed['timeFaultOpenAfterOperator'] = faultOpen[0]?.open ?? null;

    // (b) Suppression: the operator pre-raises a MINOR DRIFT_EXCEEDED alarm for the real node, then the
    // monitor measures a genuine 3.5 s drift on it.
    const realNode = 'db-f69-real';
    const preempt = await operatorRaises(realNode, 'MINOR');
    observed['preemptRaise'] = preempt.ok ? 'ACCEPTED' : preempt.code;
    const real = await monitorDriftCheck(realNode);
    observed['monitorRaisedOnRealNode'] = real.raised.map((r) => r.kind);
    const realAlarmId = real.raised.find((r) => r.kind === 'DRIFT_EXCEEDED')?.alarm_id;
    observed['monitorIncidentOnRealNode'] = realAlarmId ? await incidentForAlarm(realAlarmId) : [];
    const { rows: openOnReal } = await db.admin.query<{ kind: string; severity: string; raised_by_person: string }>(
      `select a.kind, a.severity, a.raised_by_person from platform.alarm a
        where a.subject = $1 and not exists (select 1 from platform.alarm_clearance c where c.alarm_id = a.id)
        order by a.recorded_at`,
      [realNode],
    );
    observed['openAlarmsOnRealNode'] = openOnReal.map((a) => ({
      kind: a.kind, severity: a.severity, raisedBy: a.raised_by_person === monitor.personId ? 'MONITOR' : a.raised_by_person === operator.personId ? 'OPERATOR' : a.raised_by_person,
    }));

    // Control: on an untouched node the same monitor check raises the MAJOR alarm and its SYSTEM incident.
    const control = await monitorDriftCheck('db-f69-control');
    expect(control.raised.map((r) => r.kind)).toEqual(['DRIFT_EXCEEDED']);
    expect(await incidentForAlarm(control.raised[0]?.alarm_id ?? '')).toEqual([
      { source: 'TIME_SYNC', incident_type: 'DATA_INTEGRITY', initial_severity: 'MAJOR', detected_by: 'SYSTEM' },
    ]);

    expect(observed).toEqual({
      ghostRaise: expect.stringMatching(/^(PERMISSION_DENIED|EBMR-(PLAT|IAM|REC)-\d+)$/),
      timeSyncIncidentsRaisedByOperator: 0,
      ghostNodeAlarms: 0,
      timeFaultOpenAfterOperator: false,
      preemptRaise: expect.stringMatching(/^(PERMISSION_DENIED|EBMR-(PLAT|IAM|REC)-\d+)$/),
      monitorRaisedOnRealNode: ['DRIFT_EXCEEDED'],
      monitorIncidentOnRealNode: [{ source: 'TIME_SYNC', incident_type: 'DATA_INTEGRITY', initial_severity: 'MAJOR', detected_by: 'SYSTEM' }],
      openAlarmsOnRealNode: [{ kind: 'DRIFT_EXCEEDED', severity: 'MAJOR', raisedBy: 'MONITOR' }],
    });
  });
});

/**
 * Review reproducer F70: a single system administrator can rewrite the least-privilege
 * permission-to-role map at runtime with iam.add_role_permission (0120:550). The function checks
 * only IAM.ROLE_MANAGE (held by SYSTEM_ADMINISTRATOR alone), takes no second approver and no
 * change-control reference, and the only catalogue guard (iam.role_permission_guard, 0120:406)
 * blocks mixing ADMINISTRATION and GMP permissions in one role. So one administrator can:
 *   - add a GMP-WRITE permission (RECORD.LEGAL_HOLD) to a kernel GMP role (OPERATOR), after which
 *     every operator places legal holds, bypassing the DI-17 map shipped in 0700; and
 *   - add a GOVERNANCE permission (PLATFORM.ALARM_CLEAR) to their own SYSTEM_ADMINISTRATOR role,
 *     granting themselves authority without a second approver (DI-18: administrators cannot grant
 *     themselves any authority; every grant of authority needs a second approver).
 *
 * Safe behaviour asserted here: after a lone administrator's call to iam.add_role_permission
 * (whether the call is refused or merely recorded as a pending request awaiting a second person),
 *   (a) an OPERATOR still cannot place a legal hold (EBMR-IAM-040 on RECORD.LEGAL_HOLD), and
 *   (b) the administrator, in the SYSTEM_ADMINISTRATOR role, still does not hold PLATFORM.ALARM_CLEAR.
 * Controls: before the edit the operator is refused and the administrator lacks the permission;
 * a QA reviewer (who holds RECORD.LEGAL_HOLD in the shipped map) places a legal hold, proving the
 * call path works when the permission is legitimately held.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { evaluateAuthority } from '../../src/identity/authority.ts';
import { placeLegalHold } from '../../src/records/retention-store.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';
import { seedAdministration, withReason, type SeedAdministration } from '../identity/seed.ts';

let db: TestDatabase;
let adm: SeedAdministration;

const again = <T extends ActorContext>(ctx: T): T => ({ ...ctx, correlationId: randomUUID() });

const codeOf = (e: unknown): string => {
  const m = e instanceof Error ? e.message : String(e);
  if (/permission denied/.test(m)) return 'PERMISSION_DENIED';
  return m.match(/EBMR-[A-Z]+-\d+/)?.[0] ?? `UNEXPECTED: ${m}`;
};

async function outcome<T>(work: () => Promise<T>): Promise<string> {
  try {
    await work();
    return 'ACCEPTED';
  } catch (e) {
    return codeOf(e);
  }
}

/** A fresh operator (seeded through the real identity flow) tries to place a legal hold on a batch. */
async function operatorPlacesHold(tag: string): Promise<string> {
  const operator = await seededTestActor(db, { roleCode: 'OPERATOR', legalName: `F70 Operator ${tag}` });
  return outcome(() => withCommand(db.app, again(operator), (c) => placeLegalHold(c, 'batch', randomUUID(), `F70 ${tag} claim`)));
}

async function adminHoldsAlarmClear(): Promise<boolean> {
  const d = await evaluateAuthority(db.app, {
    personId: adm.admin.personId,
    accountId: adm.admin.accountId,
    permission: 'PLATFORM.ALARM_CLEAR',
    roleCode: 'SYSTEM_ADMINISTRATOR',
  });
  return d.allowed;
}

beforeAll(async () => {
  db = await createTestDatabase();
  adm = await seedAdministration(db);
});

afterAll(async () => {
  await db.drop();
});

describe('F70: one administrator alone cannot rewrite the permission-to-role map', () => {
  it('[DI-18][DI-17][INV-11] a lone administrator cannot give operators a GMP permission, nor give their own role new authority', async () => {
    // Controls on the shipped map.
    const qa = await seededTestActor(db, { roleCode: 'QA_REVIEWER', legalName: 'F70 QA reviewer' });
    const qaHold = await outcome(() => withCommand(db.app, again(qa), (c) => placeLegalHold(c, 'batch', randomUUID(), 'F70 control claim')));
    expect(qaHold).toBe('ACCEPTED');
    expect(await operatorPlacesHold('before')).toBe('EBMR-IAM-040');
    expect(await adminHoldsAlarmClear()).toBe(false);

    const observed: Record<string, unknown> = {};

    // The seeded SYSTEM_ADMINISTRATOR, alone, edits the kernel GMP role OPERATOR.
    observed['adminAddsLegalHoldToOperator'] = await outcome(() =>
      withCommand(db.app, withReason(adm.admin, 'ROLE_CHANGE', 'F70 lone edit'), (c) =>
        c.query("select iam.add_role_permission('OPERATOR', 'RECORD.LEGAL_HOLD')"),
      ),
    );
    // A freshly seeded operator then tries to place a legal hold (GMP action reserved to QA).
    observed['operatorPlacesLegalHoldAfterEdit'] = await operatorPlacesHold('after');

    // The same administrator, alone, extends their own role with a GOVERNANCE permission.
    observed['adminAddsAlarmClearToOwnRole'] = await outcome(() =>
      withCommand(db.app, withReason(adm.admin, 'ROLE_CHANGE', 'F70 self edit'), (c) =>
        c.query("select iam.add_role_permission('SYSTEM_ADMINISTRATOR', 'PLATFORM.ALARM_CLEAR')"),
      ),
    );
    observed['adminHoldsAlarmClearAfterSelfEdit'] = await adminHoldsAlarmClear();

    // Evidence: the live catalogue rows the lone administrator's commands left behind.
    const { rows } = await db.admin.query<{ role_code: string; permission_code: string }>(
      `select role_code, permission_code from iam.role_permission
        where removed_at is null
          and ((role_code = 'OPERATOR' and permission_code = 'RECORD.LEGAL_HOLD')
            or (role_code = 'SYSTEM_ADMINISTRATOR' and permission_code = 'PLATFORM.ALARM_CLEAR'))
        order by role_code`,
    );
    observed['liveCatalogueRowsAddedByLoneAdmin'] = rows.map((r) => `${r.role_code}:${r.permission_code}`);

    // Safe behaviour: whatever the administrator's call returns, the edits do not take effect
    // without a second approver (or are refused outright).
    expect({
      operatorPlacesLegalHoldAfterEdit: observed['operatorPlacesLegalHoldAfterEdit'],
      adminHoldsAlarmClearAfterSelfEdit: observed['adminHoldsAlarmClearAfterSelfEdit'],
      liveCatalogueRowsAddedByLoneAdmin: observed['liveCatalogueRowsAddedByLoneAdmin'],
      _context: observed,
    }).toEqual({
      operatorPlacesLegalHoldAfterEdit: 'EBMR-IAM-040',
      adminHoldsAlarmClearAfterSelfEdit: false,
      liveCatalogueRowsAddedByLoneAdmin: [],
      _context: observed,
    });
  });
});

/**
 * Review reproducer F71: continuity.reserve_counter_ceiling (packages/kernel/sql/0600_continuity_core.sql:358)
 * checks CONTINUITY.COUNTER_RESERVE in iam.actor_location_scope() (the session's site/room), not in the
 * scope of the counter being reserved. A batch-number counter 'site.batch_number:<rule>' belongs to a
 * named site's numbering rule, so a BATCH_ISSUER whose grant covers only SITE-1 (session at SITE-1)
 * passes the check for a counter of a SITE-2 rule and can write a ceiling reservation with a fabricated
 * external floor and receipt into SITE-2's number-protection records.
 *
 * Scenario:
 *   1. a MASTER_DATA_STEWARD defines a PROCESSING numbering rule for SITE-2 (counter site.batch_number:<rule>);
 *   2. an unrestricted BATCH_ISSUER reserves the first block (floor 0, ceiling 50): positive control that
 *      the call is well formed and the counter is reservable by someone whose grant covers SITE-2;
 *   3. a BATCH_ISSUER whose grant is limited to SITE-1 (session at SITE-1) calls
 *      reserve_counter_ceiling(<key>, 9999, 10000, 'forged receipt').
 *
 * Safe behaviour asserted: step 3 is refused for lack of CONTINUITY.COUNTER_RESERVE (no grant covers
 * SITE-2), and SITE-2's counter, ceiling reservations, sequence bumps and LEDGER_AHEAD alarms are unchanged.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { seedActor } from '../identity/seed.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';

const OTHER_SITE = 'SITE-2';
const RULE = `F71-${randomUUID().slice(0, 8).toUpperCase()}`;
const KEY = `site.batch_number:${RULE}`;

let db: TestDatabase;
let steward: ActorContext;
let issuer: ActorContext;
let site1Issuer: ActorContext;

const again = (ctx: ActorContext): ActorContext => ({ ...ctx, correlationId: randomUUID() });

async function reserve(ctx: ActorContext, floor: number, ceiling: number, receipt: string): Promise<string> {
  return withCommand(db.app, again(ctx), async (c) => {
    const { rows } = await c.query<{ ceiling: string }>(
      'select continuity.reserve_counter_ceiling($1, $2, $3, $4)::text as ceiling',
      [KEY, floor, ceiling, receipt],
    );
    const r = rows[0];
    if (!r) throw new Error('no row');
    return r.ceiling;
  });
}

async function snapshot(): Promise<Record<string, unknown>> {
  const counter = await db.app.query(
    'select last_value::text, reserved_ceiling::text from continuity.counter where sequence_key = $1',
    [KEY],
  );
  const reservations = await db.app.query(
    'select previous_ceiling::text, new_ceiling::text, external_floor::text, ledger_receipt from continuity.ceiling_reservation where sequence_key = $1 order by new_ceiling',
    [KEY],
  );
  const bumps = await db.app.query(
    'select reason, value_before::text, value_after::text from continuity.sequence_bump where sequence_key = $1',
    [KEY],
  );
  const alarms = await db.app.query(
    "select alarm_code from continuity.open_alarm where alarm_code = 'LEDGER_AHEAD' and details ->> 'sequence_key' = $1",
    [KEY],
  );
  return { counter: counter.rows, reservations: reservations.rows, bumps: bumps.rows, alarms: alarms.rows };
}

beforeAll(async () => {
  db = await createTestDatabase();
  steward = await seededTestActor(db, { roleCode: 'MASTER_DATA_STEWARD' });
  issuer = await seededTestActor(db, { roleCode: 'BATCH_ISSUER' });
  // Grant limited to SITE-1; the seeded devices (and therefore the session) are at SITE-1.
  const { seed: _seed, ...ctx } = await seedActor(db, { roleCode: 'BATCH_ISSUER', scope: { site: 'SITE-1' }, acknowledgeEsig: false });
  void _seed;
  site1Issuer = ctx;
  await withCommand(db.app, again(steward), (c) =>
    c.query('select site.define_batch_number_rule($1::jsonb)', [
      JSON.stringify({
        rule_code: RULE,
        site_code: OTHER_SITE,
        batch_kind: 'PROCESSING',
        format: 'S2{YY}{SEQ:4}',
        site_zone: 'Asia/Kolkata',
        effective_from: null,
        reason: 'SOP-QA-017',
        block_size: 50,
      }),
    ]),
  );
});

afterAll(async () => {
  await db.drop();
});

describe('F71 counter ceiling reservation is authorised at the actor location, not the counter site', () => {
  it('[DI-17][INV-27] a BATCH_ISSUER limited to SITE-1 cannot reserve a ceiling on a SITE-2 batch-number counter', async () => {
    // The counter belongs to the SITE-2 rule.
    const rule = await db.app.query<{ site_code: string; counter_key: string }>(
      'select site_code, counter_key from site.batch_number_rule where rule_code = $1',
      [RULE],
    );
    expect(rule.rows).toEqual([{ site_code: OTHER_SITE, counter_key: KEY }]);

    // Positive control: an issuer whose grant covers SITE-2 (unrestricted) reserves the first block.
    expect(await reserve(issuer, 0, 50, 'ledger-receipt-1')).toBe('50');
    const before = await snapshot();
    expect(before).toEqual({
      counter: [{ last_value: '0', reserved_ceiling: '50' }],
      reservations: [{ previous_ceiling: '0', new_ceiling: '50', external_floor: '0', ledger_receipt: 'ledger-receipt-1' }],
      bumps: [],
      alarms: [],
    });

    // Sanity: the SITE-1-limited issuer's grant does not cover SITE-2 (the owning module refuses it a
    // SITE-2 allocation, which is checked in the rule's site scope).
    await expect(
      withCommand(db.app, again(site1Issuer), (c) =>
        c.query('select * from site.allocate_batch_number($1::jsonb)', [
          JSON.stringify({
            site_code: OTHER_SITE,
            product_code: 'PY',
            product_name: 'Product PY',
            edition: 'TABLETS',
            batch_kind: 'PROCESSING',
            batch_size: '1000',
            batch_size_unit: '{tbl}',
          }),
        ]),
      ),
    ).rejects.toThrow(/EBMR-IAM-040 .*BATCH_NUMBER\.ALLOCATE/);
    expect(await snapshot()).toEqual(before);

    // The SITE-1-limited issuer tries to write a forged reservation into SITE-2's counter.
    let outcome: string;
    try {
      outcome = `ALLOWED: returned ${await reserve(site1Issuer, 9999, 10000, 'forged receipt')}`;
    } catch (error) {
      outcome = String((error as Error).message);
    }
    const after = await snapshot();

    expect({ outcome, stateUnchanged: after }).toEqual({
      outcome: expect.stringMatching(/EBMR-IAM-040 .*CONTINUITY\.COUNTER_RESERVE/),
      stateUnchanged: before,
    });
  });
});

/**
 * Review reproducer F72: a denied platform permission (EBMR-PLAT-006) leaves no stored authority
 * evaluation, so the failed check is not logged (DI-17, DI-19, INV-26).
 *
 * iam.platform_authority (packages/kernel/sql/0710_authorization_scope_and_platform.sql) stores the
 * evaluation with iam.evaluate_authority inside the command; platform.authorize (0500) then raises
 * EBMR-PLAT-006 and the whole command, including the stored evaluation, rolls back. withGuardedCommand
 * (packages/kernel/src/identity/authority.ts) re-logs only EBMR-IAM-040 / EBMR-IAM-041 refusals outside
 * the rolled-back transaction, not EBMR-PLAT-006.
 *
 * Scenario:
 *   1. control: an OPERATOR attempts records.place_legal_hold through withGuardedCommand; it is refused
 *      with EBMR-IAM-040 and a denied evaluation of RECORD.LEGAL_HOLD is stored for that person
 *      (the documented "a failed check blocks the action and is logged" path works);
 *   2. the same kind of OPERATOR attempts platform.set_setting('time.drift_alarm_threshold_s', '5')
 *      (with a reason, so the refusal comes from the authority check) through withGuardedCommand;
 *   3. and platform.register_time_source(...) through withGuardedCommand.
 *
 * Safe behaviour asserted: steps 2 and 3 are refused with EBMR-PLAT-006 AND each refusal is logged:
 * iam.authority_evaluation holds at least one row, all denied, for PLATFORM.SETTINGS_CHANGE and
 * PLATFORM.TIME_SOURCE_MANAGE for that person. The setting itself is unchanged.
 */
import { randomBytes, randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type { ActorContext } from '../../src/db/command.ts';
import { withGuardedCommand } from '../../src/identity/authority.ts';
import { placeLegalHold } from '../../src/records/retention-store.ts';
import { seedActor, seedAdministration, withReason } from '../identity/seed.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';

let db: TestDatabase;
beforeAll(async () => {
  db = await createTestDatabase();
  await seedAdministration(db);
});
afterAll(async () => {
  await db.drop();
});

const again = <T extends ActorContext>(ctx: T): T => ({ ...ctx, correlationId: randomUUID() });

async function evaluations(personId: string, permission: string): Promise<{ allowed: boolean }[]> {
  const { rows } = await db.app.query<{ allowed: boolean }>(
    'select allowed from iam.authority_evaluation where person_id = $1 and permission_code = $2',
    [personId, permission],
  );
  return rows;
}

describe('F72: a refused platform permission (EBMR-PLAT-006) is logged like any failed authority check', () => {
  it('[DI-17][INV-26] an operator refused a setting change or a time-source registration leaves a stored denied evaluation', async () => {
    // 1. Control: an iam.require_permission refusal (EBMR-IAM-040) is re-logged by withGuardedCommand.
    const control = await seedActor(db, { roleCode: 'OPERATOR', acknowledgeEsig: false });
    await expect(
      withGuardedCommand(db.app, again(control), (c) => placeLegalHold(c, 'batch', randomUUID(), 'claim')),
    ).rejects.toThrow(/EBMR-IAM-040 .*RECORD\.LEGAL_HOLD/);
    const holdLog = await evaluations(control.personId, 'RECORD.LEGAL_HOLD');
    expect(holdLog.length).toBeGreaterThanOrEqual(1);
    expect(holdLog.every((r) => !r.allowed)).toBe(true);

    const operator = await seedActor(db, { roleCode: 'OPERATOR', acknowledgeEsig: false });
    const before = (await db.app.query<{ v: string }>("select platform.setting_text('time.drift_alarm_threshold_s') as v")).rows[0]?.v;

    // 2. Weakening the drift-alarm threshold is refused by the platform authority check ...
    await expect(
      withGuardedCommand(db.app, withReason(operator, 'CHANGE_CONTROL', 'CC-F72'), (c) =>
        c.query("select platform.set_setting('time.drift_alarm_threshold_s', '5')"),
      ),
    ).rejects.toThrow(/EBMR-PLAT-006 permission platform\.settings\.change denied: .*PLATFORM\.SETTINGS_CHANGE/);
    const after = (await db.app.query<{ v: string }>("select platform.setting_text('time.drift_alarm_threshold_s') as v")).rows[0]?.v;
    expect(after).toBe(before);

    // 3. ... and so is registering a time source.
    await expect(
      withGuardedCommand(db.app, again(operator), (c) =>
        c.query("select platform.register_time_source($1, 'NTP', 'ntp.example', 'NPL India', gen_random_uuid(), 'VAL-TS-F72')", [
          `F72 ${randomBytes(3).toString('hex')}`,
        ]),
      ),
    ).rejects.toThrow(/EBMR-PLAT-006 .*PLATFORM\.TIME_SOURCE_MANAGE/);

    // Each failed check must be logged (DI-17 "a failed check blocks the action and is logged"; INV-26).
    const settingLog = await evaluations(operator.personId, 'PLATFORM.SETTINGS_CHANGE');
    const timeSourceLog = await evaluations(operator.personId, 'PLATFORM.TIME_SOURCE_MANAGE');
    expect({ settingsChange: settingLog.length >= 1, timeSourceManage: timeSourceLog.length >= 1 }).toEqual({
      settingsChange: true,
      timeSourceManage: true,
    });
    expect([...settingLog, ...timeSourceLog].every((r) => !r.allowed)).toBe(true);
  });
});

/**
 * Review reproducer F73: approval e-signature independence depends on signing order.
 *
 * esig.check_independence (kernel 0230, the only definition) builds the excluded set from the
 * signers who ALREADY hold the independent_of meanings at signing time:
 *   APPROVED.independent_of = {PREPARED, CHECKED}, CHECKED.independent_of = {PREPARED} (0210).
 * Nothing makes the exclusion symmetric (a CHECKED signer is never excluded by an existing APPROVED
 * signature) and nothing binds a signature to the lifecycle state it was taken in: esig.sign checks
 * the record state only against the caller-supplied p_expected_state, the content hash excludes the
 * state (0200 canonical_envelope), and platform.transition (0550) accepts any valid signature of
 * the transition's meaning on the record (esig.platform_signature_check -> signature_problem).
 *
 * INV-04 (outline 5.3): "author, checker and approver are distinct persons (checker = approver only
 * if S4 allows)"; S4 defaults to NO and no S4 switch exists in Phase 1. DI-17: "the MBR author,
 * checker and QU approver are three different users". Outline 5.2: SUBMITTED -> CHECKED needs
 * Sig(CHECKED); CHECKED -> APPROVED needs Sig(APPROVED) "not the checker unless S4 allows".
 *
 * Case J (INV-04, one person as checker AND approver):
 *   controls: in signing order the dual-role person who checked is refused APPROVED (EBMR-ESIG-043,
 *   which also proves the person passes the authority check as QA_MBR_APPROVER); a distinct
 *   approver's APPROVED signature approves the record (the APPROVE path works);
 *   attack on a fresh record: the dual-role person signs APPROVED while the record is in DRAFT
 *   (nothing to exclude yet), the author submits, the same person signs CHECKED (excludes only
 *   PREPARED signers) and fires CHECK, and a QA reviewer fires APPROVE citing that APPROVED signature.
 *   Safe behaviour asserted: some step is refused, the record is not APPROVED and the person does not
 *   hold valid CHECKED and APPROVED signatures on the same record.
 *
 * Case G (a pre-state signature authorises a later transition):
 *   a distinct QA approver signs APPROVED while the record is in DRAFT (before submission and before
 *   any independent check); after SUBMIT and a CHECK by a distinct checker, APPROVE is fired citing
 *   that early signature. Safe behaviour asserted: the early signature is refused (at signing or at
 *   the transition); a positive control shows an APPROVED signature taken in CHECKED is accepted.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand } from '../../src/db/command.ts';
import { decideRoleGrant, requestRoleGrant } from '../../src/identity/admin.ts';
import { ebmrCode } from '../../src/identity/errors.ts';
import { createAggregateState, getAggregateState, transition, type TransitionResult } from '../../src/state/engine.ts';
import { ensureSealKey, expectRefused, run, signStub, testActor } from '../esig/helpers.ts';
import { seedAdministration, withReason, type SeededActor } from '../identity/seed.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
});

afterAll(async () => {
  await db.drop();
});

/** A second role on the person's account (requested by the administrator, approved by the process owner). */
async function grantRole(actor: SeededActor, roleCode: string): Promise<void> {
  const { admin, owner } = await seedAdministration(db);
  const grantId = await withCommand(db.app, withReason(admin), (c) =>
    requestRoleGrant(c, { accountId: actor.accountId, roleCode, reason: 'second duty for review test' }),
  );
  await withCommand(db.app, withReason(owner), (c) => decideRoleGrant(c, grantId, true, 'approved for review test'));
}

const as = (actor: SeededActor, roleCode: string): SeededActor => ({ ...actor, roleCode });

async function newRecord(author: SeededActor): Promise<string> {
  return run(db, author, async (c) => {
    const { rows } = await c.query<{ id: string }>("insert into platform.stub_record (title, body) values ('Cleaning SOP', 'Version 1 text') returning id");
    const id = rows[0]?.id ?? '';
    await createAggregateState(c, 'sample_record', { aggregateType: 'sample_record', aggregateId: id });
    return id;
  });
}

const fire = (actor: SeededActor, id: string, event: string, expectedVersion: number, signatureId?: string): Promise<TransitionResult> =>
  run(db, actor, (c) =>
    transition(c, {
      machine: 'sample_record', aggregateType: 'sample_record', aggregateId: id, event, expectedVersion,
      ...(signatureId ? { payload: { signature_id: signatureId } } : {}),
    }),
  );

/** Full real signing flow (challenge, signer authentication through ebmr_authn, sign, seal) on a sample record. */
const signOn = async (signer: SeededActor, id: string, meaning: string, expectedState: string): Promise<string> =>
  (await signStub(db, signer, id, { meaning, aggregateType: 'sample_record', expectedState })).signatureId;

type Outcome<T> = { ok: true; value: T } | { ok: false; code: string; message: string };

/** A database refusal (EBMR code) is an outcome; anything else is a test mistake and is rethrown. */
async function outcome<T>(p: Promise<T>): Promise<Outcome<T>> {
  try {
    return { ok: true, value: await p };
  } catch (error) {
    const code = ebmrCode(error);
    if (!code) throw error;
    return { ok: false, code, message: error instanceof Error ? error.message : String(error) };
  }
}

async function stateOf(id: string): Promise<string | undefined> {
  return (await getAggregateState(db.app, { aggregateType: 'sample_record', aggregateId: id }))?.state;
}

async function validMeaningsOf(id: string, personId: string): Promise<string[]> {
  const { rows } = await db.admin.query<{ meaning_code: string }>(
    "select meaning_code from esig.record_signatures('sample_record', $1) where signer_person = $2 and valid order by meaning_code",
    [id, personId],
  );
  return rows.map((r) => r.meaning_code);
}

describe('F73: approval independence must not depend on signing order', () => {
  it('[INV-04][DI-17] J: a person who signed APPROVED first can still sign CHECKED, and the engine approves on both signatures', async () => {
    const author = await testActor(db, { roleCode: 'MBR_AUTHOR', legalName: 'A. Author' });
    const dual = await testActor(db, { roleCode: 'MBR_CHECKER', legalName: 'D. Checker-and-Approver' });
    await grantRole(dual, 'QA_MBR_APPROVER');
    const approver = await testActor(db, { roleCode: 'QA_MBR_APPROVER', legalName: 'P. Approver' });
    const qaReviewer = await testActor(db, { roleCode: 'QA_REVIEWER', legalName: 'Q. Reviewer' });

    // Control 1: in signing order the rule holds (and the dual person passes the authority check as
    // QA_MBR_APPROVER, since EBMR-ESIG-040 is evaluated before independence).
    const inOrder = await newRecord(author);
    await fire(author, inOrder, 'SUBMIT', 1);
    const checkedInOrder = await signOn(dual, inOrder, 'CHECKED', 'SUBMITTED');
    await fire(dual, inOrder, 'CHECK', 2, checkedInOrder);
    await expectRefused(signOn(as(dual, 'QA_MBR_APPROVER'), inOrder, 'APPROVED', 'CHECKED'), 'EBMR-ESIG-043');
    // Control 2: the APPROVE path works with a distinct approver.
    const approvedInOrder = await signOn(approver, inOrder, 'APPROVED', 'CHECKED');
    expect(await fire(qaReviewer, inOrder, 'APPROVE', 3, approvedInOrder)).toMatchObject({ from: 'CHECKED', to: 'APPROVED' });

    // Attack: the same two duties in reverse signing order on a fresh record.
    const id = await newRecord(author);
    let refused: { step: string; code: string; message: string } | undefined;
    const step = async <T>(name: string, work: () => Promise<T>): Promise<T | undefined> => {
      if (refused) return undefined;
      const r = await outcome(work());
      if (r.ok) return r.value;
      refused = { step: name, code: r.code, message: r.message };
      return undefined;
    };
    const approvedEarly = await step('dual signs APPROVED in DRAFT', () => signOn(as(dual, 'QA_MBR_APPROVER'), id, 'APPROVED', 'DRAFT'));
    await fire(author, id, 'SUBMIT', 1);
    const checked = await step('dual signs CHECKED in SUBMITTED', () => signOn(dual, id, 'CHECKED', 'SUBMITTED'));
    await step('CHECK with the dual person\'s CHECKED signature', () => fire(dual, id, 'CHECK', 2, checked));
    await step('APPROVE with the dual person\'s APPROVED signature', () => fire(qaReviewer, id, 'APPROVE', 3, approvedEarly));

    const held = await validMeaningsOf(id, dual.personId);
    const state = await stateOf(id);
    expect.soft(held, `INV-04: one person holds valid CHECKED and APPROVED signatures on sample_record:${id}`).not.toEqual(['APPROVED', 'CHECKED']);
    expect.soft(state, 'INV-04: the record was approved on a CHECKED and an APPROVED signature of the same person').not.toBe('APPROVED');
    expect.soft(refused, 'no step of the reverse-order sequence was refused').toBeDefined();
  });

  it('[INV-04][DI-37] G: an APPROVED signature captured in DRAFT (before the independent check) authorises the later APPROVE', async () => {
    const author = await testActor(db, { roleCode: 'MBR_AUTHOR', legalName: 'A. Author' });
    const checker = await testActor(db, { roleCode: 'MBR_CHECKER', legalName: 'C. Checker' });
    const earlyApprover = await testActor(db, { roleCode: 'QA_MBR_APPROVER', legalName: 'E. Early Approver' });
    const approver = await testActor(db, { roleCode: 'QA_MBR_APPROVER', legalName: 'P. Approver' });
    const qaReviewer = await testActor(db, { roleCode: 'QA_REVIEWER', legalName: 'Q. Reviewer' });

    const id = await newRecord(author);
    const early = await outcome(signOn(earlyApprover, id, 'APPROVED', 'DRAFT'));
    await fire(author, id, 'SUBMIT', 1);
    const checked = await signOn(checker, id, 'CHECKED', 'SUBMITTED');
    await fire(checker, id, 'CHECK', 2, checked);
    expect(await stateOf(id)).toBe('CHECKED');

    if (early.ok) {
      const approve = await outcome(fire(qaReviewer, id, 'APPROVE', 3, early.value));
      expect(approve.ok, 'APPROVE accepted an APPROVED signature captured while the record was in DRAFT, before it was checked').toBe(false);
    }
    // Positive control: an APPROVED signature taken in CHECKED approves the record.
    const approvedInState = await signOn(approver, id, 'APPROVED', 'CHECKED');
    expect(await fire(qaReviewer, id, 'APPROVE', 3, approvedInState)).toMatchObject({ from: 'CHECKED', to: 'APPROVED' });
  });
});

/**
 * Review reproducer F74: a co-signature must not leave the co-signer's validated actor context
 * installable by the application for the rest of the transaction (attribution forgery).
 *
 * esig.sign (0230, co-signature branch) installs the co-signer's context with
 * iam.set_internal_actor (kernel.command_marker + iam.command_log row for that context's hash) and
 * afterwards only restores ebmr.ctx with kernel.set_actor_context(v_actor). If the co-signer's marker
 * survives, ebmr_app can put the co-signer's context back with set_config('ebmr.ctx', ...) and every
 * later statement of the transaction is attributed to the co-signer: audited updates of the signed
 * entry (esig.content_change then names the co-signer as a person who changed the record, INV-03),
 * permission-gated functions (records.raise_incident evaluated with the co-signer's grants), without
 * any fresh authentication of the co-signer (INV-40) and without kernel.begin_command (INV-07).
 *
 * Scenario (the finding's): an operator on a SHARED kiosk runs one command with a correction reason;
 * a VERIFIER co-signs VERIFIED at that kiosk in that command; the application then re-installs the
 * verifier's context, corrects the signed entry and raises an incident, and commits.
 *
 * Control: the very same set_config overlay issued BEFORE esig.sign is not a validated actor, so the
 * only thing that can make it validated afterwards is what esig.sign left behind.
 *
 * Safe behaviour asserted: after the co-signature the re-installed verifier context is not validated
 * (iam.actor_is_validated() false, kernel.current_actor() NULL), the audited update and the incident
 * are refused (EBMR-AUDIT-* / EBMR-IAM-*), and nothing committed names the verifier as actor of the
 * update, as a person who changed the entry, or as the raiser of an incident.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type pg from 'pg';
import { toDbContext } from '../../src/db/command.ts';
import { sign } from '../../src/esig/signing.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { challengeFor, cmd, createStub, ensureSealKey, signatureAuth, signStub, testActor, testSealKey } from '../esig/helpers.ts';

let db: TestDatabase;

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
});

afterAll(async () => {
  await db.drop();
});

const codeOf = (e: unknown): string => {
  const m = e instanceof Error ? e.message : String(e);
  return m.match(/EBMR-[A-Z]+-\d+/)?.[0] ?? `UNEXPECTED: ${m}`;
};

async function attempt<T>(c: pg.PoolClient, name: string, work: () => Promise<T>): Promise<{ ok: true; value: T } | { ok: false; code: string }> {
  await c.query(`savepoint ${name}`);
  try {
    const value = await work();
    await c.query(`release savepoint ${name}`);
    return { ok: true, value };
  } catch (e) {
    await c.query(`rollback to savepoint ${name}`);
    return { ok: false, code: codeOf(e) };
  }
}

const OVERLAY_SQL = "select set_config('ebmr.ctx', (current_setting('ebmr.ctx')::jsonb || $1::jsonb)::text, true)";

describe('F74: the co-signer context is not installable by the application after esig.sign', () => {
  it('[INV-40][INV-07][INV-03][DI-14][DI-22][DI-35] after a co-signature, re-installing the verifier context with set_config attributes no update, content change or incident to the verifier', async () => {
    const performer = await testActor(db, { deviceClass: 'SHARED', withPin: true, legalName: 'F74 Kiosk Operator' });
    const verifier = await testActor(db, { roleCode: 'VERIFIER', deviceClass: 'SHARED', withPin: true, legalName: 'F74 Kiosk Verifier' });
    const stubId = await createStub(db, performer, { value: '12.503' });
    await signStub(db, performer, stubId, { meaning: 'PERFORMED', method: 'BADGE_PIN' });

    // The verifier co-signs VERIFIED at the operator's kiosk (own badge + PIN, SIGNATURE event).
    const ch = await challengeFor(db, performer, stubId, { meaning: 'VERIFIED', signer: verifier });
    expect(ch.cosignature).toBe(true);
    const verifierEvent = await signatureAuth(db, verifier, performer, ch.challengeId, 'BADGE_PIN');
    // The operator's command: fresh badge tap (INV-40) and a correction reason (DI-24).
    const operatorCtx = await cmd(db, performer, { reasonCode: 'ENTRY_ERROR', reasonText: 'transcription error corrected' });

    const observed: Record<string, unknown> = {};
    let forgedIncidentId: string | null = null;
    const c = await db.app.connect();
    try {
      await c.query('begin');
      await c.query('select kernel.begin_command($1::jsonb)', [JSON.stringify(toDbContext(operatorCtx))]);
      const operatorRaw = (await c.query<{ s: string }>("select current_setting('ebmr.ctx') as s")).rows[0]?.s ?? '';

      // Control: before the co-signature, the verifier overlay is NOT a validated actor.
      const plannedOverlay = {
        person_id: verifier.personId, account_id: verifier.accountId, role_code: 'VERIFIER', auth_event_id: verifierEvent, legal_name: 'F74 Kiosk Verifier',
      };
      await c.query(OVERLAY_SQL, [JSON.stringify(plannedOverlay)]);
      const pre = await c.query<{ ok: boolean; p: string | null }>("select iam.actor_is_validated() as ok, kernel.current_actor() ->> 'person_id' as p");
      expect(pre.rows[0]).toEqual({ ok: false, p: null });
      // Back to the operator's own (validated) context.
      await c.query("select set_config('ebmr.ctx', $1, true)", [operatorRaw]);
      const restored = await c.query<{ p: string }>("select iam.assert_validated_actor() ->> 'person_id' as p");
      expect(restored.rows[0]?.p).toBe(performer.personId);

      // The co-signature itself (esig.sign + esig.seal_signature) in the operator's command.
      const sig = await sign(c, { challengeId: ch.challengeId, authEventId: verifierEvent, expectedState: 'OPEN' }, testSealKey);
      expect(sig.cosignature).toBe(true);
      const back = await c.query<{ p: string }>("select iam.assert_validated_actor() ->> 'person_id' as p");
      expect(back.rows[0]?.p).toBe(performer.personId);

      // Everything needed is readable by ebmr_app from the signature row it just wrote.
      const { rows: sigRows } = await c.query<{ person_id: string; account_id: string; role_code: string; auth_event_id: string; legal_name: string }>(
        `select signer_person::text as person_id, signer_account::text as account_id, signer_role_code as role_code,
                auth_event_id::text as auth_event_id, signer_legal_name as legal_name
           from esig.signature where id = $1`, [sig.signatureId]);
      const overlay = sigRows[0];
      // Same values as the control overlay: the only difference is that esig.sign has run.
      expect(overlay).toEqual(plannedOverlay);

      // The application re-installs the verifier's context with set_config (no kernel code involved).
      await c.query(OVERLAY_SQL, [JSON.stringify(overlay)]);

      // 1. Not a validated actor.
      const v = await c.query<{ ok: boolean; p: string | null }>("select iam.actor_is_validated() as ok, kernel.current_actor() ->> 'person_id' as p");
      observed['actorIsValidated'] = v.rows[0]?.ok ?? null;
      const p = v.rows[0]?.p ?? null;
      observed['currentActorPerson'] = p === verifier.personId ? 'VERIFIER (co-signer)' : p === performer.personId ? 'OPERATOR' : p;

      // 2. An audited correction of the signed entry under it must be refused.
      const upd = await attempt(c, 'forged_update', () => c.query("update esig.stub_signable set value = '13.000' where id = $1", [stubId]));
      observed['forgedUpdate'] = upd.ok ? 'ACCEPTED' : upd.code;

      // 3. A permission-gated function under it must be refused.
      const inc = await attempt(c, 'forged_incident', () =>
        c.query<{ id: string }>("select records.raise_incident('OTHER', 'FORGED', 'MINOR', 'F74 forged incident', '', '[]'::jsonb)::text as id"));
      if (inc.ok) {
        forgedIncidentId = inc.value.rows[0]?.id ?? null;
        observed['forgedIncident'] = 'ACCEPTED';
      } else {
        observed['forgedIncident'] = inc.code;
      }

      await c.query('commit');
    } catch (e) {
      await c.query('rollback');
      throw e;
    } finally {
      c.release();
    }

    // What was committed in the verifier's name (nothing, if the guarantee holds).
    const { rows: updAudit } = await db.admin.query<{ n: string }>(
      `select count(*)::text as n from kernel.audit_event
        where table_name = 'esig.stub_signable' and record_id = $1 and action = 'UPDATE'
          and payload -> 'actor' ->> 'person_id' = $2`, [stubId, verifier.personId]);
    observed['committedUpdateAuditedAsVerifier'] = Number(updAudit[0]?.n ?? '0');
    const { rows: changes } = await db.admin.query<{ n: string }>(
      "select count(*)::text as n from esig.content_change where aggregate_ref = $1 and person_id = $2", [`esig_stub:${stubId}`, verifier.personId]);
    observed['committedContentChangesByVerifier'] = Number(changes[0]?.n ?? '0');
    const { rows: incidents } = await db.admin.query<{ n: string }>(
