/**
 * Review reproducer F77: kernel.audit_row_change (packages/kernel/sql/0010_audit_trail.sql, the only
 * definition) computes the chain key from the NEW row for an UPDATE:
 *
 *   v_row := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
 *   v_key := v_reg.aggregate_type || ':' || coalesce(v_row ->> v_reg.aggregate_column, '?');
 *
 * so an UPDATE that changes the aggregate column of a registered table (moves the row from aggregate
 * A to aggregate B) is appended to chain B only. Chain A keeps the row's INSERT and never shows the
 * row leaving, so a per-aggregate audit-trail review of A (outline 5.4) still shows the row as A's.
 *
 * Scenario (market.stub_pack is registered with aggregate market_stub_batch / batch_id, 0310:287;
 * ebmr_app holds UPDATE on it, MASTERDATA.CHANGE via MASTER_DATA_STEWARD):
 *   1. MASTER_DATA_STEWARD inserts product P, batches B1 and B2 (both {IN}) and pack PK1 on B1.
 *   2. With a reason, MASTER_DATA_STEWARD runs update market.stub_pack set batch_id = B2 where id = PK1.
 *
 * Sanity checks (so a failure cannot come from a test mistake): the update really moved the row, the
 * INSERT of PK1 is in chain market_stub_batch:B1, and the UPDATE (old batch_id B1 -> new B2) is in
 * chain market_stub_batch:B2.
 *
 * Safe behaviour asserted (DI-22 / DI-25 / INV-07): B1's chain also records the change of PK1 (an event
 * for market.stub_pack / PK1 after its INSERT), so reviewing B1's trail shows the pack left B1.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';

let db: TestDatabase;
beforeAll(async () => {
  db = await createTestDatabase();
});
afterAll(async () => {
  await db.drop();
});

interface AuditRow {
  seq: string;
  action: string;
  table_name: string | null;
  record_id: string | null;
  payload: { body?: { old?: Record<string, unknown>; new?: Record<string, unknown> } };
}

async function chainEventsFor(chainKey: string, table: string, recordId: string): Promise<AuditRow[]> {
  const { rows } = await db.admin.query<AuditRow>(
    `select seq::text as seq, action, table_name, record_id, payload
       from kernel.audit_event
      where chain_key = $1 and table_name = $2 and record_id = $3
      order by seq`,
    [chainKey, table, recordId],
  );
  return rows;
}

describe('F77: moving a row to another aggregate must be visible in the old aggregate\'s audit chain', () => {
  it('[DI-22][DI-25][INV-07] update market.stub_pack set batch_id = B2 is recorded in chain market_stub_batch:B1 as well as B2', async () => {
    const tag = randomUUID().slice(0, 8);
    const steward = await seededTestActor(db, { roleCode: 'MASTER_DATA_STEWARD' });

    // 1. Setup: product, batches B1 and B2, pack PK1 on B1.
    const { b1, b2, pk1 } = await withCommand(db.app, { ...steward, correlationId: randomUUID() }, async (c) => {
      const one = async (sql: string, params: unknown[]): Promise<string> => {
        const { rows } = await c.query<{ id: string }>(sql, params);
        const id = rows[0]?.id;
        if (!id) throw new Error(`no id returned by ${sql}`);
        return id;
      };
      const product = await one('insert into market.stub_product (code, edition, markets) values ($1, $2, $3) returning id', [`F77-P-${tag}`, 'tablets', ['IN']]);
      const batch1 = await one('insert into market.stub_batch (batch_number, product_id, markets) values ($1, $2, $3) returning id', [`F77-B1-${tag}`, product, ['IN']]);
      const batch2 = await one('insert into market.stub_batch (batch_number, product_id, markets) values ($1, $2, $3) returning id', [`F77-B2-${tag}`, product, ['IN']]);
      const pack = await one('insert into market.stub_pack (code, batch_id, destination) values ($1, $2, $3) returning id', [`F77-PK1-${tag}`, batch1, 'IN']);
      return { b1: batch1, b2: batch2, pk1: pack };
    });

    // 2. Move the pack from B1 to B2, with a reason (as the application role, inside a command).
    await withCommand(
      db.app,
      { ...steward, correlationId: randomUUID(), reasonCode: 'DATA_CORRECTION', reasonText: 'pack assigned to the wrong batch' },
      (c) => c.query('update market.stub_pack set batch_id = $1 where id = $2', [b2, pk1]),
    );

    // Sanity: the row really moved.
    const { rows: now } = await db.admin.query<{ batch_id: string }>('select batch_id from market.stub_pack where id = $1', [pk1]);
    expect(now[0]?.batch_id).toBe(b2);

    const chainA = `market_stub_batch:${b1}`;
    const chainB = `market_stub_batch:${b2}`;
    const inA = await chainEventsFor(chainA, 'market.stub_pack', pk1);
    const inB = await chainEventsFor(chainB, 'market.stub_pack', pk1);

    // Sanity: the INSERT of PK1 is in B1's chain, the UPDATE (B1 -> B2) is in B2's chain.
    expect(inA[0]?.action).toBe('INSERT');
    const updB = inB.filter((e) => e.action === 'UPDATE');
    expect(updB).toHaveLength(1);
    expect(updB[0]?.payload.body?.old?.['batch_id']).toBe(b1);
    expect(updB[0]?.payload.body?.new?.['batch_id']).toBe(b2);

    // Safe behaviour: B1's own trail records that PK1 changed (left B1) after its INSERT.
    const afterInsertInA = inA.slice(1).map((e) => ({ action: e.action, table: e.table_name, record: e.record_id }));
    expect(
      afterInsertInA,
      `chain ${chainA} holds only the INSERT of pack ${pk1}; the move to ${b2} is recorded only in ${chainB}`,
    ).toContainEqual(expect.objectContaining({ table: 'market.stub_pack', record: pk1 }));
  });
});

/**
 * Review reproducer F78: platform.create_aggregate_state (packages/kernel/sql/0550_platform_state_engine.sql,
 * line 398; the only definition, never replaced later) is granted to ebmr_app (0550 line 597) and checks
 * only platform.require_actor() (0500 line 21: "a context exists"). It never calls platform.authorize /
 * iam.require_permission, so any validated actor, including one whose role holds no GMP permission at all,
 * creates GMP state: an aggregate_state row, a state_history row attributed to that person, a BUSINESS audit
 * entry on the aggregate's chain and a 'state.created' outbox message. It can also pin any published machine
 * version (p_machine_version) and pre-empt the id a module will create later (EBMR-PLAT-063).
 *
 * DI-17 (authorization: every GMP write is checked against the actor's permissions) requires that a
 * CONTRACT_GIVER_REVIEWER (K27, "Read-only access to completed records", holds only RECORD.READ) is
 * refused when it tries to create GMP state.
 *
 * Steps (all as ebmr_app, through kernel.begin_command, exactly as the product would):
 *   1. Sanity: CONTRACT_GIVER_REVIEWER's only live permission is RECORD.READ, and machine sample_record has
 *      a published version (so the call is well-formed and cannot fail on EBMR-PLAT-060/065).
 *   2. Positive control: the same reviewer calls a gated platform writer (platform.set_setting, which runs
 *      platform.authorize('platform.settings.change')) with a reason and is refused with EBMR-PLAT-006. This
 *      proves the reviewer's command context is valid and that the AUTHORITY hook denies this role.
 *   3. The reviewer runs
 *        select platform.create_aggregate_state('sample_record', 'sample_record', <new uuid>)
 *      Safe behaviour asserted: the call is refused (for a reason other than a missing context or an unknown
 *      machine), and no aggregate_state row, state_history row or audit entry exists for that aggregate.
 *
 * With the defect, step 3 resolves (state DRAFT, version 1), and a state_history row with role_code
 * CONTRACT_GIVER_REVIEWER and a BUSINESS audit event on chain sample_record:<id> exist.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seededTestActor } from '../support/seeded-actor.ts';

let db: TestDatabase;
let reviewer: ActorContext;

beforeAll(async () => {
  db = await createTestDatabase();
  reviewer = await seededTestActor(db, { roleCode: 'CONTRACT_GIVER_REVIEWER', legalName: 'R. Reviewer' });
});

afterAll(async () => {
  await db.drop();
});

type Outcome = { ok: true; value: unknown } | { ok: false; message: string };

const settle = async (p: Promise<unknown>): Promise<Outcome> =>
  p.then(
    (value) => ({ ok: true as const, value }),
    (e: unknown) => ({ ok: false as const, message: e instanceof Error ? e.message : String(e) }),
  );

describe('F78: platform.create_aggregate_state is ungated (DI-17)', () => {
  it('[DI-17] a CONTRACT_GIVER_REVIEWER (RECORD.READ only) cannot create sample_record GMP state', async () => {
    // 1. Sanity: the role is read-only and the machine is published.
    const { rows: perms } = await db.admin.query<{ permission_code: string }>(
      `select permission_code from iam.role_permission
        where role_code = 'CONTRACT_GIVER_REVIEWER' and removed_at is null order by 1`,
    );
    expect(perms.map((p) => p.permission_code)).toEqual(['RECORD.READ']);
    const { rows: versions } = await db.admin.query<{ n: string }>(
      `select count(*)::text as n from platform.machine_version
        where machine_code = 'sample_record' and definition_hash is not null`,
    );
    expect(Number(versions[0]?.n)).toBeGreaterThan(0);

    // 2. Positive control: a gated platform writer refuses this reviewer through the AUTHORITY hook.
    const gated = await settle(
      withCommand(
        db.app,
        { ...reviewer, correlationId: randomUUID(), reasonCode: 'CONFIGURATION', reasonText: 'F78 positive control' },
        (c) => c.query("select platform.set_setting('time.drift_alarm_threshold_s', '1')"),
      ),
    );
    expect(gated.ok).toBe(false);
    expect(gated.ok ? '' : gated.message).toMatch(/EBMR-PLAT-006/);

    // 3. The reviewer tries to create GMP state for a new sample_record aggregate.
    const id = randomUUID();
    const outcome = await settle(
      withCommand(db.app, { ...reviewer, correlationId: randomUUID() }, async (c) => {
        const { rows } = await c.query<{ r: unknown }>(
          "select platform.create_aggregate_state('sample_record', 'sample_record', $1::uuid) as r",
          [id],
        );
        return rows[0]?.r;
      }),
    );

    const { rows: stateRows } = await db.admin.query<{ state: string }>(
      "select state from platform.aggregate_state where aggregate_type = 'sample_record' and aggregate_id = $1",
      [id],
    );
    const { rows: histRows } = await db.admin.query<{ role_code: string; person_id: string }>(
      "select role_code, person_id::text as person_id from platform.state_history where aggregate_type = 'sample_record' and aggregate_id = $1",
      [id],
    );
    const { rows: auditRows } = await db.admin.query<{ n: string }>(
      'select count(*)::text as n from kernel.audit_event where chain_key = $1',
      [`sample_record:${id}`],
    );

    // Safe behaviour: refused, and nothing was written in the reviewer's name.
    expect(
      outcome,
      `CONTRACT_GIVER_REVIEWER (RECORD.READ only) created sample_record:${id}: ${JSON.stringify(outcome)}; ` +
        `history ${JSON.stringify(histRows)}; audit events ${auditRows[0]?.n}`,
    ).toMatchObject({ ok: false });
    // The refusal must be an authorization refusal, not a missing context or an unknown machine.
    expect(outcome.ok ? '' : outcome.message).not.toMatch(/EBMR-PLAT-001|EBMR-PLAT-06[05]|EBMR-IAM-00[12]/);
    expect(stateRows).toHaveLength(0);
    expect(histRows).toHaveLength(0);
    expect(Number(auditRows[0]?.n)).toBe(0);
  });
});

/**
 * Review reproducer F79: site-scoped qualification requirements fail open when the authority request
 * carries no site.
 *
 * iam.evaluate_authority (packages/kernel/sql/0130_iam_qualifications_authority.sql, line 238; the only
 * definition) applies a qualification requirement only when
 *   iam.scope_covers(q.scope_site, q.scope_area, q.scope_product, v_scope)
 * holds. scope_covers (0100 line 108) is false when the requirement names a site and the request does
 * not. For grants that is fail-closed (no grant, no authority); for requirements it is fail-open (the
 * requirement is silently skipped, so the training gate does not block). esig.sign (0230 line 425)
 * evaluates in the provider's scope, which is '{}' whenever the provider returns no site.
 *
 * INV-26 / DI-21 / IN-04: every signer held the required qualification at that instant; a lapse is a
 * hard block naming the missing item; the training gate is never relaxed (every site is India-licensed).
 *
 * Setup (all through the product's own functions, as ebmr_app inside kernel.begin_command):
 *   - TRAINING_COORDINATOR creates qualification type SOP-VERIFY-xxxx and a requirement on permission
 *     STEP.VERIFY limited to site SITE-1 (the installation's site; every seeded terminal is registered there).
 *   - A VERIFIER with an installation-wide grant, whose terminal is at SITE-1, never receives that
 *     qualification.
 *
 * Positive controls (prove the requirement is live and the verifier lacks it):
 *   - evaluate_authority(verifier, 'STEP.VERIFY', {"site":"SITE-1"}, role VERIFIER) -> refused,
 *     MISSING_QUALIFICATION:<code>;
 *   - VERIFIED on a stub entry carrying site SITE-1 -> EBMR-ESIG-040 MISSING_QUALIFICATION.
 *
 * Safe behaviour asserted (fails with the defect):
 *   1. evaluate_authority(verifier, 'STEP.VERIFY', '{}', role VERIFIER) is also refused with
 *      MISSING_QUALIFICATION:<code> (with the defect: allowed = true, reasons = []).
 *   2. The same verifier, at the same SITE-1 terminal, signing VERIFIED on a stub entry whose provider
 *      returns no site is refused with EBMR-ESIG-040 MISSING_QUALIFICATION, and no VERIFIED signature is
 *      stored (with the defect: the signature is applied and stored).
 */
import { randomBytes } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { withCommand } from '../../src/db/command.ts';
import { evaluateAuthority } from '../../src/identity/authority.ts';
import { createStub, ensureSealKey, run, signStub } from '../esig/helpers.ts';
import { SEED_SITE, seedActor, withReason, type SeededActor } from '../identity/seed.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';

let db: TestDatabase;
let tc: SeededActor;
let op: SeededActor;
let verifier: SeededActor;
let code: string;

type Outcome = { ok: true; value: unknown } | { ok: false; message: string };

const settle = async (p: Promise<unknown>): Promise<Outcome> =>
  p.then(
    (value) => ({ ok: true as const, value }),
    (e: unknown) => ({ ok: false as const, message: e instanceof Error ? e.message : String(e) }),
  );

beforeAll(async () => {
  db = await createTestDatabase();
  await ensureSealKey(db);
  tc = await seedActor(db, { roleCode: 'TRAINING_COORDINATOR', acknowledgeEsig: false });
  op = await seedActor(db, { roleCode: 'OPERATOR', legalName: 'F79 Operator' });
  // Installation-wide VERIFIER grant (scope {}), terminal registered at SITE-1; no qualification recorded.
  verifier = await seedActor(db, { roleCode: 'VERIFIER', legalName: 'F79 Unqualified Verifier' });

  code = `SOP-VERIFY-${randomBytes(2).toString('hex').toUpperCase()}`;
  await withCommand(db.app, withReason(tc), async (c) => {
    await c.query("select iam.create_qualification_type($1, 'Verification SOP', 'current version of the SITE-1 verification SOP')", [code]);
    await c.query("select iam.add_qualification_requirement($1, null, 'STEP.VERIFY', $2::jsonb, 'site SOP')", [
      code,
      JSON.stringify({ site: SEED_SITE }),
    ]);
  });
});

afterAll(async () => {
  await db.drop();
});

async function stubEntry(site: string | null): Promise<string> {
  if (site === null) return createStub(db, op);
  return run(db, op, async (c) => {
    const { rows } = await c.query<{ id: string }>(
      "insert into esig.stub_signable (kind, title, value, unit, site) values ('STEP', 'Granulation: binder added', '12.503', 'kg', $1) returning id",
      [site],
    );
    return rows[0]?.id ?? '';
  });
}

async function verifiedCount(id: string): Promise<number> {
  const { rows } = await db.admin.query<{ n: string }>(
    "select count(*)::text as n from esig.signature where aggregate_ref = $1 and meaning_code = 'VERIFIED'",
    [`esig_stub:${id}`],
  );
  return Number(rows[0]?.n ?? '0');
}

describe('F79: site-scoped qualification requirements are skipped when the request has no site (INV-26, DI-21, IN-04)', () => {
  it('sanity: the requirement is live, the verifier is unqualified, holds an installation-wide grant and works at a SITE-1 terminal', async () => {
    const req = await db.admin.query<{ permission_code: string; scope_site: string | null }>(
      'select permission_code, scope_site from iam.qualification_requirement where qualification_code = $1 and effective_to is null',
      [code],
    );
    expect(req.rows).toEqual([{ permission_code: 'STEP.VERIFY', scope_site: SEED_SITE }]);
    const pq = await db.admin.query('select 1 from iam.person_qualification where person_id = $1 and qualification_code = $2', [verifier.personId, code]);
    expect(pq.rows).toHaveLength(0);
    const g = await db.admin.query<{ role_code: string; scope_site: string | null }>('select role_code, scope_site from iam.role_grant where id = $1', [
      verifier.seed.grantId,
    ]);
    expect(g.rows).toEqual([{ role_code: 'VERIFIER', scope_site: null }]);
    const dev = await db.admin.query<{ site_code: string }>('select site_code from iam.device where id = $1', [verifier.deviceId]);
    expect(dev.rows).toEqual([{ site_code: SEED_SITE }]);
  });

  it('[INV-26][DI-21] iam.evaluate_authority: an installation-wide request does not skip the SITE-1 training requirement', async () => {
    // Positive control: in scope SITE-1 the requirement applies and the verifier is refused.
    const atSite = await evaluateAuthority(db.app, {
      personId: verifier.personId, accountId: verifier.accountId, permission: 'STEP.VERIFY', scope: { site: SEED_SITE }, roleCode: 'VERIFIER',
    });
    expect(atSite).toMatchObject({ allowed: false, reasons: [`MISSING_QUALIFICATION:${code}`] });

    // Same person, same permission, same role, no site in the request.
    const noSite = await evaluateAuthority(db.app, {
      personId: verifier.personId, accountId: verifier.accountId, permission: 'STEP.VERIFY', scope: {}, roleCode: 'VERIFIER',
    });
    expect(
      noSite,
      `unqualified VERIFIER evaluated in scope {} for STEP.VERIFY: ${JSON.stringify(noSite)} ` +
        `(in scope {"site":"${SEED_SITE}"} the same evaluation was ${JSON.stringify(atSite)})`,
    ).toMatchObject({ allowed: false, reasons: [`MISSING_QUALIFICATION:${code}`] });
  });

  it('[INV-26][IN-04] esig.sign: an unqualified verifier cannot sign VERIFIED on an entry whose provider returns no site', async () => {
    // Positive control: the entry carries site SITE-1, the provider returns scope {"site":"SITE-1"} and the
    // training gate refuses the unqualified verifier.
    const sited = await stubEntry(SEED_SITE);
    await signStub(db, op, sited, { meaning: 'PERFORMED' });
    const control = await settle(signStub(db, verifier, sited, { meaning: 'VERIFIED' }));
    expect(control.ok).toBe(false);
    expect(control.ok ? '' : control.message).toMatch(/EBMR-ESIG-040/);
    expect(control.ok ? '' : control.message).toContain(`MISSING_QUALIFICATION:${code}`);
    expect(await verifiedCount(sited)).toBe(0);

    // The same step without a site on the entry (provider scope {}), signed at the same SITE-1 terminal.
    const unsited = await stubEntry(null);
    await signStub(db, op, unsited, { meaning: 'PERFORMED' });
    const outcome = await settle(signStub(db, verifier, unsited, { meaning: 'VERIFIED' }));
    const stored = await verifiedCount(unsited);
    const evals = await db.admin.query<{ scope: object; allowed: boolean; reasons: string[] }>(
      `select e.scope, e.allowed, e.reasons from esig.signature s join iam.authority_evaluation e on e.id = s.authority_evaluation_id
        where s.aggregate_ref = $1 and s.meaning_code = 'VERIFIED'`,
      [`esig_stub:${unsited}`],
    );

    expect(
      outcome,
      `unqualified VERIFIER signed VERIFIED on esig_stub:${unsited} from a ${SEED_SITE} terminal: ${JSON.stringify(outcome)}; ` +
        `stored VERIFIED signatures: ${stored}; authority evaluation used: ${JSON.stringify(evals.rows)}`,
    ).toMatchObject({ ok: false });
    expect(outcome.ok ? '' : outcome.message).toMatch(/EBMR-ESIG-040/);
    expect(outcome.ok ? '' : outcome.message).toContain(`MISSING_QUALIFICATION:${code}`);
    expect(stored).toBe(0);
  });
});

/**
 * Review reproducer F80: market.evaluate_stub_scope (0330) derives the market set and predicates of
 * a stored evaluation from the scope, and refuses a predicate the scope fixes (EBMR-MKT-055), but it
 * passes the site as coalesce(p_req -> 'siteId', <scope's site>). market.evaluation_complete then
 * applies the site value of whatever site the caller named. A PRODUCT scope (a batch) fixes its site
 * (stub_batch.site_id), so an evaluation of batch B must apply B's own site value.
 *
 * Setup: the IN-52 stub world. Batch T-IN (site S1, markets {IN}) resolves
 * tablets.compression.ipcSampleMaxInterval to 30 min. S1 holds a TIGHTER site value of 20 min.
 * A second site S2 holds its own TIGHTER value of 25 min (tighter than the table, looser than S1).
 *
 * Safe behaviour asserted: an OPERATOR (MARKET.RULE_EVALUATE) evaluating batch T-IN cannot obtain
 * a stored evaluation of T-IN that applies another site: a request naming a random site id or S2 is
 * either refused, or stored with site_id = S1, SITE_TIGHTER and effective value 20.
 *
 * Positive control: without a siteId override T-IN is stored with site S1, SITE_TIGHTER, 20.
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { evaluateStubScope, setSiteValue, type EvaluateStubScopeRequest, type StoredEvaluation } from '../../src/market/repository.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { asApp, MARKET_ROLES, publishSeedTables, seedStubWorld, type StubWorld } from '../market/helpers.ts';

let db: TestDatabase;
let world: StubWorld;
let site2: string;

const KEY = 'tablets.compression.ipcSampleMaxInterval';
const AS_OF = '2026-03-01';

beforeAll(async () => {
  db = await createTestDatabase();
  await publishSeedTables(db);
  world = await seedStubWorld(db);
  // A second site (same installation) with its own, less tight, site value.
  site2 = await asApp(
    db,
    async (c) => {
      const { rows } = await c.query<{ id: string }>('insert into market.stub_site (code, markets) values ($1, $2) returning id', [
        `SITE2-${randomUUID().slice(0, 8)}`,
        ['IN'],
      ]);
      return rows[0]?.id ?? '';
    },
    { roleCode: MARKET_ROLES.stubs },
  );
  const s1 = await asApp(db, (c) => setSiteValue(c, { siteId: world.siteId, key: KEY, value: '20', effectiveFrom: '2026-01-01' }), {
    roleCode: MARKET_ROLES.siteValues,
  });
  expect(s1.outcome).toBe('TIGHTER');
  const s2 = await asApp(db, (c) => setSiteValue(c, { siteId: site2, key: KEY, value: '25', effectiveFrom: '2026-01-01' }), {
    roleCode: MARKET_ROLES.siteValues,
  });
  expect(s2.outcome).toBe('TIGHTER');
});

afterAll(async () => {
  await db.drop();
});

/** Evaluate as an OPERATOR (MARKET.RULE_EVALUATE). */
function evaluate(request: EvaluateStubScopeRequest): Promise<StoredEvaluation> {
  return asApp(db, (c) => evaluateStubScope(c, request), { roleCode: MARKET_ROLES.evaluator });
}

/** A short description of the stored evaluation, or the refusal code. */
async function attempt(p: Promise<StoredEvaluation>): Promise<string> {
  try {
    const e = await p;
    const site = e.siteId === world.siteId ? 'S1' : e.siteId === site2 ? 'S2' : e.siteId === null ? 'none' : 'foreign';
    return `stored subject=${e.subjectId === world.batch.tabletIn ? 'T-IN' : e.subjectId} site=${site} outcome=${e.siteOutcome} effective=${JSON.stringify(e.effectiveValue)}`;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return `REFUSED ${/EBMR-[A-Z]+-\d+/.exec(message)?.[0] ?? message}`;
  }
}

const SAFE_STORED = 'stored subject=T-IN site=S1 outcome=SITE_TIGHTER effective="20"';
const safe = (r: string): string => (r.startsWith('REFUSED') || r === SAFE_STORED ? 'SAFE' : r);

describe('F80: an evaluation of a batch applies the batch\'s own site value', () => {
  it('[INV-29][IN-52] a siteId in the request cannot replace the site the batch scope fixes', async () => {
    const base = { key: KEY, scope: { kind: 'PRODUCT' as const, id: world.batch.tabletIn }, resolutionPoint: 'EXECUTION' as const, asOf: AS_OF };

    // Positive control: the scope's own site S1 gives SITE_TIGHTER, 20.
    const control = await attempt(evaluate(base));
    expect(control).toBe(SAFE_STORED);

    // Attack 1: a random site id -> the batch's tighter site value is dropped (NO_SITE_VALUE, 30).
    const randomSite = await attempt(evaluate({ ...base, siteId: randomUUID() }));
    // Attack 2: another site's looser (but still "TIGHTER") value -> 25 instead of 20, looks legitimate.
    const otherSite = await attempt(evaluate({ ...base, siteId: site2 }));

    expect({ randomSite: safe(randomSite), otherSite: safe(otherSite) }).toEqual({ randomSite: 'SAFE', otherSite: 'SAFE' });
  });
});

/**
 * Review reproducer F81: INV-27 says user IDs (login names) are never reused, including after a
 * restore. The only record of issued login names is iam.issued_identifier (0110), which lives in the
 * database. After a restore from a backup taken before a login name was issued, the name is gone
 * from the register; continuity.after_restore (0600) moves sequences and counters past the external
 * ledger's high-water marks but nothing brings back issued identifiers, so iam.create_account lets
 * an administrator issue the same login name to a different person.
 *
 * Scenario (the restore procedure is followed exactly as in continuity/restore.test.ts):
 *   T0  backup of the source database (persons X and Y exist, both identity-verified).
 *   T1  administrator creates and activates account <jdoe> for person X; an anchor is exported to
 *       the external ledger afterwards (normal periodic anchoring).
 *   --  disaster: the T0 backup is restored into a new database.
 *   --  restore event recorded by an operator, approved (signed) by a second person, completed.
 *   T2  administrator creates an account for person Y with login name <jdoe>.
 *
 * Safe behaviour asserted: T2 is refused (EBMR-IAM-021, the login name was issued before and is never
 * issued again). With the defect, T2 succeeds and <jdoe> now denotes person Y.
 */
import { randomBytes, randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { exportAnchor } from '../../src/continuity/anchors.ts';
import type { BackupArtefact } from '../../src/continuity/backup-drill.ts';
import type { FileLedger } from '../../src/continuity/ledger.ts';
import { approveRestoreEvent, completeRestore, recordRestoreEvent } from '../../src/continuity/restore.ts';
import { withCommand, type ActorContext } from '../../src/db/command.ts';
import { activateAccount, createAccount, createPerson, recordIdentityVerification } from '../../src/identity/admin.ts';
import { createTestDatabase, type TestDatabase } from '../support/db.ts';
import { seedAdministration, withReason, type SeedAdministration, type SeededActor } from '../identity/seed.ts';
import { backupTestDatabase, dbTime, ensureSealKey, restoreCopy, signerActor, signFor, tempDir, tempLedger, testActor } from '../continuity/helpers.ts';

const dir = tempDir('f81');
let source: TestDatabase;
let restored: TestDatabase;
let ledger: FileLedger;
let adm: SeedAdministration;
let operator: ActorContext;
let approver: SeededActor;
let backup: BackupArtefact;
let personX: string;
let personY: string;
let accountX: string;
const jdoe = `jdoe-${randomBytes(4).toString('hex')}`;

const asAdmin = <T>(db: TestDatabase, work: Parameters<typeof withCommand<T>>[2]) => withCommand(db.app, withReason(adm.admin), work);

async function newVerifiedPerson(db: TestDatabase, name: string): Promise<string> {
  return asAdmin(db, async (c) => {
    const p = await createPerson(c, 'NATURAL', name, `EMP-${randomUUID()}`);
    await recordIdentityVerification(c, {
      personId: p,
      purpose: 'INITIAL',
      method: 'IN_PERSON_DOCUMENT',
      documentType: 'Passport',
      evidenceRef: `HR-${randomUUID()}`,
      occurredAt: '2026-01-05T09:00:00Z',
    });
    return p;
  });
}

beforeAll(async () => {
  source = await createTestDatabase();
  ledger = tempLedger('f81-source', dir.path);
  adm = await seedAdministration(source);
  operator = await testActor(source, { roleCode: 'SYSTEM_ADMINISTRATOR', legalName: 'Restore Operator' });
  approver = await signerActor(source, 'QA_REVIEWER', 'QA Approver');
  await ensureSealKey(source);

  personX = await newVerifiedPerson(source, 'Person X');
  personY = await newVerifiedPerson(source, 'Person Y');
  await exportAnchor(source.app, ledger);

  // T0: the backup.
  backup = await backupTestDatabase(source, dir.path);

  // T1: after the backup, login name jdoe is issued to person X (and anchored externally).
  accountX = await asAdmin(source, async (c) => {
    const a = await createAccount(c, { personId: personX, loginName: jdoe, kind: 'HUMAN' });
    await activateAccount(c, a);
    return a;
  });
  await exportAnchor(source.app, ledger);

  // The disaster: the T0 backup is restored into a new database.
  restored = await restoreCopy(source, backup, dir.path);
}, 120_000);

afterAll(async () => {
  await restored?.drop();
  await source?.drop();
  dir.cleanup();
});

describe('F81: login names after a restore (INV-27 user-ID part)', () => {
  it('[INV-27] a login name issued in the lost window is not issued to another person after the restore procedure', async () => {
    // Preconditions: in the source, jdoe denotes person X; the restored copy predates it.
    const src = await source.app.query<{ person_id: string }>('select person_id from iam.account where login_name = $1', [jdoe]);
    expect(src.rows.map((r) => r.person_id)).toEqual([personX]);
    const reg = await source.app.query<{ account_id: string }>('select account_id from iam.issued_identifier where identifier = $1', [jdoe]);
    expect(reg.rows.map((r) => r.account_id)).toEqual([accountX]);
    // Positive control: without a restore, reusing jdoe for person Y is refused.
    await expect(asAdmin(source, (c) => createAccount(c, { personId: personY, loginName: jdoe, kind: 'HUMAN' }))).rejects.toThrow('EBMR-IAM-021');

    // The full restore procedure: recorded by the operator, approved (signed) by a second person, completed.
    const recorded = await recordRestoreEvent(restored.app, operator, ledger, {
      eventKind: 'FULL_RESTORE',
      backupId: backup.backupId,
      backupTakenAt: backup.snapshotTakenAt,
      restorePoint: backup.snapshotTakenAt,
      performedAt: await dbTime(restored),
      reason: 'Primary storage failure; restored from the last good backup',
      changeReference: 'INC-2026-0081',
      approverPersonIds: [approver.personId],
    });
    const signature = await signFor(restored, approver, { type: 'restore_event', id: recorded.restoreEventId }, 'RESTORE_APPROVED', 'RECORDED', { registerKey: false });
    await approveRestoreEvent(restored.app, approver, recorded.restoreEventId, signature);
    await completeRestore(restored.app, operator, ledger, recorded.restoreEventId);
    const status = await restored.app.query<{ status: string }>('select status from continuity.restore_event_status where id = $1', [recorded.restoreEventId]);
    expect(status.rows[0]?.status).toBe('COMPLETED');

    // T2: an administrator issues login name jdoe to person Y. INV-27: it must be refused.
    const reuse = asAdmin(restored, (c) => createAccount(c, { personId: personY, loginName: jdoe, kind: 'HUMAN' }));
    await expect(reuse).rejects.toThrow('EBMR-IAM-021');

    const now = await restored.app.query<{ person_id: string }>('select person_id from iam.account where login_name = $1', [jdoe]);
    expect(now.rows.map((r) => r.person_id)).not.toContain(personY);
  });
});
